INSERT INTO Definition
(word_id,language_id,pos_id,definition,example)
VALUES
(1051,3,4,'ပေးသည်။','“အဲကဵုကုဍေံ သြန်စှ်ဒကေဝ်ရ။” = “သူ့အား ငွေတစ်ဆယ်ကျပ် ကျွန်မပေးသည်။”')
,(1051,3,3,'နှင့်။','ပုၚ်ကဵုသွ = ထမင်းနှင့်ဟင်း။ မိကဵုမ = အမိနှင့်အဖ။')
,(1051,3,9,'၁။ (ကြိရှေ့ဆက်) ဖြစ်စေခြင်းကိုပြသည်။ ကာရိုက်ကြိယာဖြစ်စေသည်။','ကဵုစဴ = ပြန်စေသည်။ ကဵုလလံသွာ = ပျောက်ပြယ်စေသည်။ ကဵုကၠောန် = လုပ်စေသည်။')
,(1051,3,9,'၂။ (ကြိနောက်ဆက်) သူတစ်ပါးအတွက် ဆောင်ရွက်သည့်သဘောကို ပြသောစကားလုံး။','ဟီုကဵု = ပြောပေးသည်။ || ကၠောန်ကဵု = လုပ်ပေးသည်။')
,(1051,3,9,'၃။ (ကြိဝိဖြစ်စေသော ကြိရှေ့ဆက်)','“ပတၠသမ္တီ သ္ၚဳကဵုဂၠိၚ် ညာတ်ကဵုသ္ၚောဲညိ။” = “အသိဉာဏ်ရှိသူဖြစ်လျက် အရှည်ကိုကြည့်၍ အဝေးကိုမြင်နိုင်ပါစေ။” (ကဵု × ဂၠိၚ်) “အာကဵုပြဟ်ရ။” = “မြန်မြန်သွားပါ။” (ကဵု × ပြဟ်)')
,(1053,3,4,'အကြံပေးသည်။',null)
,(1054,3,4,'ရိုက်နှက်ဒဏ်ပေးသည်။ ရိုက်ပုတ်သည်။','‘ကဵုဒွဵု’ လည်းရှု။')
,(1055,3,4,'ရိုက်နှက်အပြစ်ပေးသည်။ ရိုက်ပုတ်ဒဏ်ခတ်သည်။','“ယဝ်ဍေံဟွံသုၚ်ဂဥုဲဂှ်မ္ဂး နဇုက်ဗၜန်ဂှ်ကဵုဒှ်၊ နဇုက်စၞာံဂှ်ကဵုဒှ်၊ နကၞာၚ်ဆုဂှ်ကဵုဒှ်၊ — နမမိက်မွဲမွဲဂှ် ဂိုၚ်ကေတ်တုဲ ဂိုၚ်ဂြဲနၚ် ဂြဲဏာတုဲ ကဵုကွိုက်ကဵုဒွဵုကဵုဍေံရ။” (ဇ—၁၃ဝ။ အစွောံ။) = “ဆေးကို အကယ်၍မသောက်အံ့၊ ထိုပုဏ္ဏေးမကို ကြိုးဖြင့်၄င်း လွန်ဖြင့်၄င်း သစ်ခက်ဖြင့်၄င်း ၚၚ်၍ ရိုက်ခတ်ကောင်းသောအရာ­ ရိုက်ခတ်၍ ဆံတို့­ဆွဲငင်၍ တတောင်ဖြင့်ထောင်းလေလော့။” (ညောင်ကန်)')
,(1056,3,4,'ကတိပေးသည်။ နှုတ်ဖြင့်ကတိပြုသည်။',null)
,(1057,3,4,'လမ်းခင်းပေးသည်။ လမ်းကြောင်းပေးသည်။',null)
,(1058,3,4,'ထိမ်းမြားပေးစားသည်။','“ကောန်ဝုတ်ညးဂှ် ညးကဵုစကဵုမာံထဝ်ဏောၚ်။” = “သူ့သမီးကို မောင်ထော်နှင့် သူထိမ်းမြားပေးစားမည်။”')
,(1059,3,4,'(သဘောတူညီမှုကို လေးနက်စေရန်) သစ္စာပြုသဘောဖြင့် အဘိုးတန်ဝတ္ထုတစ်စုံ တစ်ရာကိုပေးသည်။ (?)','“ဗၞိက်ပ္ဍဲက္ၜၚ်ဝွံ လ္ပသွံကဵုညးသ္အာၚ်ညိ” မၚ်ဗၠာဲဂးတုဲ လစိန်မွဲ မၚ်ဗၠာဲ ကဵုစရံက် ကုဇမၞော်က္ၜၚ်ဂှ်ရ။ = “သၚ်္ဘောရှိကုန်ပစ္စည်းတို့ကို တစ်ပါးသူတို့အား မရောင်းပါနှင့်” ဟုဆိုကာ လုလင်သည် သၚ်္ဘောသူကြီးအား သစ္စာပြုဖြစ်သော တစ်ခုသောလက်စွပ်ကို ပေး၏။')
,(1060,3,4,'အလိုလိုက်သည်။','“ကောန်ၚာ်ဏအ် လ္ပကဵုစိုတ်ဂၠိုၚ်၊ ကဵုစိုတ်ဂၠိုၚ် တိုန်က္ဍိုပ်ရောၚ်။” = “ဤကလေးကို သိပ်အလိုမလိုက်ပါနှင့်၊ အလိုလိုက်ပါများလျှင် ခေါင်းပေါ်တက်လိမ့်မည် (ဝါ) ရောင့်တက်လိမ့်မည်။”')
,(1061,3,4,'လက်ဆောင်ပဏ္ဏာဆက်သည်။ လက်ဆောင်ပေးသည်။',null)
,(1062,3,4,'အားပေးသည်။',null)
,(1063,3,4,'လက်ဖြင့်အချက်ပြသည်။ အချက်ပေးသည်။','“ညံၚ်အဲဂွံစဴအာသ္ၚိဂှ် နူဇမ္ၚောဲအပါကဵုတဲ ကဵုအဲရ။” = “ကျွန်တော်အိမ်ပြန်သွားရန် ကျွန်တော့်ကို အဝေးမှ လက်ဖြင့် အဖေအချက်ပြသည်။”')
,(1064,3,4,'လက်ဆောင်ပေးသည်။',null)
,(1065,3,4,'စရန်ပေးသည်။',null)
,(1066,3,4,'ဒုက္ခပေးသည်။','“ဗှ်ေဟွံမိက်ရီုဗၚ်အဲမ္ဂး လ္ပရီုဗၚ်၊ လ္ပကဵုဒဒိုက်ကဵုအဲညိ။”= “ငါ့ကို နင်မကူညီချင်လျှင် မကူညီဘဲနေပါ၊ ငါ့ကို ဒုက္ခမပေးပါနှင့်။”')
,(1067,3,4,'စိတ်ဒုက္ခပေးသည်၊ စိတ်ဆင်းရဲစေသည်။','“ကောန်သမၠီု ကဵုဒဒိုက်စိုတ်ကဵုမိမလၟိုန်ရ။” = “မိုက်သောသားသမီးသည် မိဘတို့ကို အမြဲစိတ်ဆင်းရဲအောင်လုပ်၏။”')
,(1068,3,4,'ပြစ်ဒဏ်ပေးသည်။',null)
,(1069,3,4,'အလှူပေးသည်။ ဒါနပြုသည်။',null)
,(1070,3,4,'အသက်ကို ချမ်းသာပေးသည်။','“ပွကမၠတ်ဂှ် အဲဟွံပကြဴရ။ လ္ပဂစိုတ်အဲညိ။ ကဵုဒါန်လမျီုကုအဲမွဲဝါညိ။” = “ခိုးခြင်းအမှုကို နောင်ကိုအကျွန်ုပ်မပြုတော့ပါ။ အကျွန်ုပ်ကို မသတ်ပါနှင့်။ အကျွန်ုပ်ကို တစ်ကြိမ်တစ်ခါ အသက်ချမ်းသာခွင့်ပေးပါ။”')
,(1071,3,16,'ဖြစ်စေ။ ဖြစ်သော်လည်း။','“ဍေံဟွံအာကဵုဒှ်၊ ဗှ်ေဒးအာရောၚ်။” = “သူ မသွားသည်ဖြစ်စေ၊ နင်သွားရမည်။”')
,(1072,3,16,'ဖြစ်စေ—ဖြစ်စေ။ သော်လည်းကောင်း—သော်လည်းကောင်း။','“စကဵုဒှ် တိက်ကဵုဒှ် ကဵုတီပယာံကာလညိ။” = “စားသည်ဖြစ်စေ အိပ်သည်ဖြစ်စေ အချိန်ကာလကို သိပါစေ” || “ဗှ်ေကဵုဒှ် အဲကဵုဒှ် နွံကဵုစိုတ်ဖအိုတ်ရ။” = “သင်သည်လည်းကောင်း ငါသည်လည်းကောင်း စိတ်ရှိကြသည်ချည်းဖြစ်သည်။”')
,(1073,3,4,'အပြစ်ပေးသည်။ ဒဏ်ခတ်သည်။',null)
,(1074,3,4,'ရိုက်နှက်သည်။ သတ်ပုတ်သည်။','“ညးရပ်ဂွံကၠေံကမၠတ်ဂှ်တုဲ ကဵုဒွဵုတၟာဂစိုတ်ရ။” = “သူခိုးအားဖမ်းမိပြီး သေလုနီးပါးမျှ ရိုက်နှက်ဒဏ်ခတ်၏။”')
,(1075,3,4,'အိပ်မက်ပေးသည်။',null)
,(1076,3,4,'နည်းပေးသည်။ နည်းနာပေးသည်။ နည်းလမ်းပြသည်။',null)
,(1077,3,4,'သတင်းပေးသည်။ အကြောင်းကြားသည်။',null)
,(1078,3,4,'ငြာသံပေးသည်။ ဟစ်အော်အသံပြုသည်။','“သၟိၚ်သီုအမာတ်လ္ၚီ ညာတ်ကၠဵုတံဂှ်တုဲ မွဲဒမြိပ်ကဵုပါၚ်တုဲ ကၠဵုဂမၠိုၚ်လကိုတ်ဒြေပ်ဒဴအာအိုတ်ရ။” (ဇ—၅၁။ အစွောံ။) = “ထိုမြေခွေးတို့ကိုမြင်ကုန်၍ မင်းသည်၄င်း အမတ်တို့သည်၄င်း တပြိုင်နက်လျှင် အသံပြုကုန်၏။ မြေခွေးတို့သည် ကြောက်ကုန်သည်ဖြစ်၍ ပြေးကုန်၏။” (ညောင်ကန်)')
,(1078,3,4,'ငြာသံပေးသည်။ ဟစ်အော်အသံပြုသည်။','“သၟိၚ်ကလိၚ်ဖေက်ဒဴအာအိုတ်တုဲ ဗဵုပၞာန်သၟိၚ်အဿကတံဝွံ တက်ကၞက်ကဵုပါၚ် ဂအတ်ရမျှာၚ် လလောၚ်ကြီုတဴရ၊ တိဇၞော်ညံၚ်မပြဵုအာကီုရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “ကာလိၚ်္ဂမင်းသည် ရှုံး၍ပြေး၏။ ကာလိၚ်္ဂမင်းပြေးသည်ကိုမြင်၍ (အဿကမင်း၏ စစ်သည်ဗိုလ်ပါတို့သည်) ပဲ့တင်ထပ်အောင် ကြော်ငြာကုန်၏။” (ညောင်ကန်)')
,(1079,3,4,'ပညာပေးသည်။',null)
,(1080,3,4,'ပဋိညာဉ်ပေးသည်။ သဘောတူသည်။ ခွင့်ပေးသည်။',null)
,(1081,3,4,'(ရဟန်း) ဆွမ်းဘုဉ်းသည်။',null)
,(1082,3,4,'အကျိုးပေးသည်။','“ဓဝ်စၞာဲဂှ် ကဵုဖဵုတုဲ ဒုဟ်စၞာဲဂှ်လေဝ်မံက် မအံက်ဇကုလေဝ်တူ—။” (ဇ—၉၈။ အစွောံ။) = “စဉ်းလဲခြင်းတရားက အကျိုးပေး၍ စဉ်းလဲခြင်းအပြစ်သည်လည်း ထင်ရှား၊ မိမိဖခင်လည်းမီးလောင်—။”')
,(1083,3,4,'မျက်ရိပ်ပြသည်။ မျက်စပစ်သည်။','“(ကၞုဲကၠတ်လဝ်ဂွါကၟက်ကအ်ဂှ်) မၞိဟ်ဂမၠိုၚ် ညာတ်တုဲ ကဵုတဲကဵုမတ်ရၚ်သ္ကံတုဲ ပန်ဗရုသေနာတ်,ကဵုပါၚ် သီုညးဖအိုတ်တုဲ ကၞုဲဂှ်ဖေက်လကိုတ် ဗိုတ်ထောံဂွါကၟက်ကအ်ဂှ်တုဲ ဒြေပ်ဒဴအာကၠေံရ။” (ဇ—၉၂။ အစွောံ။) = “လည်ဆွဲတန်ဆာကို ခိုးယူထားသောမျောက်ကို လူများမြင်သည်ရှိသော် လက်ဖြင့်လည်းကောင်း မျက်စိဖြင့်လည်း ကောင်း အချင်းချင်းအချက်ပေး၍ အားလုံးတစ်ပြိုင်နက် သေနတ်ပစ်ဖောက် ဟစ်သံပေးသဖြင့် ထိုမျောက်ကြောက်လန့်၍ ထိုလည်ဆွဲတန်ဆာကို စွန့်ပစ်၍ပြေး၏။”')
,(1085,3,4,'အမည်ပေးသည်။ အမည်မှည့်သည်။',null)
,(1086,3,4,'အသံပေးသည်။ အသံပြုသည်။',null)
,(1087,3,4,'ဆုပေးသည်။ ဆုလာဘ်ပေးသည်။',null)
,(1088,3,4,'ဆုပေးသည်။ အာဏာပေးသည်။',null)
,(1089,3,4,'တာဝန်ပေးသည်။ တာဝန်အပ်နှင်းသည်။',null)
,(1090,3,4,'သတိပေးသည်။ သတိတရားရစေသည်။',null)
,(1091,3,4,'ကောင်းချီးပေးသည်။ သြဘာပေးသည်။','“(ဗောဓိသတ်တွံဓဝ်တုဲဂှ်) မၞိဟ်ဒေဝတဴတံ ကဵုတဴသာဓုကာ ဂြီုဂြီုအိုတ်ရ။” (ဇ—၅၃၆။ အစွောံ။) = “ဘုရားလောင်းတရားဟောပြီးသော် လူနတ်အပေါင်းတို့သည် တစ်ပြိုင်နက်သောအသံဖြင့် ကောင်းချီးပေးကြကုန်၏။” || “(ဇနပဒကလျာဏဳလှ်ေဒယှ်ေဂှ်) မှာဇန်တံဂမၠိုၚ် ဂွံမိၚ်ဂွံညာတ်တုဲ တက်တဲသဝဲယာတ် ကဵုသာဓုကာ ပူဇဴသကာရိုဟ်ဟွံမာန်ရ။” (ဇ—၉၆။ အစွောံ။) = “ဇနပဒကလျာဏီ သီဆိုကပြသည်ကို ကြားရ မြင်ရကုန်သော လူပရိသတ်အပေါင်းတို့သည် လက်ခုပ်တီး၍၄င်း အဝတ်ကိုဝှေ့ယမ်း၍၄င်း သြဘာပေးကြကုန်၍ ဆုလာဘ်ပူဇော်သက္ကာရသည် မရေမတွက်နိုင်။” || “(ဂွံညာတ်အသဝ်ကွတ်တ္ၚ ဗောဓိသတ်တုဲ) မှာဇန်ဂမၠိုၚ် — တက်ကၞက်ကြီုဇာ တက်တဲသဝဲယာတ် ကဵုတဴသာဓုကာ—။” (ဇ—၁၈၁။ အစွောံ။) = “ဘုရားလောင်း၏ အံ့ဖွယ်သူရဲဖြစ်သော လေးအတတ်ကိုမြင်၍ လူသူပရိသတ်သည် လက်ပမ်းပေါက်ခတ် ကြုံးဝါးကုန်လျက် လက်ခုပ်တီး၍ ၄င်းအဝတ်ကိုဝှေ့ယမ်း၍၄င်း ကောင်းချီးသြဘာပေးကြကုန်၏။”')
,(1092,3,4,'သီလပေးသည်။',null)
,(1093,3,4,'အချက်ပေးသည်။ အမှတ်သညာပေးသည်။',null)
,(1094,3,4,'အသိပေးသည်။ အမှတ်သညာပေးသည်။','“ကလောန်ဂှ် မၞးကၠောန်တုဲဒှ်မ္ဂး ကဵုသမ္တီ ကဵုအဲညိ။” = “ထိုအလုပ်ကို သၚ်လုပ်ပြီးစီးလျှင် ကျွန်ုပ်ကို အသိပေးပါ။” || “(ဒေါၚ်ဗြဴဂှ်) ကဵု သမ္တီကောန်တြုံသၟိၚ်ရ။” (ဇ—၁၂၆။ အစွောံ။) = “ထိုနတ်ဝင်မသည် မင်းသားအား (ချိန်းဆို ထားသည့်အတိုင်းပြုရန်) အမှတ်သညာပေး၏။”')
,(1095,3,4,'အမှတ်သညာပေးသည်။ အချက်ပေးသည်။ အချက်ပြသည်။','“ကာလဂြောဝ် စိုပ်မုက်ရၚ်သၟိၚ်ဂှ်ဗက် ခဍာ်သုမုခ ကဵုသမ္တီအမှတ်ကဵုခဍာ်ဒစာံတံဂှ် (ကဵုပၠံၚ်စၞနူပ္ဍဲဂြောဝ်ဂှ်ရ။)”(ဇ— ၂၉၂။ အစွောံ။) = “မင်းနန်းရှေ့ရင်ပြင်သို့ မင်းစားတော်ကဲရောက်သည်နှင့် သုမုခကျီး (စစ်သူကြီး)သည် ရှစ်ခုသောကုန်ကျီး (သူရဲ) တို့ကို ထိုစားတော်ကဲထံမှ အစာကိုလုရန် အချက်ပေးလိုက်၏။”')
,(1096,3,4,'အသက်ကိုပေးသည်။ နှလုံးသားကိုပေးသည်။ အသက်တမျှ တန်ဖိုးထားသည်။','“နွံကောန်ဂကူမွဲ ပဒတဴပ္ဍဲဍုၚ်သာရဝှ်ရ။ ကဵုသြိုဟ်ကဵုသာသနာတုဲ တိတ်ပခမဳရ။” (ဇ—၂၅၁။ အစွောံ။) = “သာဝတ္ထိပြည်­နေသော တယောက်သောအမျိုးသားသည် သာသနာတော်­ အသက်ကိုလှူသဖြင့် ရဟန်းပြု၍—။” (ညောင်ကန်)')
,(1097,3,4,'အခွင့်ပေးသည်။ အခွင့်ပြုသည်။',null)
,(1098,3,4,'ဘေးမဲ့ပေးသည်။','‘အဘယဒါန်’ လည်းရှု။')
,(1099,3,4,'အမိန့်ပေးသည်။',null)
,(1100,3,4,'အချက်ပေးသည်။','“ယာံက္ဍိုပ်ဒမၠဂှ် ကဵုအမှတ်သမ္တီဗက် ကောန်ရဲတအ်ဂှ် လုပ်ဗ္တိုက်ပၠံၚ်ၜးဒြပ် ပ္ဍဲဆေၚ်ဖျာဒမာတ်ထဝ်ဂှ်ရ။” = “ဓါးပြခေါင်းဆောင်က အချက်ပေးလိုက်သည်နှင့် နောက်လိုက်ဓါးပြတို့သည် ထိုရွှေပန်းထိမ်ဆိုင်ကို ဝင်ရောက်တိုက်ခိုက် လုယက်ကြသည်။”')
,(1101,3,4,'ခြောက်သည်။ ခြောက်သွေ့သည်။',null)
,(1102,3,4,'အလွန်ခြောက်သည်။ ကြွပ်သည့်တိုင်ခြောက်သည်။',null)
,(1103,3,4,'ခန်းခြောက်သည်။',null)
,(1104,3,4,'ပိန်ခြောက်သည်။ ကြုံလှီသည်။',null)
,(1105,3,4,'ကြွပ်ဆတ်သည်အထိခြောက်သည်။',null)
,(1106,3,1,'ခရေပန်း။','‘ကှ်ေ’ ရှု။')
,(1107,3,4,'၁။ မျောက်အော်သည်။',NULL)
,(1107,3,4,'၂။ အသံပြု၍ အချက်ပေးသည်။','ကုဟ်က္ညာၚ် = အော်၍ အချက်ပေးသည်။')
,(1108,3,1,'ခရေပင်။ ချယားပင်။ (ပါဠိ—ဗကုလ)','ပ္ကဴကှ်ေ = ခရေပန်း။')
,(1108,3,4,'ကညစ်ဖြင့် ပေရွက်ပေါ်တွင် စာရေးသားသည်။','ကှ်ေလိက် = စာရေးသည်။ ပေရွက်ပေါ်တွင်ရေးသည်။')
,(1109,3,9,'နားထောင်သူ၏အာရုံကို ဆွဲဆောင်ရန် သုံးသောစကား။ ကဲ။','“ကေဟ် — အာရ။” = “ကဲ—သွားတော့။”')
,(1110,3,4,'ကညစ်ဖြင့်ရေးသည်။',null)
,(1111,3,4,'ဇာတာဖွဲ့သည်။',null)
,(1112,3,4,'‘ကိုဟ်’ ရှု။',null)
,(1113,3,4,'ဖြူသည်။ ဖွေးသည်။','ဗုကိုဟ်၊ ဂွုကိုဟ်၊ ကိုဟ်ဂွု = ဖြူဖွေးသည်။')
,(1113,3,3,'ဖြူသော။','“(ပံက်စၞာဲဂှ် စကၠေံကမွဲကၟာ) ဗွဝ်ဇုတ်မကိုဟ်ဒၟံၚ် ဇရေၚ်တၞံဗလဲဂှ်။” (ဇ—၃၈။ အစွောံ။) = “ဗျိုင်းစဉ်းလဲသည် တစ်အိုင်လုံးမှငါးတို့ကို စားပစ်ကုန်၍ ငါးရိုးစုတို့သည် ရေသဖန်းပင်ရင်း­ ဖွေးနေ၏။” || “(ကလော်ဂှ်) မုက်ဍေံကိုဟ်ဂွု၊ ဇကုဍေံဒဝါန်၊ ဇိုၚ်တဲဍေံလစံက်—။” (ဇ—၅၅။ အစွောံ။) = “(ထိုဘီလူးသည်) ဖြူသောမျက်နှာရှိသည် ပြောက်ကျားသောဝမ်းရှိသည် ညိုသောလက်ခြေရှိသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(1114,3,1,'ဥက္ကာခဲ။','ကိုဟ်စှ်ေ = (အာကာသမှ) ဥက္ကာကြွေသည်။ ဥက္ကာခဲကျသည်။ ‘ဗဳသတဳ’ (န) လည်းရှု။')
,(1115,3,4,'၁။ သွန်သည်။ လောင်းသည်။','“ဍာ်ဂှ် ကိုဟ်စုတ်ထောံ ပ္ဍဲထၟာဲညိ။” = “ရေကို အိုးထဲလောင်းထည့်လိုက်ပါ။” || “ပုၚ်အုတ်အာဂှ် သကိုဟ်ထောံကၠေံရ။” = “သိုးသွား သောထမင်းကို သွန်ပစ်လိုက်သည်။”')
,(1115,3,4,'၂။ စုပြုံလာသည်။ ဒလဟောဝင်လာသည်။ အရေအတွက် (ဝါ) ပမာဏများစွာဖြင့် ရောက်လာသည်။','“တၞဟ်နပါဲဒဴဘဲပၞာန်တုဲ ညးဒှ်ဒဒိုက်ဂမၠိုၚ် နူ ဍုၚ်ရးဗၟာတအ်ဂှ် ကိုဟ်လုပ်ကၠုၚ်ဍုၚ်ရးသေံအိုတ်ရ။” = “စစ်ဘေးစစ်ဒဏ်မှ ရှောင်တိမ်းရန်အတွက် မြန်မာနိုင်ငံမှ ဒုက္ခသည်များသည် ထိုင်းနိုင်ငံတွင်းသို့ ဒလဟောစုပြုံဝင်ရောက်လာကြသည်။” || “ကၟိုန်ပြိုဟ်တုဲ ဍာ်ကိုဟ်လုပ်ကၠုၚ် ပ္ဍဲဝါဗ္ၚရ။” = “တာတမံကျိုးပေါက်၍ လယ်ကွင်း ထဲသို့ ဒလဟောရေဝင်လာသည်။”')
,(1116,3,4,'သွန်ပစ်သည်။ လောင်းပစ်သည်။',null)
,(1117,3,1,'လည်ပင်း။ ခံတွင်း။',null)
,(1118,3,1,'ကျွန်း။',null)
,(1119,3,4,'ဇက်ကျိုးသည်။ (ရောဂါသည်း၍လည်းကောင်း၊ သေရည်အသောက်များ၍လည်းကောင်း ဖြစ်တတ်သည်။)',null)
,(1120,3,1,'အထပ်ခိုး။ လည်ပေါ်အထပ်ခိုး။',null)
,(1121,3,1,'လည်ပင်းကြီးနာ။','(ကြိ) လည်ပင်းကြီးရောဂါရသည်။')
,(1122,3,4,'(ဥပစာ) လည်ဆန့်၍ တငံ့ငံ့စောင့်မျှော်သည်။','“အဲစၟဳဒၟံၚ်ဍေံ ကအ်ဂၠိၚ်ရ၊ ဍေံဟွံစိုပ်ဏီရ။” = “သူ့ကို ငါမျှော်နေတာ လည်တံရှည်ကုန်ပြီ၊ သူမရောက်လာသေးပါ။”')
,(1123,3,4,'၁။ လည်တံတိုသည်။','“မၞိဟ်တြုံဂှ် ကြောအ်လောန်တုဲ ကအ်ဂၠေံဒၟံၚ်ရ။” = “ထိုယောကျာ်းသည် ဝလွန်း၍ လည်တံတိုနေသည်။”')
,(1123,3,4,'၂။ (ဥပစာ) (ခေါင်း­ရွက်ရပါ များ၍) အလွန်ပင်ပန်းသည်။','“အဲယဵုသွံသၞေဝ်တုဲ ဒးကၠောန်ဗစလဝ်ဗှ်ေတအ်ဂှ် ကအ်အဲဂၠေံအိုတ်ရ။” = “ဟင်းရွက်ရောင်း၍ နင်တို့ကို လုပ်ကျွေးထားရသည်မှာ ငါ့လည်တိုကုန်ပြီ။”')
,(1124,3,1,'ခြေကျင်းဝတ်။',null)
,(1125,3,1,'လက်ကောက်ဝတ်။',null)
,(1126,3,1,'အာမခံကတိ။ နှုတ်ကတိ။','ပ္တိတ်လဝ်ကအ်ပါၚ် = နှုတ်ကတိပြုထားသည်။')
,(1127,3,4,'စားသောက်ပြီးစတွင် ခံတွင်း­ ချဉ်သောအရသာဖြစ်ပေါ်သည်။ ခံတွင်းချဉ်သည်။',null)
,(1128,3,4,'လည်တစ်သည်။ လည်ပင်းနၚ်သည်။',null)
,(1129,3,4,'ခံတွင်းပျက်သည်။ စားလိုစိတ်မရှိဖြစ်သည်။',null)
,(1130,3,4,'စားရာတွင် အရသာမတွေ့၊ မစားချင်မသောက်ချင်ဖြစ်သည်။ ခံတွင်းပျက်သည်။',null)
,(1131,3,4,'အငန်အရသာကဲသော အစားအစာကို ကြိုက်နှစ်သက်သည်။ ခံတွင်းလေးသည်။',null)
,(1132,3,4,'အငန်အရသာနည်းသော အစားအစာကို ကြိုက်နှစ်သက်သည်။ ခံတွင်းပေါ့သည်။',null)
,(1133,3,4,'အစာရွေးသည်။ အစာကောင်းမှ စားလိုသည်။ ခံတွင်းအလိုလိုက်သည်။',null)
,(1134,3,1,'လည်ကုပ်။',null)
,(1135,3,4,'(စည်း) ‘ကည’ ရှု။',null)
,(1136,3,4,'အလျင်အမြန်ပြုလုပ်သည်။','‘ကညက်’ ရှု။')
,(1137,3,1,'နွေကာလ။ နွေဥတု။','‘ကညၚ်’ ရှု။')
,(1138,3,4,'အော်သည်။ အော်ဟစ်သည်။','‘ကညာၚ်’ ရှု။')
,(1139,3,4,'ခိုင်သည်။ မြဲသည်။','ဗိုန်က္ညန် = ခိုင်မြဲသည်။ ‘ကညန်’/‘ကညောန်’ ရှု။')
,(1140,3,4,'ရုန်းသည်။ ရုန်းကန်သည်။','‘ကညဟ်’ ရှု။')
,(1141,3,1,'အထွာ။ အထွာဆိုင်။ တစ်ထွာအတိုင်းအတာ။',null)
,(1141,3,4,'၁။ ထွာသည်။ အထွာဖြင့် တိုင်းတာသည်။',NULL)
,(1141,3,4,'၂။ ခြေဖနောင့်ပင့်၍ ခြေဖျားထောက်သည်။','က္ဍကျောဝ် = ခြေဖျားထောက်၍ ချောင်းကြည့်သည်။ || က္ဍကေတ် = ခြေဖျားထောက်၍ လှမ်းယူသည်။')
,(1142,3,4,'(ကျွတ်ကောင်ကဲ့သို့) ထွာ၍ထွာ၍သွားသည်။',null)
,(1143,3,4,'တိမ်သည်။','က္ဍာက္ဍာ = (နဝိ) တိမ်သော။ ဍာ်က္ဍာက္ဍာ = တိမ်သောရေ။ “ချိုတ်ဍာ်က္ဍာက္ဍာ” = “ရေတိမ်နစ်သည်။”')
,(1144,3,4,'မာကြောသောအရာဝတ္ထုပေါ်သို့ တစ်စုံတစ်ခုကျသောအခါ မြည်သောအသံ။',null)
,(1145,3,1,'မာကြောသောအရာဝတ္ထုပေါ်သို့ တစ်စုံတစ်ခုကျသောအခါ မြည်သောအသံ။',NULL)
,(1145,3,4,'၁။ စိုသည်။ စွတ်စိုသည်။',NULL)
,(1145,3,4,'၂။ ခင်မင်သည်။ အကျွမ်းဝင်သည်။',NULL)
,(1146,3,4,'ခင်မင်သည်။ ရင်းနှီးသည်။ အကျွမ်းဝင်သည်။',null)
,(1147,3,5,'(ချမ်းလွန်း၍ဖြစ်စေ၊ ကြောက်လွန်း၍ဖြစ်စေ) တဆတ်ဆတ်(တုန်သည်)။','“ကၞုဲဂှ် ၜိုဟ်ဗြဲတုဲ ဇတဝ်ဒၟံၚ်က္ဍုက်က္ဍုက်ရ။” = “ထိုမျောက်သည် မိုးအေးသဖြင့် တဆတ်ဆတ် တုန်နေသည်။”')
,(1148,3,4,'၁။ စွတ်စိုသည်။ စိုပြည်သည်။','“ပ္ဍဲဥတုကသီု တၞံဆုဂမၠိုၚ်က္ဍုက် က္ဍေက်ဒၟံၚ်အိုတ်ရ။” = “မိုးဥတု­ သစ်ပင်များသည် စိမ်းလန်းစိုပြည်နေကြသည်။”')
,(1148,3,4,'၂။ (အသံ၊ စကားစသည်) သာယာသည်။ နာပျော်ဖွယ်ဖြစ်သည်။','“ဂစေံကွဴဂှ် မၞုံရမျှာၚ်မက္ဍုက်က္ဍေက်ရ။” = “ဥသြငှက်သည် သာယာနာပျော်ဖွယ်သော အသံရှိသည်။”')
,(1149,3,4,'စိုသည်။ စိုစွတ်သည်။',null)
,(1150,3,4,'(လက်သည်း၊ လက်စသည်ဖြင့်) ချိုးဖြတ်သည်။','“တၞုၚ်လဵုဂှ် လ္ပဍေက်ကဵုတဲ၊ ရေက်ကေတ်ကဵုၜုန်ညိ။” = “ဗူးညွန့်ကို လက်ဖြင့်မချိုးဖြတ်ပါနှင့်။ ဓါးနှင့်လှီး ဖြတ်ယူပါ။”')
,(1151,3,3,'(မကောင်းမှုစသည်ဖြင့်) ညစ်ထေးလိမ်းကျံသော။ ပေကျံသော။ (?)','“အသပ္ပရိုဟ်ဒုဿဳလ မက္ဍေက်ဒဇဳဒၟံၚ်ဒုစရိုတ်ပိစွံ။” (ဇ—၁၅ဝ။ အစွောံ။) = “ဒုစရိုက်သုံးပါးတို့ဖြင့် ညစ်ထေးလိမ်းကျံနေသော အကျင့်သီလမရှိသော မသူတော်ဒုဿဳလ။”')
,(1152,3,4,'၁။ စီးသည်။','က္ဍိုက်ချေံ = မြင်းစီးသည်။ က္ဍိုက်ဂၠုၚ် = လှေစီးသည်။')
,(1152,3,4,'၂။ ဖိသည်။','“တၞံဆုဂှ် ကဝ်ဒေါမ်စှ်ေတုဲ ဍိုက်ဒးလဝ်သ္ၚိဝစ်ရ။” = “ထိုသစ်ပင်ကျိုးလဲကျပြီး အိမ်သာအပေါ် ဖိမိနေသည်။”')
,(1152,3,4,'၃။ (လ) ရက်စုံသည်။','“ဂိတုဟွံဍိုက်ဂှ် နွံ (၂၉) တ္ၚဲတုဲ ဂိတုဍိုက်ဂှ် နွံ (၃ဝ) တ္ၚဲရ။” = “ရက်မစုံသောလသည် (၂၉) ရက်ရှိပြီး ရက်စုံသောလသည် ရက် (၃ဝ) ရှိသည်။”')
,(1153,3,4,'(လှေ၊ သၚ်္ဘော၊ လှည်းစသည်) စီးနင်းသည်။',null)
,(1154,3,4,'အရှက်ခွဲသည်။ အရှက်ရစေသည်။','“ဒေါဝ်ဗၞဳမၞိဟ်ဂမၠိုၚ် လ္ပက္ဍိုက်ဂဝအဲညိ။” = “လူပုံအလယ်မှာ ငါ့ကိုအရှက်မခွဲပါနှင့်။”')
,(1155,3,4,'အရှက်ရသည်။ အရှက်ကွဲသည်။','“ဟာဲဣသိစၞာဲ၊ ——၊ (ဗှ်ေဂှ်) ဣသိစၞာဲကမၠတ်စ ရောၚ် အဲသ္ဂးတုဲ မၞိဟ်ဂမၠိုၚ်ရပ်ဗှ်ေရ၊ ဗှ်ေဒးက္ဍိုက်ဂွရ။ ကၠာညးဟွံတီညာတ်ဂှ် ဗှ်ေကမန်ဒဴအာကၠေံ ပြဟ်ရ” ဗောဓိသတ်(ဒကောတ်) စမြဗဟေက်တုဲ —။ (၅၅ဝ။ ဇ—၃၂၅။ ဒု—၂၁၃။ အစွောံ။) = “အိုရသေ့စဉ်းလဲ၊ ——၊ သင်သည် ခိုးသူသေ့စဉ်းလဲတည်းဟု ငါဆို၍ လူတို့သည် သင့်ကိုဖမ်း ကုန်အံ့၊ သင်သည် အရှက်ကွဲရအံ့။ လူသူမသိသေးခင် လျင်စွာပြေးလေ” ဟုဘုရားလောင်းဖွတ် မင်းခြိမ်းချောက်၏။')
,(1156,3,1,'ခေါင်တန်း။',null)
,(1157,3,4,'ပြည့်စုံသည်။ ပြည့်ဝသည်။ လိုသည်မရှိဖြစ်သည်။',null)
,(1158,3,4,'၁။ စျေးကြီးသည်။','“ယာတ်ဏအ် ၚုဟ်ဍေံက္ဍၚ်လောန်အာရ။” = “ဤအဝတ်သည် စျေးကြီးလွန်းသည်။”')
,(1158,3,4,'၂။ (အနာရောဂါ)သည်းသည်။','“အပါယဲက္ဍၚ်ဒၟံၚ်။” = “အဖေ့ရော ဂါသည်းနေသည်။”')
,(1158,3,3,'အလွန်။ ပိုလွန်သော။ သာလွန်သော။ လွန်ကဲသော။','“မိကျာ်သြဳဂှ် ကျေဝ်တဴရ။ မိသိုက္ခမာတုန် ကျေဝ်က္ဍၚ်ရ။” = “မိကျိုက်စွိုင်းက လှသည်။ မိသိုက္ခမာကား သာလွန်၍လှသည်။” || “သတ္တအ်ရာဂက္ဍၚ် ချိုတ်အာက္တဵုဒှ်ပြိုတ်ဖအိုတ်ရ။ သတ္တအ်မောဟက္ဍၚ် ချိုတ်အာက္တဵုဒှ်တိရစ္ဆာန်ဖအိုတ်ရ။ သတ္တံဒေါသက္ဍၚ် ချိုတ်အာစှ်ေဒးနရက်ဖအိုတ်ရ။” (အဓါန်မ သုန်။ အစွောံ။) = “ရာဂလွန်ကဲသောသတ္တဝါများသည် သေ၍ပြိတ္တာဖြစ်ကြကုန်၏။ မောဟလွန်ကဲသော သတ္တဝါများသည် သေ၍တိရစ္ဆာန်ဖြစ်ကြကုန်၏။ ဒေါသလွန်ကဲသော သတ္တဝါများသည် သေ၍ငရဲကျကြကုန်၏။” || “တၠပညာတအ် ဝေတ်ပါၚ်ဝေတ်စိုတ်ကဵုက္ဍၚ်ညိ။” (ဇ— ၁၁၇။ အစွောံ။) = “ပညာရှိတို့သည် နှုတ်ကို၄င်း စိတ်ကို၄င်း မဖြစ်မနေ အလွန်စောင့်စည်း ထိန်းချုပ်ပါလေ။”')
,(1158,3,9,'ကြိယာကို ပြေပြစ်လေးနက်စေသောစကားလုံး။','“သ္ၚိမ္ဂးဂှ် ဇၞော် က္ဍၚ်ခိုဟ်က္ဍၚ်ရ။” = “အိမ်မည်သည်မှာ ကြီးလေကောင်းလေဖြစ်သည်။”')
,(1159,3,5,'အလွန်အမင်း။ အလွန်တရာ။',null)
,(1160,3,5,'အလွန်။ အလွန်အမင်း။ အလွန်တရာ။','“ရုပ်သာ်သၟတ်ဗြဴဝုတ်ဂှ် ဂေါဝ်လောန် က္ဍၚ်သန်ရ။” = “ထိုမိန်းမပျို၏ရုပ်ရည်သည် အလွန်တရာ လှပတင့်တယ်၏။”')
,(1161,3,1,'သံမဏိ။','ပသဲက္ဍာၚ် = သံမဏိ။')
,(1162,3,1,'ထီး။',NULL)
,(1162,3,4,'၁။ (ကြက်ဥဘဲဥများ သားမပေါက်ပဲ) ပုပ်သွားသည်။','“ခၟာဲစာၚ် က္ဍိုၚ်အာရ။” = “ကြက်ဥသည် သားမပေါက်ပဲပုပ်သွားပြီ။”')
,(1162,3,4,'၂။ လွင့်သည်။','“ကၠဟ်ဏာမ တၟအ်ဂှ် က္ဍိုၚ်တိုန်အာရ။” = “ကျောက်ခဲလုံးကို လွှင့်ပစ်လိုက်ရာ လွင့်တက်သွားသည်။”')
,(1163,3,4,'နားပင်းသည်။',null)
,(1164,3,1,'လေထီး။',null)
,(1165,3,1,'ဘုရာထီးတော်။ စေတီထီးတော်။',null)
,(1166,3,1,'ခေါက်ထီး။',null)
,(1167,3,1,'တံခွန်ကုက္ကား။ ထီးတံခွန်။',null)
,(1168,3,1,'ထီးဖြူ။ (မင်းမြှောက်တန်ဆာငါးပါးတွင် အပါအဝင်။)',null)
,(1169,3,1,'ပုသိမ်ထီး။ (ရန်ကုန်ထီး)',null)
,(1170,3,4,'ဥမှပေါက်သည်။','“ကောန်စာၚ်ဂှ် က္ဍတ်တိတ်ကၠုၚ်နူခၟာဲရ။” = “ကြက်သားလေးသည် ဥမှပေါက်ထွက်လာသည်။” || ‘ခ္ဍတ်’ (ကြိ) လည်းရှု။')
,(1171,3,4,'တစ်ခဲနက်ထူထဲသည်။ သိပ်သည်းကျစ်လျစ်သည်။',NULL)
,(1171,3,1,'တစ်ခဲနက်သောအထူ။ သိပ်သည်းသောအထူ။','က္ဍတ်တၟအ် = တစ်ခဲနက်ထူထဲသောတောင်။ “ဣသိကာဠဒေဝလမွဲဂှ် နိဿဲကဵုက္ဍတ်တၟအ်မွဲ ပ္ဍဲတြဴသၠုၚ်ကျာအဝန္တိရးဂှ်တုဲ တွဳဗဝိုၚ်ကေတ် ဣသိမကမွဲလ္ၚီတုဲ ပဒတဴရ။” (ဇ—၄၂၃။ အစွောံ။) = “ကာဠဒေဝိလမည်သော ရသေ့သည် အဝန္တိဒက္ခိဏာပထ­ တစ်ခဲနက် သောတောင်ကို အမှီပြု၍ အထောၚ်မကသော ရသေ့တို့သည် ခြံရံအပ်သည်ဖြစ်၍ နေ၏။” (ညောင်ကန်)')
,(1172,3,4,'ထူထဲသည်။','“ဆုဇၞော်မွဲ မၞုံဂါပ်ကၞာၚ်ဇၞော်သၟတ် မၞသၠတမြံၚ်လမတ်မ က္ဍတ်သ္တီု—။” (ဇ—၁၃၃။ အစွောံ။) = “တစ်ခုသောသစ်ပင်ကြီးသည် အခက်အခွကြီးငယ်နှင့် ပြည့်စုံ၍ ထူထဲသောအရွက်ရင့်အရွက်နုများရှိ၏။”')
,(1173,3,4,'ပေါက်ဖွားသည်။','“(ခမာဲဂစေံပိမဂှ်) သတြုဟွံမွဲမ္ဂး ဍေံက္ဍတ်ပါ်တိုန် ဗွဲမဒးရးရအဴ” လၟတံဂး။ (ဇ—၅၂၁။ အစွောံ။) = “ငှက်ဥသုံးလုံးတို့သည် ဘေးရန်မရှိပါက ကောင်းမွန်စွာ ပေါက်ဖွားလာလိမ့်မည်။”')
,(1174,3,4,'၁။ (အစားအစာ) ချိုသောအရသာရှိသည်။ ချိုသည်။','“ဍာ်သာဲ မ္ဂးဂှ် က္ဍာတ်လောန်ရ။” = “ပျားရည်မည်သည် အလွန်ချို၏။”')
,(1174,3,4,'၂။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“ၜိုန်အရေဝ်ဍေံဍာတ်ဒၟံၚ်ကီုလေဝ် စိုတ်ဍေံယုတ်မာဒၟံၚ်ရောၚ်။” = “သူ့စကားသည် ချို သော်လည်း သူ့စိတ်သည် ယုတ်မာ၏။”')
,(1174,3,3,'အရသာချိုသော။ ချိုသာသော။ သာယာနာပျော်ဖွယ်ဖြစ်သော။',NULL)
,(1175,3,4,'သာယာနာပျော်ဖွယ်ဖြစ်သည်။ နားဝင်ချိုသည်။',null)
,(1176,3,4,'၁။ ချိုဆိမ့်သောအရသာရှိသည်။',NULL)
,(1176,3,4,'၂။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“အရေဝ်ကောန်မ္ဂးဂှ် က္ဍာတ်ကြောအ်ဒၟံၚ် ပ္ဍဲကတောဝ်မိမလၟိုန်ရ။” = “သားသမီး၏စကားမည်သည် မိဘတို့၏နားတွင် အမြဲသာယာနာပျော်ဖွယ်ဖြစ်၏။”')
,(1177,3,1,'အုတ်။ အုတ်ခဲ။',NULL)
,(1177,3,4,'ကြေသည်။ ညက်သည်။ အမှုန့်ဖြစ်သည်။','“ထၞက် မြေက်ဂှ် ဍိုတ်ရဟာ။” = “ၚရုပ်သီးကိုထောင်းတာ ညက်ပြီလား။”')
,(1178,3,4,'မှုန့်မှုန့်ညက်ညက်ကြေသည်။',null)
,(1179,3,4,'၁။ ကျဉ်းသည်။ ကျဉ်းမြောင်းသည်။','“ဖိုၚ်ဖဴသ္ၚိပိုဲဂှ် က္ဍန်တဴရ။” = “ငါတို့အိမ်၏မီး ဖိုချောၚ်သည် ကျဉ်းနေသည်။”')
,(1179,3,4,'၂။ (ငါးမျှားချိပ်ဖြင့်) မျှားသည်။','က္ဍန်က = ငါးမျှားသည်။')
,(1179,3,3,'ကျဉ်းသော။ ကျဉ်းမြောင်းသော။','‘ခ္ဍန်’ (ကြိ)၊ ‘ကမၞန်’/‘ခမၞန်’ (နဝိ) လည်းရှု။')
,(1180,3,4,'အသက်နှစ်ဆယ်မပြည့်သေး၍ သန္ဓေသက်ပါပေါင်းပြီး ရဟန်းခံရသော ရဟန်း လောင်းအတွက် သိဒ္ဓိတင်သည့်ပွဲ ကျင်းပသည်။',null)
,(1181,3,4,'ကျပ်တည်းသည်။ ကျဉ်းမြောင်းသည်။ ကျဉ်းကျပ်သည်။ (ပါဠိ—သမ္ဗာဓ)',null)
,(1182,3,4,'(လိပ်ပြာစဉ်သူအတွက်) လိပ်ပြာခေါ်သည်။',null)
,(1183,3,1,'၁။ ခေါင်း။ ဦးခေါင်း။ ထိပ်။','က္ဍိုပ်မၞိဟ် = လူဦးခေါင်း။ က္ဍိုပ်တၞိန် = လှေခါးထိပ်။ က္ဍိုပ်ဒဵု၊ က္ဍိုပ်တၟအ် = တောင်ထိပ်။ တောင်ထွတ်။')
,(1183,3,1,'၂။ (အပင်မှရသော)ဥ။','က္ဍိုပ်ကွာဲ = မြောက်ဥ။ က္ဍိုပ်ကြဴ = ပိန်းဥ။ က္ဍိုပ်သော = ဆိပ်ဖူးပင်။')
,(1183,3,1,'၃။ အုပ်စု။၊','“က္ဍိုပ်ပိုဲ မၞိဟ်နွံစှ် တၠရ။” = “ကျွန်တော်တို့အုပ်စုမှာ လူဆယ်ယောက်ရှိသည်။”')
,(1183,3,9,'အုပ်စုကို ရေတွက်ရာတွင် သုံးသောစကားလုံ။','“မၞိဟ်ၜါက္ဍိုပ်တအ်ဂှ် တံၚ်ဇုက်ပြိုၚ်ဒြဟတ်ညးသ္ကအ်ရ။” = “လူအုပ်စု နှစ်စုတို့သည် လွန်ကြိုးဆွဲအားပြိုၚ်ကြသည်။”')
,(1184,3,1,'(ဥပစာ) စဉ်းလဲသောသူ။ ကောက်ကျစ်သောသူ။',null)
,(1185,3,4,'(သစ်ပင်၊ သစ်ရွက်စသည်) စိမ်းလန်းစိုပြည်သည်။',null)
,(1186,3,1,'လေညာ။ လေတၚ်။ လေညာအရပ်။ (ဝိနဒဝအရဒ)','“(ကၠိက်ဂှ် ပၠောလေတ်လဝ် အိက် အလုံဇကုတုဲ) ပ္ဍဲဋ္ဌာန်က္ဍိုပ်ကျာဂှ် ကၠိက်အာတန်ဒၟံၚ်ရ။ (မၚ်ဇာဒိသိုၚ်မကၠုၚ်ရ။)” (ဇ— ၁၅၃။ အစွောံ။) = “ထိုဝက်သည် တစ်ကိုယ်လုံးကို မစင်လူးပြီးလျှင် လေညာအရပ်­ ရပ်နေ၍ ခြင်္သေ့အလာကို စောင့်၏။”')
,(1187,3,4,'ခေါင်းမာသည်။ ပြောဆိုရခက်သည်။',null)
,(1188,3,1,'ရာခိုင်နှုန်း။','၆ဝ က္ဍိုပ်ကၠံ = ၆ဝ ရာခိုင်နှုန်း။')
,(1189,3,1,'အိမ်မြှောင်။ ကွန်ပါ။',null)
,(1190,3,4,'ခေါင်းကိုက်သည်။',null)
,(1191,3,1,'ဦးခေါင်းရှိငယ်ထိပ်။',null)
,(1192,3,1,'တောဦးစီး။ တောခေါင်း။',null)
,(1193,3,1,'ဆံစုအခေါင်း။',null)
,(1194,3,1,'တစ်လတစ်လတွင် အမြင့်ဆုံးတက်သောဒီရေ။ ခေါင်ရေ။',null)
,(1195,3,1,'နို့မလိုင်။',null)
,(1196,3,1,'၁။ မြက်ချိုမျိုးဝင် မြက်တစ်မျိုး။ (ဆေးဖက်ဝင်)','(၄င်းအပင်ကို တံမြက်စီးအဖြစ်လည်း သုံးရသည်။)')
,(1196,3,1,'၂။ ရှေးခေတ်မြို့နယ်အပိုင်းအခြား။',NULL)
,(1197,3,1,'မြေတို့၏အထွတ်အထိပ်။ အချက်အချာအောင်မြေ။','“အလုံဂတာဇမ္မုဒိတ်ဝွံ ဘာဇေတဝန်ဂှ် မဒှ်က္ဍိုပ်တိမပြဲရောၚ်။ ဟိုတ်ညးဒၟံၚ်ပ္ဍဲဋ္ဌာန်ဂှ်တုဲ လာဘသက္ကာရပူဇဴသကာညးမဂၠိုၚ်ရောၚ်” တဳတံဂး။ (ဇ—၂၁၃။ အစွောံ။) = “အရှင်တို့၊ ရဟန်းဂေါတမသည် ဇမ္ဗူဒိပ်ကျွန်းအလုံး၏ မြတ်သောဋ္ဌာနဖြစ်သော မြေတို့၏အထွတ်အထိပ်­ နေရ၏။ ထို့ကြောင့် ရဟန်းဂေါတမအား လာဘသက္ကာရသည်ဖြစ်၏” ဟုတိတ္ထိတို့ဆိုကုန်၏။ (ညောင်ကန်)')
,(1198,3,1,'နို့သီးခေါင်း။',null)
,(1199,3,1,'တောင်ထိပ်။ တောင်ထွတ်။','“သၟိၚ် ပဂကောံကဵုအမာတ်တံတုဲ တိုန်အာဒဵုက္ဍိုပ်တၟံတေံကီုရ။” (ဇ—၁၂၂။ အစွောံ။) = “မင်းသည်လည်း အမတ်အပေါင်းနှင့်အတူ တောင်ထိပ်သို့တိုင်အောင် တက်သွား၏။” || “ဗောဓိသတ်ဒှ်ဇာဒိ သိုၚ် ဒၟံၚ်ပ္ဍဲဂိုဟ်တၟံမွဲ တိတ်နူဂိုဟ်တၟံတုဲ တိုန်အာလ္တူက္ဍိုပ်တၟံသၠုၚ်ရ။” (ဇ—၁၅၇။ အစွောံ။) = “ဘုရားလောင်းသည် ခြင်္သေ့ဖြစ်၍ တောင်ဂူ­နေ၏။ — ဂူမှထွက်ပြီးလျှင် တောင်ထိပ်­ရပ်၍။” (ညောင်ကန်)')
,(1200,3,1,'ထမင်းဦး။ ဆွမ်းဦး။ (ပါဠိ—အဂ္ဂပိဏ္ဍ)',null)
,(1201,3,1,'ထမင်းဦးဟင်းဦး။ စားဦးစားဖျား။','“ကၠာမိမဟွံဂွံစဏီ လ္ပစက္ဍိုပ်ပုၚ်က္ဍိုပ်သွ ညိ။” = “မိဘများမစားမှီ ထမင်းဦးဟင်းဦးကို မစားပါနှင့်။”')
,(1202,3,1,'ဖိုခနောက်။ မီးဖို။ ခုံလောက်။','“(ဗမၞိဟ်ဗြဴတုန် ကုတ္ၚေက်ဂှ်) ဝတ်ကအ်ဂစိုတ်တုဲ စွံလဝ်လတူက္ဍိုပ်ဖဴရ။” (ဇ—၁၉၈။ အစွောံ။) = “ပုဏ္ဏေးမသည် ကျေးသားအား လည်ကိုလိမ်၍ သတ်ပြီးလျှင် ခုံလောက်ကြားတို့­ သွင်း၏။” (ညောင်ကန်)')
,(1203,3,5,'ဦးခေါင်းဇောက်ထိုးဖြစ်လျက်။ ဦးစောက်ပြောင်းပြန်။','“(သၟိၚ်ဗပုန်ဂှ် ရပ် ဒက်လဝ်သၟိၚ်ဗာရာဏသဳတုဲ) ကဵုညးကွက်လဝ်ပ္ဍဲလယ က္ဍိုပ်ဖျေံဇိုၚ်ပ္တိုန်—။” (ဇ—၃ဝ၃။ အစွောံ။) = “ခိုးသူမင်းသည် ဗာရာဏသီမင်းအား ဖမ်းချုပ်နှောင်၍ ဆိုင်း­ထည့်၍ ဦးစောက်ပြောင်းပြန် ဆွဲထားစေ၏။”')
,(1204,3,4,'ခေါင်းအုံသည်။ ခေါင်းမူးသည်။','“ဟိုတ်မစဂၠိုၚ် ဇကုသ္ဇိုၚ်မတ်ကြုပ်က္ဍိုပ်ဘိုၚ် အာ—။” (ဇ—၂၅၅။ အစွောံ။) = “စားများသဖြင့် ကိုယ်လေးလံ၍ ငိုက်မျဉ်း၍ ခေါင်းမူးဝေ၏။”')
,(1205,3,1,'တံဆိပ်ခေါင်း။ (စာပို့ရန်)',null)
,(1206,3,1,'မလိုင်။ နို့နှစ်။',null)
,(1207,3,1,'(အကြောင်းအရာ၏) ခေါင်းစဉ်။ ခေါင်းစီး။',null)
,(1208,3,1,'ဦးစီးခေါင်းဆောင်။',null)
,(1209,3,1,'(အိပ်ရာ)ခေါင်းရင်း။ ဦးခေါင်းရင်း။','“မၞိက်စောလာမူဏိ သေဋ္ဌဳမစွံလဝ် ပ္ဍဲက္ဍိုပ်သတိက်—။” (ဇ—၂၈၄။ အစွောံ။) = “ဦးခေါင်းရင်း­ သူဌေးထားအပ်သော ပတ္တမြားတုံး။”')
,(1210,3,1,'ပြဿနာဖန်တီးသူ။ ပြဿနာကောင်။',null)
,(1211,3,4,'(ဆီး၊ ဝမ်း) ချုပ်သည်။','ဂၞဴက္ဍဝ် = ဝမ်းချုပ်သည်။ ပဿဴက္ဍဝ် = ဆီးချုပ်သည်။ ယဲသ္ၚိဍာ်ပဿဴမက္ဍဝ် = ဆီးဝမ်းချုပ်သောရောဂါ။ (ပါဠိ—အာနာဟ)')
,(1212,3,4,'(အနာ) ရောၚ်ရမ်းလာသည်။ အခြေအနေဆိုးဝါးလာသည်။','“ဟွံသ္ပဂရု ဟွံဂွံဝဳပ ရာဍေံတုဲ သရဂှ် က္ဍဝ်တိုန်ရ။” = “ဂရုစိုက်ကုသခြင်း မရှိလေသောကြောင့် ထိုအနာသည် ဆိုးဝါးလာသည်။” || “ဒေဝဒတ်မသ္ပစဵုကဵုဆီထမၞေက်မက္ဍဝ်ကုကျာ်ရ။” = “ဒေဝဒတ်သည် မြတ်စွာဘုရားအား သွေးစိမ်းထွက်၍ အခြေအနေဆိုးဝါးအောင်ပြု၏။”')
,(1213,3,9,'အဖြာ။ အပါး။ အတန်။','မ္ၚဵုမသုန်က္ဍဝ် = မၚ်္ဂလာငါးဖြာ။ မၚ်္ဂလာငါးပါး။')
,(1214,3,1,'၁။ ဦးနှောက်။',NULL)
,(1214,3,1,'၂။ အထွတ်အထိပ်။','က္ဍဟ်ဒဵု = တောင်ထိပ်။')
,(1215,3,4,'ဦးနှောက်ကောင်းသည်။ ဉာဏ်ကောင်းသည်။',null)
,(1216,3,4,'ခေါင်းရှုပ်သည်။',null)
,(1217,3,4,'ဦးနှောက်မြန်သည်။ ဉာဏ်ပြေးသည်။',null)
,(1218,3,1,'ကျယ်လောင်စွာစကားပြောတတ်သည်။ အာကျယ်သည်။',null)
,(1219,3,4,'မုန်းသည်။ စက်ဆုပ်သည်။ ရွံရှာသည်။','‘ဆာန်ဟွံညာတ်ဒုဟ် က္ဍုဟ်ဟွံညာတ်ဂုန်’ = ‘ချစ်လျှင်အပြစ်မမြင်၊ မုန်းလျှင်ကျေးဇူးမမြင်။’')
,(1219,3,1,'မုန်းခြင်း။ အမုန်း။ စက်ဆုပ်ခြင်း။','‘ဂဍုဟ်’ ဟုလည်းတွေ့ရသည်။ || “ပွအနေသနၜါစှ်ောမွဲဝွံဂှ် မဒှ်က္ဍုဟ်ကျာ်အရှန်ပစ္စေဂဗုတ်တံရောၚ်။” (ဇ—၁၇၉။ အစွောံ။) = “နှစ်ဆဲ့တစ်ပါးအပြားရှိသောအနေသနအမှုသည် ဘုရား၊ ရဟန္တာ၊ ပစ္စေကဗုဒ္ဓါတို့၏ စက်ဆုပ်ရာဖြစ်၏။”')
,(1220,3,4,'(သစ်သီး) မှည့်သည်။',null)
,(1221,3,4,'မုန်းတီးသည်။ ရွံရှာသည်။ ရွံမုန်းသည်။',null)
,(1222,3,1,'(သစ်သီး) အမှည့်လွန်သည်။ မှည့်ရော်သည်။',null)
,(1223,3,4,'ပါးနပ်သည်။ လိမ္မာသည်။',null)
,(1224,3,4,'လိမ္မာပါးနပ်သည်။',null)
,(1225,3,4,'(သံတူရွင်းစသည်ဖြင့်) ပင့်ကော်သည်။ ကော်ထုတ်သည်။ ကလော်ထုတ်သည်။',null)
,(1226,3,9,'တစ်ခင်း။ တစ်ကွက်။','တိပိကၞ = လယ်မြေသုံးခင်း။')
,(1227,3,1,'၁။ (ဘူးဖရုံစသောနွယ်ပင်တို့ တက်ရန်လုပ်ထားသော) စင်။','ကၞာလဵု = ဗူးစင်။')
,(1227,3,1,'၂။ ပရိသတ်စုဝေးရာ ယာယီတဲ။ မဏ္ဍပ်။ ကနား။ (ပါဠိ—မဏ္ဍပ)',NULL)
,(1228,3,1,'မဏ္ဍပ်။','“(ဗောဓိသတ် အာတရဴကန္တာဗတဳ) လတူကွဳဂှ် ကဵုကၠောန်က ဏာထးတုဲ တြဴဗ္တံအာတဴရ။” (ဇ—၂။ အစွောံ။) = “ဘုရားလောင်းသည် သဲကန္တာရခရီးသွား၏။ လှည်းအထက်­ မဏ္ဍပ်ဆောက်စေကုန်၍ ညဉ့်­သာသွားကုန်၏။”')
,(1229,3,1,'ရတနာမဏ္ဍပ်။ (ဘုရင်တို့၏ ပွဲသဘၚ်ကြည့်ရာနေရာ။ ရဟန်းတို့၏ တရားဟောရာ နေရာ။)','“(ခမဳကောကာလိကဂှ် တၞဟ်နတွံဓဝ်) လ္ၚောဝ်ထေဇၞော်တံတုဲ လုပ်အာပ္ဍဲဒေါဝ်ကၞာရတ် တုဲ တိုန်လတူသၞာဓဝ် ညးမလးပ္ညပ်လဝ်ဂှ်တုဲ—။” (ဇ—၁၇၂။ အစွောံ။) = “(ကောကာလိကမည် သောရဟန်းသည် တရားဟောရန်အလို့ငှာ) သၚ်္ဃာ့အလယ်သို့ဝင်၍ သီတင်းကြီးသော ရဟန်းတို့ ကိုရှိခိုး၍ တန်ဆာဆင်အပ်သော ရတနာမဏ္ဍပ်­ ခင်းအပ်သော ဓမ္မကထိကတို့၏နေရာသို့တက် ၍—။” (ညောင်ကန်)')
,(1230,3,1,'၁။ ကြွက်။',NULL)
,(1230,3,1,'၂။ ဓနိပင်။','သတ်ကၞိ = ဓနိသီး။ ဍာ်ကၞိ = ဓနိရည်။')
,(1230,3,1,'၃။ ပိတ်ချင်း။ (ဆေးဖက်ဝင်)', null)
,(1231,3,1,'ကြွက်စုတ်။ (ပါဠိ—ဂိရိကာ)',null)
,(1232,3,1,'ကြွက်ဖြူ။',null)
,(1233,3,1,'ကြွက်ကတိုး။ ကြွက်စုတ်။',null)
,(1234,3,1,'၁။ ကြမ်းပြင်။ ကြမ်းခင်း။','“သ္ၚိဂှ် လးလဝ်ကၞဳဆုရ။” = “ထိုအိမ်သည် သစ်သားကြမ်း ခင်းထားသည်။”')
,(1234,3,1,'၂။ ကြည်း။ ကုန်း။','သတ်မမြက်ပ္ဍဲဍာ်ပ္ဍဲကၞဳ = ရေ­၄င်း ကြည်း­၄င်း လျင်မြန်သောသတ္တဝါ။ သၞေဟ်ကၞဳ = ကြည်းဆိပ်။ “ကဝွံမွဲ သၟဟ်ရထအစောံအပါ ပ္ဍဲကၞဳ ပ္ဍဲဍာ်သန်။” (ဇ—၃၈။ အစွောံ။) = “ဤငါးကြီးသည် ကြည်း­၄င်း ရေ­၄င်း ခွန်အားနှင့်ပြည့်စုံ၍ သန်စွမ်း၏။” ‘တၞဳ’ ရှု။')
,(1235,3,4,'ပြန်လည်သင့်မြတ်စေသည်။ စေ့စပ်သည်။ အကျေအလည် ပြေငြိမ်းအောင်ပြုသည်။ ဖျန်ဖြေသည်။',null)
,(1236,3,1,'ခရု။ (မြန်မာဝေါဟာရ ‘ခရု’သည် မွန်ဝေါဟာရ ‘ကၞု’ မှ ဆင်းသက်လာသည်။)',null)
,(1237,3,1,'၁။ နားစည်။ နားခင်။',null)
,(1237,3,1,'၂။ နားပုံသဏ္ဍာန်ရှိ ပင်လယ်ခရု။',null)
,(1238,3,1,'ယောက်သွား။ ဝက်နားပုံသဏ္ဍာန်ခရု။',null)
,(1239,3,1,'ခရုပက်ကျိ။',null)
,(1240,3,1,'အသားစာရသော ပင်လယ်ယောက်သွားကြီးတစ်မျိုး။ ကနုကမာ။ (မြန်မာဝေါဟာရ ‘ကနုကမာ’သည် မွန်ဝေါဟာရ ‘ကၞုကၟာ’ မှ ဆင်းသက်လာသည်။)',null)
,(1241,3,1,'သမန်းခရု။ သင်ပန်းခရု။',null)
,(1242,3,1,'ဂုံးကောင်။ ရှည်သောအခွံရှိသော ကမာကောင်တစ်မျိုး။ (အခွံကိုဘီးလုပ်ရန်သုံးသည်)',null)
,(1243,3,1,'ကျယ်လောင်စွာ အော်မြည်တတ်သော သစ်ခေါင်းအောင်းခရုတစ်မျိုး။',null)
,(1244,3,1,'လယ်ခရု။',null)
,(1245,3,1,'ယောက်သွားခရု။',null)
,(1246,3,1,'ခရုသင်း။',null)
,(1247,3,1,'ပင်လယ်ခရု။',null)
,(1248,3,4,'(အဆောက်အဦ) ဆက်သည်၊ ဆက်ထုတ်သည်။ အဖီချသည်။',null)
,(1249,3,1,'အသားပို။ အသားတက်။',null)
,(1250,3,1,'အူအတက်။',null)
,(1251,3,1,'၁။ ခြင်ထောင်။',null)
,(1251,3,1,'၂။ စစ်ကြီး (ဝါ) တိနာသုနာပင်။ (ဆေးဖက်ဝင်)',null)
,(1252,3,1,'ဆီး။ ကျင်ငယ်။',null)
,(1252,3,4,'၁။ ကျင်ငယ်စွန့်သည်။',null)
,(1252,3,4,'၂။ ဆူပွက်သည်။','ဍာ်ကၞံ = ရေဆူသည်။')
,(1253,3,4,'(ရေ၊ ဆီစသည်) ပွက်ပွက်ဆူသည်။ ကျိုက်ကျိုက်ဆူသည်။',null)
,(1254,3,1,'(ရေ၊ ဆီစသည်) ပွက်ပွက်ဆူသည်။ ကျိုက်ကျိုက်ဆူသည်။',null)
,(1255,3,1,'အမွေးဆံပင်ရိတ်ဓါး။','‘ကး’ (ကြိ) လည်းရှု။')
,(1256,3,1,'၁။ ချိုင်း။ ချိုင်းကြား။ လက်ကတီး။',null)
,(1256,3,1,'၂။ ၚုတ်ချွန်တိုင်။ ပနနက်သဲ။ ငြောင့်။ တံသင်း။ (ပါဠိ—ခါဏုက)',null)
,(1256,3,1,'၃။ ဒဏ္ဍာရီပုံပြင်။ ယုံတမ်းစကား။',null)
,(1257,3,1,'ကနခို။ (ဆေးဖက်ဝင်) (ပါဠိ—ဒန္တိကာ','နိကုမ္ဘ)')
,(1258,3,1,'ဘုရာထီးဗဟိုချက်မတိုင်။ ဘုရားထီးပိနနဲတိုင်။',null)
,(1259,3,1,'အမှုန့်။','‘ခၞိက်’ (န) ရှု။')
,(1260,3,4,'မပြောပဲလျှိုသည်။ လူသူမသိအောင်ဖုံးဝှက်သည်။ ထိမ်ဝှက်သည်။ ထိမ်ချန်သည်။ မုသားဆိုသည်။','“သ္ဇက်ဟီုနွံမ္ဂးဟီု လ္ပကၞိက်လဝ်ညိ။” = “ပြောစရာရှိလျှင် ပြောပါ၊ မထိမ်ချန်ထားပါနှင့်။” || “ယွံသၟိၚ်ဣန်၊ ဂလာန်ကနိက်မုသာဂှ် မရာတ်ဟီုရောၚ်သွံ။” (ဇ—၃ဝ၁။ အစွောံ။) = “သိကြားမင်း၊ လိမ်ညာမုသားစကားကို သၚ်မင်းမြတ်ဆိုဘိ၏။” ‘တနိက်’ ရှု။')
,(1261,3,4,'လိမ်လည်သည်။ လိမ်ညာသည်။ မုသားပြောသည်။',null)
,(1262,3,4,'စကားထိမ်ချန်သည်။ လိမ်လည်သည်။',null)
,(1263,3,4,'လိမ်လည်ဖုံးကွယ်သည်။ ထိမ်ချန်လျှို့ဝှက်သည်။','‘တနိက်တလန်’ ရှု။')
,(1264,3,4,'ထိမ်ဝှက်သည်။ ငြင်းကွယ်သည်။ လိမ်လည်သည်။',null)
,(1265,3,4,'ဖုံးကွယ်သည်။ ထိမ်ဝှက်သည်။',null)
,(1266,3,4,'စကားထိမ်ချန်သည်။',null)
,(1267,3,1,'အုတ်အုတ်ကျက်ကျက်ဖြစ်ခြင်း။ ရုတ်ရုတ်သဲသဲဖြစ်ခြင်း။ လှုပ်လှုပ်ရွရွဖြစ်ခြင်း။','“(စိၚ်ဗ္တာၚ်ကလာၚ်ကၠုၚ်စိုပ်ရဂးတုဲ) အလုံဍုၚ်ဗာရာဏသဳဂှ် က္တဵုဒှ်ကၞုက်ကၞာဲဇၞော်ရ။” = “ဆင်ဖြူတော်သည် ကောင်းကင်ခရီးဖြင့် လာရောက်ပြီဟု တစ်မြို့လုံးသည် တစ်ခဲနက် အုတ်အုတ်ကျက်ကျက်ဖြစ်၏။” ဗရုကၞုက်ကၞာဲ = အုတ်အုတ်ကျက်ကျက်သောအသံ။ ရုတ်ရုတ်သဲသဲအသံ။')
,(1267,3,4,'၁။ အုတ်အုတ်ကျက်ကျက်ဖြစ်သည်။—စေသည်။ တုန်လှုပ်ချောက်ချားသည်၊—စေသည်။','“(မၞိက်သၟိၚ်ကၠေံအာ သၟိၚ်ဖျေံအသံကဵုဂၠာဲ) ညးဒဝ်ကၠေံတရၚ်ဍုၚ်ဖအိုတ်တုဲ ဂၠာဲကၞုက်ကၞာဲအာအလုံ ဍုၚ်ရ။ (ဇ—၁၉၄။ အစွောံ။) = “(မင်း၏ပတ္တမြားပျောက်သွား၍ အမိန့်ချ၍ရှာစေရာ) မြို့သည် တပြိုင်နက်ချောက်ချားသည်ဖြစ်၏။” (ညောင်ကန်) || “တဳသုန္ဓရဳချိုတ်တုဲ အစာတဳတံကၞုက်ကၞာဲ တိုန်ရ။” (ဇ—၂၈၅။ အစွောံ။) = “သုန္ဒရီသေသည်ရှိသော် တိတ္တိတို့သည် အုတ်အုတ်ကျက် ကျက်ပြုကုန်၏။” || “တေံသၟိၚ်ဗာရာဏသဳတံဂှ် ပတၠသဒ္ဓါလောန် ကၞုက်ကၞာဲကၠေံအလုံဇမ္မုဒိတ်တုဲ မပ္တုဲဒါန်—။” (ဇ—၁၉၃။ အစွောံ။) = “(ဗာရာဏသီပြည့်ရှင်မင်းသည် သဒ္ဓါတရားထက်သန်သူ ဖြစ်၏။) ဇမ္ဗူဒိပ်ကျွန်းအလုံးကို ချောက်ချားစေ၍ အလှူကိုလှူ၏။” (ညောင်ကန်)')
,(1267,3,4,'၂။ (စိတ်) နောက်ကျုသည်၊—စေသည်။ စိတ်အနှောက်အရှက်ဖြစ်သည်၊—စေသည်။',' “ဗမၞးဂှ် ချပ်စံၚ်တူပ္ဍဲ ကောန်သမ္ဘာ ပြေၚ်ဂၠဴတိဗ္ၚကၠအ်သွဝ်တုဲ မၞုံစိုတ်မကၞုက်ကၞာဲတဴဂှ်ဒှ်တုဲ တၞဟ်နပကတ်ကွတ် ဟွံသၟဟ် ရထရ။” (ဇ—၁၈၅။ အစွောံ။) = “ထိုပုဏ္ဏားသည် သားမယား, ကျွဲနွား, လယ်ယာခြံမြေစသည်တို့­ စိုးရိမ်ပူပန်၍ နောက်ကျုသောစိတ်ရှိသည်ဖြစ်၍ အတတ်သင်ကြားပို့ချရန် မတတ်နိုင်။” || “(ကွးဂှ်) ညာတ်ဒုဟ်သမ္ဘာဇကုဂှ်တုဲ ဟိုတ်စိုတ်ကၞုက်ကၞာဲတဴတုဲ ဗၞတ်ၜါပိတ္ၚဲဝွံ ဟွံဂွံစိုပ် အ္စာရောၚ်။” (ဇ—၆၅။ အစွောံ။) = “တပည့်သည်လည်း မယား၏အပြစ်ကိုမြင်၍ နှောက်ရှက် သောစိတ်ရှိသည်၏အဖြစ်ကြောင့် နှစ်ရက်သုံးရက် (ဆရာ့ထံသို့ မလာဘဲနေ၏။)” (ညောင်ကန်) ||  “ဓဝ်ကိလေသဂှ် ကၞုက်ကၞာဲကၠေံစိုတ်တုဲရ။” (ဇ—၄၉၁။ အစွောံ။) = “ကိလေသာတရားသည် စိတ်ကို နောက်ကျုညစ်ညမ်းစေဖူးပြီ။”')
,(1267,3,4,'၃။ နှုတ်လုံသည်။ နှုတ်စောင့်သည်။','“ပ္ဍဲဋ္ဌာန် မချပ်ဂၞန်ပၞုက်လဒဵု၊ န်ညးမလေပ်ကၞုက်ကၞာဲ မမၚ်မွဲလဝ်ဂလာန်၊ ပ္ဍံနွံပၟိက်အိုတ်။” (ဂကောံစှ်စံၚ်။ နာဲမန်ၜိုပ်ထဝ်။ ရးဇြာ။) = “တိုင်ပင်ကုန်လတ်သော် နှုတ်စောင့်သောသူကို အလိုရှိကုန်၏။” ')
,(1270,3,1,'၁။ အစင်း။ အကွက်အကျား။ အစင်းကြောင်း။','ကၞၚ်ယာတ် = အဝတ်၏အဆင် အကွက်။ အစင်းအကွက်။ || ကၞၚ်ဂၞိန် = ထဘီအစင်း။ ထဘီအကွက်။ || ကၞၚ်ဂၠိက် = လုံချည်အ ဆင်။ လုံချည်အစင်း။ လုံချည်အကွက်။')
,(1270,3,1,'၂။ အကန့်။ အထစ်။ (လှေကားစသည်)','ကၞၚ်တၞိန်၊ တၞၚ်တၞိန် = လှေကားထစ်။ လှေကားအဆင့်။')
,(1271,3,1,'လည်စေ့။',null)
,(1272,3,1,'အစင်းအကွက်။','‘ဂၠဴမၞုံဇကုကၞၚ်ကၞောဝ်’ = ‘ကိုယ်အစင်းအကွက်ရှိသောနွား။’')
,(1273,3,1,'ကျားအစင်းကဲ့သို့သောအရာ။ ကျားအစင်း။',null)
,(1274,3,1,'လှေအကန့်။',null)
,(1275,3,1,'လှေခါးထစ်။',null)
,(1276,3,1,'အကိုင်း။','ကၞာၚ်ဆု = သစ်ကိုင်း။')
,(1276,3,4,'၁။ သစ်ကိုင်းချိုင်သည်။','“တၞံဆုဂှ် ကၞာၚ်ထောံကၠေံနကဵုမြညိ။” = “ထိုသစ်ပင်ကို ဓါးမဖြင့် အကိုင်းချိုင်လိုက်ပါ။”')
,(1276,3,4,'၂။ ဖြတ်တောက်သည်။','“ခမဳမၞုံကဵုဣဓိဇျှာန် မကဏာၚ်ကၠေံကိလေသ—။” (ဇ—၂၅၁။ အစွောံ။) = “ကိလေသာကို ဖြတ်တောက်ပစ်သော စျာန်တန်ခိုးရှိသောရဟန်း။”')
,(1277,3,1,'(သစ်ပင်) အကိုင်းအခက်။ အခက်အလက်။','“တၞံဇြဲသုံမွဲတၞံ ဍိုက်ပေၚ်တဴကေုာံကၞာၚ်သဝသၠတမဝ် ဂ္ညိဂ္ညာတ်တဴဂှ်—။” (ဇ—၂၁၃။ အစွောံ။) = “တစ်ခုသောပညောင်ပင်သည် အခက်အလက် အရွက်အဖူးတို့နှင့်ပြည့်စုံ၍ ဝေဆာနေ၏။”')
,(1278,3,1,'(ပင်စည်မဟုတ်သော) အကိုင်းအခက်။ အခက်အလက်။',null)
,(1279,3,1,'ပါး။ ပါးပြင်။',null)
,(1280,3,1,'ချုပ်ရာတွင်သုံးသောအပ်။','ကၞိၚ်က္ဍိုပ် = တွယ်အပ်။ ကၞိၚ်ထပက်ဂဥုဲ = ဆေးထိုးအပ်။')
,(1281,3,1,'၁။ အချောင်း။','တၞုၚ်ဇိုၚ်တၞုၚ်တဲ = ခြေချောင်းလက်ချောင်း။')
,(1281,3,1,'၂။ အပင်ပေါက်။ အညွန့်။','တၞုၚ်တၞံၜဲ = ပဲပင်ညွန့်။ || ကၞုၚ်လဵု = ဗူးညွန့်။ || ကၞုၚ်ခတောန် = ဍရၚ်ကောက်ညွန့်။')
,(1281,3,1,'၃။ အစွန်။ အဖျား။','ကၞုၚ်ကၟေၚ် = အိမ်ကပြင်အစွန်း။ || ကၞုၚ်ဆု = သစ်အစွန်း။ သစ်အဖျား။ || ကၞုၚ်ဇိုၚ် = ခြေအစွန်း။ ခြေအဖျား။ || ကၞုၚ်တဲ = လက်အစွန်း။ လက်အဖျား။')
,(1281,3,9,'သေးသွယ်ရှည်လျားသော အရာတို့ကို ရေတွက်ရာတွင် သုံးရသောစကားလုံး။ အချောင်း။','ဒုန်မွဲတၞုၚ် = ဝါးတစ်ချောင်း။ || လေံပိတၞုၚ် = တုတ်သုံးချောင်း။')
,(1282,3,1,'အစွန်းအဖျား။',null)
,(1283,3,1,'၁။ နဖူး။','ဂၠးကၞေၚ် = နဖူးပြင်။')
,(1283,3,1,'၂။ ကြက်ပေါင်သီး။', NULL)
,(1283,3,3,'ကျစ်ထားသော။','ဇုက်ကၞေၚ် = ကျစ်ထားသောကြိုး။')
,(1283,3,4,'ချည်ငင်သည်။ ရစ်သည်။','ကၞေၚ်တောဝ် = ချည်ငင်သည်။ (ယက္ကန်းသုံး)')
,(1284,3,1,'ကြံဟင်းပင်။ (သုံးမြှောင့်ပုံရိုးတံရှိ ဟင်းချက်စားရသည့် နွယ်ပင်တစ်မျိုး။)','ကၞေၚ်ကျာံလမ်စံက် = ကြံဟင်းညိုပင်။ (ပါဠိ—အဒ္ဓစန္ဒာ)')
,(1285,3,1,'နှောင်ဖွဲ့ခြင်း။ ချည်နှောင်ခြင်း။ အနှောင်အဖွဲ့။',null)
,(1286,3,1,'ခတ်ချိုညွန့်။',null)
,(1287,3,1,'မျက်ခုံး။',null)
,(1288,3,1,'ဆိတ်ချေးပင်။ (တံပူပြုလုပ်ရာတွင်သုံးသည်။)',null)
,(1289,3,1,'ယက္ကန်းရက်ဖောက်သီး။ ဗိုင်းငင်စက်ဝင်ရိုး။',null)
,(1290,3,1,'ဆိတ်ချေးသီး။',null)
,(1291,3,1,'ယက်မ။ (ဆင့်အောက်ခံသစ်သားချောင်း)','ကၞံၚ်သ္ၚိ = အိမ်ယက်မ။')
,(1292,3,1,'(ကစားစရာ) ဘောလုံး။ (ပါဠိ—ကန္ဒုက)','‘ကရောဲ’ လည်းရှု။')
,(1293,3,1,'‘ကၞောတ်’ ရှု။',null)
,(1294,3,1,'၁။ အပိုင်းအစ။','ကၞာတ်ဆု = သစ်သားစ။')
,(1294,3,1,'၂။ အရည်၊ အဆီစသည် ထုတ်ယူပြီး၍ ကျန်နေသောအဖတ်။ စုပ်ဖတ်။','ကၞာတ်က္ၜဴ = ကြံရည်ထုတ်ပြီးသောကြံဖတ်။ || ကၞာတ်လ္ၚဴ = (အဆီထုတ်ယူပြီးသော) နှမ်းဖတ်။ || ကၞာတ်မစ = စားဖတ်။ (ပါဠိ—စလက)')
,(1294,3,4,'၁။ တိုင်းတာသည်။','ၜတ်ကၞာတ် = တိုင်းတာသည်။')
,(1294,3,4,'၂။ အမှတ်ထားသည်။ အမှတ်ပြုသည်။ ထစ်မှတ်သည်။','‘ကၞောတ်ဆု’ = ‘သစ်ပင်ထိပ်ဖျား။’ || ‘ကၞောတ်ကြုၚ်’ = ‘ချောင်းဖျား။’ || ‘တမ်ဒေါဝ်ကၞောတ်’ = ‘အစ၊ အလယ်၊ အဆုံး။’')
,(1295,3,1,'၁။ ထိပ်ဖျား။ အဖျားပိုင်း။ အဆုံး။',NULL)
,(1295,3,1,'၂။ အထွတ်အထိပ်။ အထွတ်အမြတ်။','“ကျာ်တြဲသၟိၚ်ခမဳ မဒှ်ကၞောတ်ညးမပြဲဂှ် ဗွဲမရှ်ေသှ်ေရဴဂဴ အဲဍိက် လ္ၚောဝ်ရ။” = “သူမြတ်တို့၏ အထွတ်အထိပ်ဖြစ်တော်မူသော ရဟန်းတို့၏မင်းဖြစ်တော်မူသော မြတ်စွာဘုရားကို ရိုသေလေးမြတ်စွာ အကျွန်ုပ်ရှိခိုးပါ၏။” || “ဂၞကျာ်မဒ္ဒဳဂှ် ဒိုက်သၟဟ်သိုက်သၟဟ် မွဲဟာန်ကေုာံတြုံတၠသ္ၚိရောၚ်။ မဒှ်ကၞောတ်ဗြဴရ၊ မဒှ်အထောတ်ဗြဴရ။” = “မဒ္ဒဳမိဖုရားသည် လင်နှင့်အတူတကွ ဆင်းရဲအတူ ချမ်းသာအတူ နေထိုင်သူဖြစ်၏။ မိန်းမတကာတို့၏ အထွတ်အထိပ်ဖြစ်၏။” || “ပၞောဝ်ဒြဟတ်ဂမၠိုၚ်ဂှ် ဒြဟတ်ညာန်ပညာမွဲဂှ် မဒှ်ကၞောတ်ရ။” (ဇ—၅၂၁။ အစွောံ။) = “အင်အားများအနက် ဉာဏ်ပညာအင်အားသည် အထွတ်အထိပ်ဖြစ်၏။” ‘ကၞတ်’ ဟုလည်း ရေးသည်။')
,(1296,3,1,'တံစို့။ တံကျင်။','ဖျုန်မွဲကၞောတ် = အသားတစ်စို့။')
,(1296,3,4,'သီတံနှင့်သီသည်။','‘စၞတ်’ နှင့်အတူတူ။')
,(1297,3,1,'လျှာရင်း။ လျှာဖျား။ လည်ဖျား။',null)
,(1298,3,1,'လေညာ။ လေတိုက်ရာလမ်းကြောင်း၏ အထက်ပိုင်းအရပ်။','“နကဵု ကၟံၚ်ဗောဓိသတ်ဂှ် ဒွအ်ဂရိုက်ကသဳတၞံဓိတာန်ဂှ်တုဲ မပ္တံကၞာၚ်ဆုဇမ္ကဟ် သၠဆုဇမ္ကဟ်ပ္ကဴဇမြ စၟအချဴတံဂှ် ဒတုံပြဟ်စှ်ေ ဒးပ္ဍဲဇကုစူဠသုဘဒ္ဒါ သမ္ဘာဍောတ်ဂှ် မတဴလတူကၞတ်ကျာဂှ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “(ဘုရားလောင်းဆဒ္ဒန်ဆင်မင်းသည်) အင်ကြင်းပင်ကို ဦးကင်းဖြင့်ခိုက်၏။ ထိုအခါ စူဠသုဘဒ္ဒါမည်သော မိဖုယားသည် လေညာနံပါး­နေ၏။ ထိုစူဠသုဘဒ္ဒါမိဖုယားကိုယ်ပေါ်­ ခြောက် သောသစ်ခက်နှင့်ရောကုန်သော သစ်ရွက်ရော်တို့သည်၄င်း၊ ခါချဉ်တို့သည်၄င်း ကျကုန်၏။” (ညောင်ကန်) ‘တမ်ကျာ/တံကျာ’ လည်းရှု။')
,(1299,3,1,'ဘုရားအထွတ်တော်။',null)
,(1300,3,1,'ချောင်းဖျား။',null)
,(1301,3,1,'လမ်းထိပ်။',null)
,(1302,3,5,'နောက်ဆုံး။ အဆုံးစွန်။',null)
,(1303,3,1,'နောက်ဆုံးဘဝ။ အဆုံးစွန်သောဘဝ။','ပူဂဵုကၞောတ်ဘဝ = မစ္ဆိမဘ ဝိကသတ္တဝါ။ နောက်ဆုံးဘဝရောက်သောသူ။')
,(1304,3,1,'ဗုဒ္ဓသာသနာတော်၏ အဆုံးပိုင်းကာလ။ သာသနာတော် ကွယ်လုနီးသောကာလ။ သာသနာတော် ဆုတ်ယုတ်သောကာလ။','“ပ္ဍဲကာလဂှ် မဒှ်အာကၞတ် သာသနာရောၚ်။ ဟိုတ်မဒှ်ကၞတ်သာသနာဂှ်ရ ဂမှဳတံဂမၠိုၚ် ညံၚ်ဒ္ဂေတ်ခရှ်ကီု ဒ္ဂေတ်တဴအိုတ်ရ။” (၅၅ဝ။ ဇ—၄၆၉။ ၇—၁၆ဝ/၁၆၁။ အစွောံ။) = “ထိုအခါ­ သာသနာတော်သည် ဆုတ်ယုတ်၏။ သာသနာတော် ဆုတ်ယုတ်သောကာလဖြစ်၍ ရဟန်းအပေါင်းတို့သည် လူတို့၏အကျင့်ကဲ့သို့ ကျင့်ကြကုန်၏။”')
,(1305,3,1,'အထွတ်အထိပ်။',null)
,(1306,3,1,'သက်တမ်း၏အဆုံး။',null)
,(1307,3,1,'နောက်ဆုံးအရွယ်။ အိုမင်းရင့်ရော်သောအရွယ်။ ပစ္ဆိမအရွယ်။ (လူ့သက်တမ်းကို အနှစ် (၉ဝ) ဟုယူလျှင် အသက် (၆၁) မှ အသက် (၉ဝ) အထိကို ‘ပစ္ဆိမအရွယ်’ ဟုဆိုသည်။ အသက် (၉ဝ) အထက်လည်း အကျုံးဝင်သည်။)','‘ပစ္ဆိမအဝဲ’ နှင့်အဓိပ္ပါယ်အတူတူ။ || ‘ပစ္ဆိမအဝဲ’ ရှု။')
,(1308,3,1,'မြစ်ဖျား။',null)
,(1309,3,1,'အကွဲအစ။ အစိတ်အပိုင်း။','“ကြုက်ကြပ်ဟောံရ၊ သတ်ကြုက်မဇၞော်ဂေါဝ်တံ ဂှ် အိုတ်အာတုဲ သှ်ေဒၟံၚ်ဆကၞောန်ဍေံညိညရ။” = “သရက်သီးရာသီ ကုန်ဆုံးလုနီးပြီ၊ ကြီးလှ သောသရက်သီးများ ကုန်သွားပြီ၊ အသီးအသေးအဖွဲများ အနည်းငယ်မျှသာ ကျန်တော့သည်။”')
,(1310,3,4,'၁။ (သကြား၊ ထန်းလျက်စသည်) ညောင်စေးကျသည်အထိ ကျိုချက်သည်။','ကၞာန်ကဝ် = ထန်းလျက်ကို ညောင်စေးကျအောင် ကျိုချက်သည်။ ညောင်စေးကျစေသည်။')
,(1310,3,4,'၂။ ညောင်စေးကျသည်။','“ဍုန်လဝ်ဍာ်ကဝ်ဂှ် ကၞာန်တှ်ေ ဖျေံထောံညိ။” = “ချက်ထားသောထန်းလျက်ရည် ညောင်စေးကျလျှင် မီးဖိုမှချလိုက်ပါ။”')
,(1311,3,4,'ရောထွေးယှက်တၚ်သည်။ ကူးစက်ပျံ့နှံ့သည်။','“ယဲအေအာၚ်ဒဳအေတ်ဂှ် ကၞာန်ဒၟံၚ်အလုံလိုက်ရ။” = “အေအိုင်ဒီအက်(စ်)ရောဂါသည် တစ်ကမ္ဘာလုံးကို ကူးစက်ပျံ့နှံ့ နေသည်။”')
,(1312,3,4,'ကူးစက်ပျံ့နှံ့သည်။',null)
,(1313,3,4,'ရှုပ်ထွေးသည်။ ယှက်ထွေးသည်။ ရောထွေးသည်။',null)
,(1314,3,1,'အကွဲ။ အစ။ အပိုင်း။',null)
,(1315,3,1,'ဆန်ကွဲ။',null)
,(1316,3,1,'၁။ ဓါးအိမ်။','ကၞပ်ဇြၚ် = ဓါးအိမ်။')
,(1316,3,1,'၂။ တစ်ခုခုနှင့်တွဲဖက်၍ စားသောက်သောအစားအစာ။','ကၞပ်ဖရံက် = ငါးပိတို့စရာ။ || ကၞပ်သုရာ = အရက်သေစာနှင့် တွဲဖက်၍ စားသောအမြည်း။ || “ကၞပ်သွက်ဂွံကၠပ်ကဵုသုရာ အိုတ်အာဣရ။” = “အရက်နှင့်တွဲဖက် စားရမည့်အမြည်း ကုန်သွားပြီ။”')
,(1316,3,9,'စာအုပ်စသည်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။ တစ်အုပ်၊ တစ်စောင်။','လိက်ပိကၞပ် = စာအုပ်သုံးအုပ်။')
,(1317,3,4,'၁။ (အသံမရှိ) တိတ်ဆိတ်သည်။ (အသံမပြု) ဆိတ်ဆိတ်နေသည်။','“ဗှ်ေလ္ပဟီု ဗှ်ေကၞပ်။” (ဇ—၃၁၄။ အစွောံ။) = “နၚ်မပြောနှင့် နၚ်နှုတ်ပိတ်တိတ်လေ။” || “ဥပ္ပးအရဳမသုန်ကၠံဂှ် ကၞပ်ဒၟံၚ်ရ၊ ဟွံမွဲကဵုဗရုဗရန်ရ။” (ဇ—၁၈၃။ အစွောံ။) = “ငါးရာကုန်သော အရိယာဒါယကာတို့သည် အသံမပြုဘဲ ငြိမ်သက်စွာနေကြကုန်၏။၊”')
,(1317,3,4,'၂။ မလှုပ်မရှား ငြိမ်ငြိမ် နေသည်။ မလှုပ်မရှက် ငြိမ်သက်သည်။','“ကောန်ဒေဝတဴသၟာလှ်ေဂှ် ဇိုၚ်မွဲ တဲမွဲ ဂၞေဟ်မွဲ မတ် မွဲတံဂှ် သဝဲမွဲလ္ပာ်တုဲ လှ်ေဗဂေၚ်ဒၟံၚ်ဇကုရ။ ဇကုမွဲလ္ပာ်ဂှ် မံၚ်ကၞပ်ဒၟံၚ်တုဲ ဟွံဂွံချဳရ။” (ဇ—၄၈၉။ အစွောံ။) = “ထိုနတ်သဘၚ်သည်သည် လက်တစ်ဖက် ခြေတစ်ဖက် မျက်စိတစ်ဖက် အစွယ်တစ်ချောင်းတည်း လှုပ်၍က၏၊ ကိုယ်ထက်ဝက်သာ တုန်လှုပ်၏။ ကြွင်းသောကိုယ်ထက်ဝက်သည် မလှုပ်မရှက် ငြိမ်သက်စွာတည်၏။”')
,(1318,3,4,'တိတ်တဆိတ်နားထောင်သည်။ ခိုးနားထောင်သည်။','“မၞိဟ်ဗပုၚ်ဗပင်တံဂှ် ကၞပ်ကလၚ်ဒၟံၚ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “စုံစမ်းထောက်လှမ်းသောလူတို့သည် ခိုးနားထောင်နေ ကြကုန်၏။”')
,(1319,3,5,'တိတ်တဆိတ်။ ငြိမ်သက်စွာ။ လျှို့ဝှက်လျက်။','“ကၠဗြန်ဂှ် ကာလဗ္ၜေံတံဂှ် ဟိုတ်မာဲအာတုဲ ဗ္ၜေံကၟက်ကီု ဗ္ၜေံဗြဴကီု ကောန်ဗ္ၜေံတံဂှ်ကီု ဍေံကၠတ်ရပ်စကၞပ်ကၞပ်ရ။” (ဇ—၅၂၈။ အစွောံ။) = “ထိုကျားသစ်သည် ဆိတ်များ သတိလစ်ဟင်းသွားသောအခါ ဆိတ်ထီးတို့ကို၄င်း ဆိတ်မတို့ကို၄င်း ဆိတ်ကလေးတို့ကို၄င်း တိတ်တဆိတ်ခိုးယူဖမ်းစား၏။”')
,(1320,3,4,'နှုတ်ပိတ်ဆိတ်ငြိမ်သည်။ တိတ်ဆိတ်ငြိမ်သက်သည်။','“ဂလာန်ဗောဓိသတ်မဟီုဂှ် အမာတ်ဟီုခၠေဝ်ဟွံမာန်တုဲ ကၞပ်စိပ်ဒၟံၚ်ရ။” (ဇ—၅၂၈။ အစွောံ။) = “ဘုရားလောင်းဆိုသောစကားကို ထိုအမတ်သည် တုံ့ပြန်ဖြေဆိုခြင်းငှာ မတတ်နိုင်၍ နှုတ်ပိတ်ငြိမ်သက်လျက်နေ၏။”')
,(1321,3,4,'မှိုၚ်လျက်နေသည်။ မျက်နှာမသာဖြစ်သည်။ နှလုံးမသာမယာဖြစ်သည်။','‘ဇောဝ်’ တွင်ရှု။')
,(1322,3,1,'အရက်နှင့်တွဲဖက်စားသောအမြည်း။','‘စၞသုရာ’ နှင့်အတူတူ။')
,(1323,3,4,'တိတ်ဆိတ်စွာနေသည်။ ငြိမ်သက်စွာနေသည်။','“ယွံအနန်၊ ဥပ္ပးအရဳ မသုန်ကၠံဝွံတုန်လေဝ် ဆပ္ဍဲဘဝလၟုဟ် မကၞပ်သ္ၚဳဒၟံၚ်ဟွံသေၚ်၊ ပ္ဍဲဘဝမတုဲတေံကီုလေဝ် ကၞပ်သ္ၚဳဒၟံၚ် ကီုတုဲရ” ကျာ်တြဲဂး။ (ဇ—၁၈၃။ အစွောံ။) = “အာနန္ဒာ၊ — ဤဒါယကာတို့သည်လည်း ယခုအခါ­သာလျှင် ငြိမ်သက်စွာနေကုန်သည်မဟုတ်သေး။ ရှေး­လည်း ငြိမ်သက်စွာ နေဘူးကုန်သလျှင်ကတည်း။” (ညောင်ကန်)')
,(1324,3,4,'ဆိတ်ဆိတ်နေသည်။ တိတ်တိတ်နေသည်။','“ယွံခမဳတံ၊ — အတိက် တေံလေဝ် အဲထောံသ္ၚိကၟိန်ရ” ဂးတုဲ ကျာ်တြဲကၞပ်သ္ၚံဒၟံၚ်ရ။ (ဇ—၉။ အစွောံ။) = “ရဟန်းတို့၊ ငါဘုရားသည် ရှေး­လည်း အိမ်ထောင်နေခြင်းကို စွန့်ဖူးသည်သာလျှင်တည်း” ဟုမိန့်တော်မူ၍ ဆိတ်ဆိတ်နေတော်မူ၏။')
,(1325,3,4,'ငြိမ်သက်သည်။ ဆိတ်ဆိတ်နေသည်။','“ဂဒြဘဂမၠိုၚ်ဂှ် ဍေံသုၚ်ဒးဍာ်ဇဝါက်မုတ် ဒြာတ်တုဲ ဍေံဗ္ၜူတဴတုဲ ဍေံဒံၚ်ထလာ်တဴတုဲ ပ္ဍံဍေံဗြုဂအတ်တဴရ။ ချေံဂကူသိန္ဓဴတံ ဍာ်မုတ်ဒြာတ်မၞုံ ကုရှ်ဂှ် ဍေံသုၚ်တုဲ ဍေံကၞပ်သ္ၚိတ်ဒၟံၚ်အိုတ်ရ။” (ဇ—၁၈၃။ အစွောံ။) = “ဤမြည်းတို့သည် မုဒရက်ဖတ်အရည်ကို သောက်ရခြင်းကြောင့် ယစ်ကုန်သည်ဖြစ်၍ ခုန်လွှားပေါက်ကန်ဟစ်ကြွေးကုန် ၏။ သိန္ဓောမြင်းတို့သည်ကား အဦးဖြစ်သောအဖျော်ရည်ကို သောက်ကုန်၍ အသံကင်းကုန်လျက် ငြိမ်သက်စွာနေကုန်၏။”')
,(1326,3,1,'ဦးခေါင်း။','‘ပၠောတ်ကၞိပ်ပ္ဍဲတမ်ဇိုၚ်ကျာ်တြဲ။’ = ‘မြတ်စွာဘုရားခြေတော်ရင်း­ ဝပ်စင်းသည်။’ || “န်ကျာ်တြဲမဂြၚ်တီကေတ် ဓဝ်သစ္စပန်ဂှ် နကဵုကၞိပ်အဲ အဲလ္ၚောဝ်ကၠာတုဲ—။” (၅၅ဝ။ အစွောံ။) = “သစ္စာလေးပါးတရားကို သိမြင်တော်မူထသော မြတ်စွာဘုရားကို ငါ၏ဦးခေါင်းဖြင့် ရှိခိုးပါ၏။”')
,(1327,3,9,'စစ်ကြောင်း၊ စစ်အၚ်္ဂါသည်ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။ စစ်ကြောင်း။ စစ်အၚ်္ဂါ။','ဗဵုပၞာန်ပန်ကၞိပ် = အၚ်္ဂါလေးပါးရှိသောစစ်တပ်။ စစ်ကြောင်းလေးကြောင်း။ (ဆင်တပ်၊ မြင်းတပ်၊ ရထားတပ်၊ ခြေသည်တပ်ဟူသော ရှေးခေတ်စစ်အၚ်္ဂါလေးပါး။) || “သၟိၚ်ကောသလရး စဳရေၚ်ဗဵုပၞာန်ပန်ကၞိပ်တုဲ ဇက်ပ္ၚောံဍုၚ်ဗာရာဏသဳရ။” (ဇ—၅၁။ အစွောံ။) = “ကောသလပြည့် ရှင်မင်းသည် စစ်အၚ်္ဂါလေးပါးကိုစီရၚ်၍ ဗာရာဏသီပြည်သို့ စစ်ချီ၏။”')
,(1328,3,4,'ညှပ်သည်။ ကြားတွင်ညှပ်ထားသည်။','“ကၞေပ်လဝ်ယာတ် အကြာပါၚ်ကၞက်။”= “အဝတ်ကို ချိုင်းကြားတွင် ညှပ်ထားသည်။” || “ကၞေပ်လဝ်ၜံက် အကြာလပုဟ်တဲ။” = “ဆေးလိပ်ကို လက်ချောင်းကြားညှပ်ထားသည်။”')
,(1329,3,4,'ပွေ့ပိုက်သည်။',null)
,(1330,3,1,'ဆီး။ ကျင်ငယ်။',NULL)
,(1330,3,4,'ဆူသည်။ ဆူပွက်သည်။','‘ဍာ်ကၞမ်’ = ‘ရေဆူသည်။’')
,(1331,3,1,'အနှောင့်။ (ဓါး၊ ပုဆိန်စသည်တွင် အသွား၏ဆန့်ကျၚ်ဘက် ကျောရိုး။)','ကၞေမ်မြ = ဓါးနှောင့်။ (ပါဠိ—အသိထရု)')
,(1332,3,1,'ဆန်ကော။','“ခအဳခိုဟ်၊ ရိခိုဟ်၊ နခိုဟ်၊ ကၞာဲခိုဟ် အဲသၟိက်ဂွံရ” ဍိက်ဗြဴဂး။ (ဇ—၂၈၉။ အစွောံ။) = “ဆုံကောင်း၊ ကျည်ပွေ့ကောင်း၊ တောင်းကောင်း၊ ဆန်ကောကောင်း တို့ကိုငါလိုချင်၏။”')
,(1333,3,1,'၁။ ဆန်ခါ။',NULL)
,(1333,3,1,'၂။ (ဥပစာ) လျှို့ဝှက်စကားကို ပေါက်ကြားစေတတ်သူ။ နှုတ်မလုံသူ။', NULL)
,(1334,3,1,'ကွမ်းညှပ်။',null)
,(1335,3,1,'မျောက်။',null)
,(1336,3,1,'မျောက်ဖင်နီ။',null)
,(1337,3,1,'မျောက်ငိုပင်။',null)
,(1338,3,3,'သေးငယ်ပုညှက်သော။','ဂၠဴကၞေဲ = ပိန်သေးသောနွား။ || “ကောန်အဲဂှ် အယုက်ဍေံဟွံ ဍောတ်ရ။ ဆဂး ဍေံကၞေဲဒၟံၚ်။” = “ငါ့သားသည် အသက်မငယ်တော့ပါ။ သို့သော် သေးငယ်ပုညှက်နေသည်။”')
,(1338,3,4,'(လက်သည်းဖြင့်) ဆိတ်သည်။','“အဲကၞေဲစုတ်ကၞိၚ်ကောန်ၚာ်တုဲ ဗၟက်ဝေၚ်ရ။” = “ကလေးပါးပြင်ကိုဆိတ်၍ ကျွန်တော်ကျီစားသည်။”')
,(1339,3,1,'ကွပ်ပျစ်။ အိမ်ကပြင်။',null)
,(1340,3,1,'ငတ်မွတ်ခေါင်းပါးခြင်း။','ဘဲကၞောဝ် = ငတ်မွတ်ခြင်းဘေး။ “ပ္ဍဲရးကသဳကရးဂှ် ကၞောဝ်က္တဵုဒှ်တုဲ—။” (ဇ—၂ဝ၄။ အစွောံ။) = “ကာသိတိုင်း­ ငတ်မွတ်ခြင်းသည်ဖြစ်၏။” (ညောင်ကန်) ‘ကၠောဝ်’ (ကြိ) လည်းရှု။')
,(1341,3,1,'၁။ ကိုင်းလေး။',NULL)
,(1341,3,1,'၂။ (သစ်၊ ဝါးစသည်၏) အမျက်။ အဖုအဆစ်။',NULL)
,(1342,3,1,'ပင်လယ်လိပ်။ (အတုရတလေ)','ခၟာဲကၞုဟ် = လိပ်ဥ။')
,(1343,3,1,'၁။ ထန်းရွက်၊ ပေရွက်တွင် စာရေးရသောသံချွန်။ ကညစ်။',NULL)
,(1343,3,1,'၂။ အပိုင်းအစ။ အတံ။ အချောင်း။','ကၞေဟ်ဆု = သစ်သားအပိုင်းအစ။')
,(1343,3,1,'၃။ လေးတင်းဝင်သောတောင်း။', NULL)
,(1343,3,1,'၄။ ခါးစည်း။ ခါးပန်းကြိုး။',NULL)
,(1343,3,1,'၅။ ဂေါ်ပြား။ (မြေကော်ရန်)',NULL)
,(1344,3,1,'စလွယ်။ လက်ကြပ်စလွယ်။',null)
,(1345,3,1,'တောင်ပို့။','ကၞအ်ဒြုန် = ခြတောင်ပို့။')
,(1345,3,4,'(မျက်စိ) တိမ်စွဲသည်။', NULL)
,(1346,3,4,'မျက်စိနောက်သည်။ ကြည့်မရဖြစ်သည်။ အမြင်ကတ်သည်။',null)
,(1347,3,16,'‘ကဏေအ်’ ရှု။',null)
,(1348,3,1,'၁။ ရေကန်။',NULL)
,(1348,3,1,'၂။ အမြွာ။ အမြွာပူး။',NULL)
,(1348,3,3,'အမြွာဖြစ်သော။','ကောန်ကၟာ = အမြွာကလေး။ ‘ကမာ’ ရှု။')
,(1349,3,1,'တစ်ဘက်ဆည်ကန်။ (ပါဠိ—တဠာက)',null)
,(1350,3,1,'ယက်ဖောက်တညင်လုံး။ ချည်ရစ်လုံး။',null)
,(1351,3,1,'အမိုး။',NULL)
,(1351,3,4,'အမိုးမိုးသည်။',NULL)
,(1352,3,4,'ဖြူသည်။','ယာတ်ကၟု = အဝတ်ဖြူ။ || တိကၟု = မြေဖြူ၊ ပေါင်ဒါ။ || ချေံကမု = မြင်းဖြူ။ || က္ဍိုၚ်ကမု = ထီးဖြူ။')
,(1352,3,3,'ဖြူသော။',NULL)
,(1352,3,4,'(ကြိ) မှိုတက်သည်။ ချေးတက်သည်။ ဖားဥတက်သည်။ မိုးထင်းသည်။','“ပုၚ်ပ္ဍဲဘာဇနဂှ် သ္အုဲကၟုဒှ်အာပ္တိုဟ်ရောၚ်။” (ဇ—၂၅၁။ အစွောံ။) = “သပိတ်ထဲမှထမင်းတို့သည် ပုပ်သိုး၍ မှိုတက်ကုန်၏။”')
,(1353,3,1,'မို။ (ပုံသွန်းလောင်းရန်ပုံစံ)',null)
,(1354,3,1,'ထမ်းပိုး။','ကၟးကွဳ = လှည်းထမ်းပိုး။')
,(1355,3,1,'၁။ (တိရစ္ဆာန်) အထီး။ အဖို။','ဂၠဴကၟက် = နွားထီး။')
,(1355,3,1,'၂။ အဆွဲ။ (စာပေ)','ကၟက်မန်စှ်သာ် = မွန်စာရှိအဆွဲဆယ်မျိုး။')
,(1355,3,1,'၃။ အဆွဲ။ ဆွဲသောအရာ။','နကၟက် = ဆွဲတောင်း။ || ကၟက်ကအ် = လည်ဆွဲ။ ‘ကွက်’ (ကြိ) လည်းရှု။')
,(1355,3,1,'၄။ လယ်ထိကရုန်း။ (ဟင်းရွက်)',NULL)
,(1356,3,1,'နားသန်။ နားသန်သီး။ (တွဲလောင်းဆွဲ၍ ဝတ်ဆင်ရသော နားအဆင်တန်ဆာ) (ပါဠိ—ဝလ္လိကာ)',null)
,(1357,3,1,'လည်ဆွဲ။ ဆွဲကြိုး။ လည်ရွဲတန်ဆာ။ (ပါဠိ—ကဏူဌသုတ္တက)',null)
,(1358,3,1,'၁။ အူများကို ဖုံးအုပ်ထားသော အကြောပြင်၊ အဆီပြင်။',NULL)
,(1358,3,1,'၂။ ရှောက်နူပင်။',NULL)
,(1359,3,1,'ဆီဘူးဆွဲ။ အခြၚ်ဝါးများကို အောက်ဘက်မှတွယ်၍ ကန့်လန့်ချည်တုပ်ထားသောဝါး။ (အိမ်ခေါင်တွင်ပါဝင်သော အစိတ်အပိုင်း)',null)
,(1360,3,1,'(ခန္ဓာကိုယ်တွင်းရှိ) ကျောက်ကပ်။',null)
,(1361,3,1,'လယ်ထိကရုန်း။ (ဟင်းရွက်)',null)
,(1362,3,1,'ရေထိကရုန်း။ (ဟင်းရွက်)',null)
,(1363,3,4,'အိပ်ပျော်နေစဉ် ယောင်ယမ်းသည်။','‘တၟုက်’ ဟုလည်းရေးသည်။')
,(1364,3,4,'အိပ်ပျော်နေစဉ် ယောင်ယမ်းသည်။','‘တၟုက်တၟဝ်’ ရှု။')
,(1365,3,4,'ပဲ့သည်။','“ဆုဂတဵုဂှ် ကၟေက်တိတ်အာရ။” = “သစ်ပျဉ်ပြားက ပဲ့ထွက်သွားပြီ။” || ပါၚ်ကၟေက် = ပါးစပ်ပဲ့သည်။')
,(1366,3,4,'တွက်သည်။ တွက်ချက်သည်။','“ဂတှ်ပိုဲဒးလေဲဂှ် တၟော်လဝ်တုဲရဟာ။” = “ငါတို့လျော်ရမည့် အကြွေးကို တွက်ထားပြီးပြီလား။”')
,(1366,3,1,'အတွက်အချက်။','“လၟတုန် လၟေၚ်ကၟော် ဍေံမတော်ကဵုဂှ် ဟွံဂွံစၟတ်ဗိုန်က္ညန်(ရ။)” (၅၅ဝ။ ဇ—၄၄ဝ။ ဒု—၆၆၁။ အစွောံ။) = “မုဆိုးသည် သူတွက်ချက်ပေးသော အတွက်အချက်ကို သေချာစွာ မစိစစ်ခဲ့ရပါ။” || ‘တော်’ (ကြိ) လည်းရှု။')
,(1367,3,4,'(ခွက်၊ ပုံးစသည်ဖြင့်) ခပ်သည်။','ကၟံက်ဍာ် = ရေခပ်သည်။ || “သ္ၚုဂှ် ကၟံက်စုတ်ပ္ဍဲန ညိ။” = “ထိုဆန်ကို တောင်းထဲသို့ ခပ်ထည့်လိုက်ပါ။”')
,(1368,3,1,'၁။ ယောက်သွား။ ဂုံးကောင်။','၂။ ပြုတ်တူ။ (လက်သမားသုံး)')
,(1369,3,1,'၁။ နံရံ။ မြို့ရိုး။','ကၟာၚ်ဍုၚ် = မြို့ရိုး။ || ကၟာၚ်ကျာ် = ဘုရားတံတိုင်း။')
,(1369,3,1,'၂။ ထူးကွင်း။ ခြေကျင်း။','ကၟာၚ်စိၚ် = ဆင်ထူးကွင်း။ ဆင်ခြေကျင်း။ ‘တမာၚ်/တၟာၚ်’ ဟုလည်းရေးသည်။')
,(1370,3,1,'အမိုးမရှိသောအိမ်ကပြင်။',null)
,(1371,3,1,'ယက္ကန်းစင်။',null)
,(1372,3,1,'အိမ်ရှေ့လေသာဆောင်။',null)
,(1373,3,1,'ဦးကင်း။','ကၟံၚ်စိၚ် = ဆင်ဦးကင်း။ (ပါဠိ—ဂဇကုမ္ဘ) “(သၟိၚ်စိၚ်) နလပှ်ဇွိတ်သ ပေါတ်ကောန်ၚာ်ဂှ်တုဲ မိန်ကေတ်သၟတ်ဂှ်တုဲ ပတိုန်စွံလဝ်လတူကၟံၚ်—။” (ဇ—၁၅၆။ အစွောံ။) = “ဆင်သည် (ကလေးငယ်ကို) နှာမောင်းဖြင့် သုံးသပ်ပြီးလျှင် ချီ၍ ဦးကင်း­ထား၍—။”(ညောင်ကန်)')
,(1373,3,3,'(ဦးခေါင်းနောက်ပိုင်း) မိုမောက်သော။','“ကောန်ၚာ်တြုံဂှ် က္ဍိုပ်ကၟံၚ်ဒၟံၚ်ရ။” = “ထိုကလေးသည် ဦးခေါင်းနောက်ပိုင်း မိုမောက်နေသည် (ဝါ) နောက်စေ့ထွက်နေသည်။”')
,(1374,3,4,'(သစ်ပင်) အမြစ်လှန်သည်။ အမြစ်လန်စေသည်။ လှဲပစ်သည်။','“ဒးလဗိုတ်ကျာ တၞံဆုဂှ် ကၟိုၚ်အာသီုရိုဟ်ရ။” = “လေမုန်တိုင်းသင့်၍ ထိုသစ်ပင်သည် အမြစ်ပါကျွတ်လန် သွား၏။” || “မူပမၞးတံကုတ်တမိုၚ်ရိုဟ်ဇြဲပၠန်ရော။” (ဇ—၄၉၃။ အစွောံ။) = “ဤညောင်ပင်ကို အဘယ်ကြောင့်သင်တို့ အမြစ်လှန်ခုတ်ပစ်ပြန်ပါသနည်း။”')
,(1374,3,4,'၂။ (လှည်းစသည်) ဦးထောင်ကျသည်။','“ကွဳဂှ်ကၟိုၚ်အာတုဲ အပေါတ်ပ္ဍိုက်လဝ်လတူကွဳဂှ် ဗကပ်စှ်ေအာအိုတ်ရ။” = “ထိုလှည်းသည် ဦးထောၚ်လဲကျသွားသဖြင့် လှည်းပေါ်မှပစ္စည်းများ မှောက်ကျသွားကုန်၏။”')
,(1375,3,4,'အပင်လှဲ၍ အမြစ်ပါနှုတ်ပစ်သည်။ (ကျူပင်ခုတ် ကျူၚုတ်ပါမကျန်စေနှင့်။)',null)
,(1376,3,1,'မြက်။','‘ကမတ်’ ရှု။')
,(1377,3,4,'ပိတ်သည်။','ကၟာတ်တရၚ် = တံခါးပိတ်သည်။ || ကၟာတ်ကတောဝ် = နားပိတ်သည်။')
,(1378,3,1,'လင်းတငှက်။',null)
,(1379,3,4,'နှုတ်ပိတ်သည်။ မပြောမဆိုဘဲ ဆိတ်ဆိတ်နေသည်။ ရေငုံနေသည်။',null)
,(1380,3,1,'အောက်ချင်းငှက်။',null)
,(1381,3,4,'သုတ်သုတ်ပြုလုပ်သည်။','ကၟန်အာ = ခပ်သုတ်သုတ်သွားသည်။ သုတ်ခြေတင်သည်။ || ကၟန်ကၠောန် = မြန်မြန်လုပ်သည်။ || “ကၟန်ပြဟ်” ဂးတုဲ အဝဲါဂှ် ဗက်အာရ။ (ဇ—၈၉။ အစွောံ။) = “မြန်မြန်လုပ်” ဟုဆိုကာ ချက်ချင်းလိုက်သွား၏။ || “ယာံနွံပၟိက်ကဵုလမျီု ကၟန်အာကၠေံပြဟ်ရ။” (ဇ—၁၈၁။ အစွောံ။) = “အသက်ကို အကယ်၍အလိုရှိလျှင် အမြန်ပြေး ကြကုန်လော့။”')
,(1382,3,4,'တင်းသည်။ ကျပ်သည်။ သိပ်သည်းသည်။','“ပလၚ်ဂှ် ကဝဲလဝ်ဒကိုပ်ဍေံ ကၟောန်အာတုဲ ကလေၚ်ပံၚ်ဟွံလောဲရ။” = “ထိုပုလင်းကို ဖုံးပိတ်ထားသည်မှာ တင်းကျပ်လွန်းသဖြင့် ပြန်ဖွင့်၍မလွယ်ပါ။” ‘ကမန်’/‘ကမောန်’ ရှု။')
,(1383,3,4,'အားခဲသည်။ စိတ်အားတင်းသည်။',null)
,(1384,3,1,'တူ။ တူမ။','ကၟိန်တြုံ = တူ။ || ကၟိန်ဗြဴ = တူမ။')
,(1385,3,11,'(န) ငါးထောင်သောမြှုံး။ (ပါဠိ—ကုမိန)','“သၟိၚ်ကောသလရးဂှ် ညံၚ်ရဴကမလုပ် ကၟိန်ကီု စိုပ်သကေံတဲဇကုတုဲ ဂွံကေတ်အဇာတသတြုရ။” (ဇ—၄၉၂။ အစွောံ။) = “ကောသလ မင်းသည် မြှုံး­ဝင်မှားသောငါးကဲ့သို့ မိမိလက်သို့ရောက်၍ ထိုအဇာတသတ်မင်းကို အရဖမ်းယူနိုင်၏။” || “မၞိဟ်တံပံါစကၟိန်ပ္ဍဲကြုၚ်ဂှ်။ ပ္ဍဲကၟိန်ဂှ် ကဗွဲမဂၠိုၚ်လောပ်အာရ။” (ဇ—၂၃၉။ အစွောံ။) = “လူတို့သည် မြစ်ချောင်းအစရှိသည်တို့တွင် ထိုထိုအရပ်­ ငါးကိုဖမ်းအံ့သောငှာ မြှုံးတို့ကို ထောၚ်ကုန်၏။ တခုသောမြှုံး­ ငါးတို့သည် ဝင်ကုန်၏။” (ညောင်ကန်)')
,(1386,3,1,'တိုင်းပြည်။ တိုင်းနိုင်ငံ။','‘စၟိန်ဍုၚ်’ ဟုလည်း အနည်းအားဖြင့် တွေ့ရသည်။ || “ယွံသၟိၚ်မပြဲ၊ သၟိၚ်နာ်တၠဣဓိတၠသ္ၚိအဲဝွံဂှ် အလုံကၟိန်ဍုၚ်ရးအိုဿီုဂှ် သ္ဂောံဒှ်အာပ္တေၚ်မာန်ရ။” (ဇ—၅ဝ၆။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ တန်ခိုးရှင်ဖြစ်သော အကျွန်ုပ်လင်နဂါးမင်းသည် တိုင်းနိုင်ငံအလုံးကိုလည်း ဖွဲပြာဖြစ်အောင် ပြုနိုင်ပါ၏။”')
,(1387,3,1,'ထီးနန်း။ မင်းစည်းစိမ်။','“ဟိုတ်နူဒြဟတ်လွဳအဲ လဗိုန်ဒၟံၚ်သဳလတုဲ ပိုန်ကၟိန်နန်ဗဗွဲဓဝ် ညးမဒးကလေၚ်ဇိုန်ကဵုအဲ ကလိဂွံစသိုၚ်ရောၚ်သွံ” သၟိၚ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “သီလ­မြဲသော ငါ၏လုံ့လအစွမ်းအားဖြင့် တရားသောထီးနန်းစည်းစိမ်ကို (ရန်သူမင်းသည်) ငါ့အားပြန်ပေးရ၏။” || “ဟိုတ်အဲမတန်ဒၟံၚ် ပ္ဍဲဒလောအ်ဗ္တောန်ပစ္စေဂဗုတ် တုဲ ပိုန်ကၟိန်နန်ကျာ်သြဳသာ်ဝွံ အဲမက လိဂွံရောၚ်” ဗောဓိသတ်ချပ်။ (ဇ—၁၃၂။ အစွောံ။) = “ငါသည် အရှင်ပစ္စေကဗုဒ္ဓာ၏ အဆုံးအ မ­တည်သည်ဖြစ်၍ ဤသို့အသရေရှိသော ထီးနန်းစည်းစိမ်ကို ရရှိပေ၏။”')
,(1388,3,4,'အမြတ်အစွန်း။ လာဘ်။','“ညးဗၞိက်ၜါဂှ် ဒက်မိတ်သဟာဲတုဲ — အာပ ဗၞိက်ရ။ နကၟိန်ပရဲကလိဂွံတုဲ ကလေၚ်စဴဍုၚ်သာရဝှ်ရ။” (ဇ—၂၁၈။ အစွောံ။) = “ကုန်သည်နှစ် ယောက်တို့သည် အဆွေခင်ပွန်းဖွဲ့၍ ကုန်အရောင်းအဝယ်သွား၏။ အမြတ်အစွန်းရရှိ၍ သာဝတ္ထိမြို့သို့ ပြန်လာကြကုန်၏။”')
,(1389,3,1,'ပြည်။ နိုင်ငံ။','ကၟိန်မြုနိဗ္ဗာန် = နိဗ္ဗာန်ရွှေပြည်။')
,(1390,3,4,'‘ကၞိက်ကၟုန်’ ရှု။',null)
,(1391,3,4,'ခြေလက်ဖြင့်ဖက်တွယ်၍ တက်ဆင်းသည်။','‘ကၟေန်တိုန်တၞံဆု’ = ‘သစ်ပင်ပေါ်တွယ် တက်သည်။’ || “ကၞုဲဂမၠိုၚ်ကၟေန်စှ်ေနူဆု။” (ဇ—၁၇၇။ အစွောံ။) = “မျောက်များသည် သစ်ပင်ပေါ်မှ ဖက်တွယ်ဆင်းကြကုန်၏။”')
,(1392,3,4,'ခိုင်ခံ့သည်။ မြဲမြံသည်။',null)
,(1393,3,1,'တာတမံ။ တာရိုး။',null)
,(1394,3,1,'ပရိသတ်။ လူစုလူဝေး။ ကြွရောက်လာသောလူထု။','‘တၟပ်’ ရှု။')
,(1395,3,3,'မေးစေ့ထွက်သော။ မေးစေ့ေငါထွက်သော။',null)
,(1396,3,4,'တဟုန်ထိုးလာသည်။ အရှိန်ဖြင့်လာသည်။ ဒုန်းစိုင်းလာသည်။','“ချေံကၟိုပ်ကၠုၚ်ရ။” = “မြင်းတဟုန်ထိုးလာသည်။”')
,(1397,3,1,'ဝံ။ ဝက်ဝံ။ (ပါဠိ—အစ္ဆ/ အစ္ဆက)', NULL)
,(1397,3,4,'သင့်တော်သည်။ ထိုက်သင့်သည်။', NULL)
,(1398,3,1,'ဝက်ဝံ။ (ပါဠိ—အစ္ဆ/ အစ္ဆက)','ကၟီကၠိက်ဗ္တာၚ် = ဝက်ဝံဖြူ။ ပိုလာဝက်ဝံ။ || ကၟီကၠိက်လမ်စံက် = ဝက်ဝံနက်။ အပူပိုင်းဒေသဝက်ဝံ။')
,(1399,3,1,'လူဝံ။',null)
,(1400,3,4,'၁။ မုဆိုးမ, မုဆိုးဖိုဖြစ်သည်။','“သၟတ်ဗြဴဂှ် တြုံတၠသ္ၚိဍေံချိုတ်အာတုဲ ကၟာဲဒၟံၚ်ရ။” = “ထိုမိန်းမငယ်သည် လင်သေဆုံးသွား၍ မုဆိုးမဖြစ်နေသည်။” || ဗြဴကၟာဲ = မုဆိုးမ။ || တြုံကၟာဲ = မုဆိုးဖို။"')
,(1400,3,4,'၂။ ပုခုံးပေါ်လွယ်သည်။','ကၟာဲထိုၚ် = လွယ်အိတ်လွယ်သည်။')
,(1402,3,1,'လုံချည်ကွင်းသိုင်းသည်။',null)
,(1403,3,1,'ဧည့်သည်။',null)
,(1404,3,1,'‘ကၟုဲ’ နှင့် အဓိပ္ပါယ်အတူတူ။',null)
,(1405,3,1,'တစ်ရပ်တစ်ကျေးမှ လာသောဧည့်သည်။',null)
,(1406,3,1,'၁။ ဖျာ။ အခင်း။ ကော်ဇော။ ကမ္ဗလာ။','သၞာပဏ္ဍုကၟဝ် = သိကြားမင်းထိုၚ်ရာ ပဏ္ဍုကမ္ဗလာမြကျောက်ဖျာ။')
,(1406,3,1,'၂။ သားမွေးစသည်ဖြင့် ရက်သောအထည်။ သိုးမွေးအနွေးထည်။','ယာတ်ကၟဝ် = သားမွေးအဝတ်ပုဆိုး။')
,(1407,3,1,'သစ်ရွက်နု။','ကၟဝ်ပတုက် = ကျည်းပင်ရွက်နု။ || ကၟဝ်သိၚ်ဃဵု = သီဟိုဠ်ရွက်နု။ || ကၟဝ်မၚ်ဂၠန် = မန်ကျည်းရွက်နု။')
,(1407,3,4,'ရွက်နုထွက်သည်။ ရွက်သစ်ထွက်သည်။','“တၞံမၚ်ဂၠန်ဂှ် ကၟဝ်ဒၟံၚ်ရ။” = “ထိုမန်ကျည်းပင်သည် ရွက်နုထွက်နေပြီ။” ‘လၟဝ်’ ဟုလည်း အရေးရှိသည်။')
,(1408,3,4,'အပ်ကြောင်းထပ် ပြောဆိုရေရွတ်သည်။',null)
,(1409,3,3,'(မြင်းစသည်) ခါးကျိုးတတ်သောအမျိုးဖြစ်သော။ သာမန်အမျိုးဖြစ်သော။','‘ချေံတ မၞီကၟဝ်ဂၞိၚ်။’ (ဇ—၂၄။ အစွောံ။) = ‘ခါးကျိုးတတ်သော သာမန်ဝဲစားမြင်းမျိုး။’')
,(1410,3,1,'သမဲ့ပင်။ (ရေငန်စပ်တွင်ပေါက်သော အပင်စောက်ကြီးတစ်မျိုး)',null)
,(1411,3,1,'၁။ ကွမ်းအန်ဖတ်။',NULL)
,(1411,3,1,'၂။ စားမြုံ့ပြန်ခြင်း။',NULL)
,(1411,3,1,'၃။ အရုံ။ အဖုတ်။ အအုံ။ အစု။','ကၟဵုကၟတ်ဒဇိပ် = မြေစာမြက်စု။ || ကၟဵုဝါၚ်ဗိုၚ် = စပါးလင်ရုံ။ || ကၟဵုဒုန် = ဝါးရုံ။')
,(1411,3,9,'ဝါးရုံ၊ စပါး လင်ရုံ၊ မြေစာမြက်စုစသည်တို့ကို ရေတွက်ရာတွင် သုံးသောစကားလုံး။ (တစ်ရုံ။ တစ်ဖုတ်။ တစ်အုံ။ တစ်စု။)','ဒုန်ၜါကၟဵု = ဝါးရုံနှစ်ရုံ။ ချောဲဒဇိပ်မွဲကၟဵု = နေစာမြက်စုတစ်စု။')
,(1412,3,1,'ကျိတ်မှန်ပင်။',null)
,(1413,3,1,'တံမြက်စည်း။','‘ကွဟ်/တွံ’ (ကြိ) လည်းရှု။')
,(1414,3,1,'ငါးဖမ်းထောင်ချောက်။',NULL)
,(1414,3,3,'အေးသော။ အကျန်ဖြစ်သော။','ဍာ်ကၟုဟ် = ရေအေး။ || ပုၚ်ကၟုဟ် = ထမင်းကြမ်း။')
,(1415,3,4,'ဝေသည်။ ဝေလျှံသည်။','“ဗြဲဂူ ဍာ်ကၟိုဟ်အာဇရဳရ။” = “မိုးရွာ၍ စဉ့်အိုးကြီးမှ ရေလျှံကျသည်။”')
,(1416,3,4,'နားမဆံ့ဖြစ်သည်။ မကြားချင်အဆုံးဖြစ်သည်။',null)
,(1417,3,1,'ကျောက်ကပ်။',null)
,(1418,3,4,'ဆွဲငင်သည်။','“ကၟေအ်ဖျေံကၞာၚ်ဍေံတုဲ ၜှ်ကေတ်ပ္ကဴတအ်ဂှ်ရ။” = “ပန်းပင်အကိုင်းကို ဆွဲငင်ချ၍ ပန်းတို့ကိုခူးယူသည်။”')
,(1418,3,1,'အိုးဗုတ်ပင်။', NULL)
,(1419,3,4,'ရှုံးသည်။','“—၊ ညးဂှ်မကျ ညးဂှ်မဇၞးရောအဴ။” (ဇ—၃ဝ၁။ အစွောံ။) = “မည်သူသည် ရှုံး၍ မည်သူသည်အောင်မည်နည်း။”')
,(1420,3,4,'အမှုရှုံးသည်။ တရားရှုံးသည်။','“(သမ္ဘာတမ္ၚာသမၠီုဂှ်) ပကြံဗ္ဂန်ဂလာန် ပလီုစိုတ် ညးပဂဗုတ်ဒဵုစိုပ်တၠခွါ ကျဂဗုတ် ညးရပ်ဒက်ပဘဲ—။” (ဇ—၁၃၉။ အစွောံ။) = “မိုုက်မဲသော တံငါသည်မယားသည် သူတစ်ပါးတို့အား အနိုင်ကျင့်ပြဿနာရှာကာ အချစ်ပျက်စေ၍ ရွာစားဆီ ရောက်သည့်တိုင် တရားစွဲဆို၏။ တရားရှုံး၍ ချုပ်နှောင်ဒဏ်ပေးခြင်းခံရ၏။”')
,(1421,3,4,'စကားရှုံးသည်။ အဆိုရှုံးသည်။',null)
,(1422,3,4,'ဆုံးရှုံးသည်။ ကျရှုံးသည်။ ရှုံးနိမ့်သည်။','“ညံၚ်သရာဲဒယှ်ရ လဆောဝ်မှာရာ ဒးကျဆောံတုဲ မရံၚ်ဂွာံကလေၚ်ဇၞးကီု။” (ဇ—၁၄၈။ အစွောံ။) = “သူရဲကျော်ကဲ့သို့ တစ်ခါတစ်ရံ မှားယွင်းကျရှုံးရ၍ တစ်ဖန်အနိုင်ယူရန် အခွင့်ကောင်းကို ကြည့်ရာ၏။”')
,(1423,3,4,'ဆင်းရဲခြင်းဒဏ်ကို မခံနိုင်ဖြစ်သည်။ ဒုက္ခကိုမခံစားနိုင်ဖြစ်သည်။','“ကာလဆဵု ညာတ်ဒဒိုက် ကျဒဒိုက်တုဲ ပွမယာံတဴဂှ် ဂုန်ဖဵုဟွံမွဲရ။” = “ဒုက္ခတွေ့သောအခါ ခံနိုင်ရည်မရှိဘဲ ငိုကြွေးခြင်းသည် အကျိုးမရှိပါ။”')
,(1424,3,4,'လောင်းကစားရာတွင်ရှုံးသည်။',null)
,(1425,3,4,'စစ်ရှုံးသည်။',null)
,(1426,3,4,'လောင်းကစားရာတွင်ရှုံးသည်။',null)
,(1427,3,4,'ကုန်ရှုံးသည်။ ကုန်သွယ်ရာတွင် အရှုံးပေါ်သည်။',null)
,(1428,3,4,'မယားကြောက်ဖြစ်သည်။',null)
,(1429,3,4,'ဆုံးရှုံးသည်။',null)
,(1430,3,4,'မဲရှုံးသည်။',null)
,(1431,3,4,'တရားရှုံးသည်။ တရားရၚ်ဆိုင်ရာတွင်ရှုံးသည်။','“ခမဳဂမၠိုၚ် ဟီုအကြီုပြောဟိတ် ကျအာသၞောဝ်” (ဇ—၃၃၂။ အစွောံ။) = “ရဟန်းတို့သည် ပုရောဟိတ်တရားရှုံးသွားသောအ ကြောင်းကို ပြောဆိုကုန်၏။”')
,(1432,3,4,'အမှုရှုံးသည်။ တရားရှုံးသည်။',null)
,(1433,3,4,'စကားရှုံးသည်။',null)
,(1434,3,4,'အာဏာကို မလွန်ဆန်နိုင်ဖြစ်သည်။',null)
,(1435,3,4,'အမိန့်ကို မလွန်ဆန်ဝံ့ဖြစ်သည်။',null)
,(1436,3,1,'သူရဲဘောကြောင်သူ။',null)
,(1437,3,1,'၁။ လေ။',NULL)
,(1437,3,1,'၂။ စကား။','“ဍေံဂှ် ကျာကၠးကၠးရ၊ မူလေဝ်ကၠောန်ဟွံဒှ်မွဲသာ်ရ။” = “သူဟာ လေပေးသက်သက်ဘဲ၊ ဘာတစ်ခုမျှ လုပ်နိုင်တာမရှိဘူး။”')
,(1437,3,1,'၃။ အနံ့။','“အဲဂွံဒၟံၚ်ကျာ ဒူရေန်” = “ငါဒူးရင်းသီးအနံ့ရနေတယ်။”')
,(1437,3,3,'လေပေးသည်။ လေလုံးကြီးသည်။','“လ္ပကျာဂၠိုၚ်၊ ကျာဂၠိုၚ် ကလၚ်ဟွံမာန်ရ။” = “လေလုံးမကြီးနှင့်၊ လေလုံးကြီးလျှင် နားမထောင်နိုင်တော့ပါ။”')
,(1438,3,1,'လေပုပ်။',null)
,(1439,3,1,'လေကဒေါ့။','(ကြိ) လေဝှေ့သည်။')
,(1440,3,1,'သားဖွားနိုင်အောင် တွန်းပေးသောလေ။ ကမ္မဇလေ။',null)
,(1441,3,4,'လေကောင်းသည်။ စကားကောင်းသည်။','“ရံၚ်စမ်။ ကျာခိုဟ်ဒၟံၚ်ညးသ္ကအ်ဂှ် တက် အာစှ်နာဍဳရ။” = “ကြည့်စမ်း။ လေကောင်းနေလိုက်တာ၊ ဆယ်နာရီတောင်ထိုးသွားပြီ။”')
,(1442,3,1,'လေပူ။',null)
,(1443,3,1,'လေပုပ်။ အီး။',null)
,(1444,3,4,'လေလည်သည်။ လေသက်သည်။',null)
,(1445,3,1,'လေအားပျော့သည်။',null)
,(1446,3,4,'လေချဉ်တက်သည်။',null)
,(1447,3,4,'လေထန်သည်။ လေပြင်းသည်။',null)
,(1448,3,1,'လေပြင်း။ လေမုန်တိုင်း။',null)
,(1449,3,1,'ဝမ်းဗိုက်အတွင်းရှိလေ။',null)
,(1450,3,4,'လေခံသည်။ အစာအိမ်တွင်း­ လေလွန်ကဲ၍ အခုအခံဖြစ်နေသည်။',null)
,(1451,3,1,'လေပွေ။',null)
,(1452,3,1,'အနောက်လေ။',null)
,(1453,3,4,'လေတိုက်သည်။',null)
,(1454,3,4,'လေကုန်သည်။ စကားပြောဆိုရကျိုးမနပ်ဖြစ်သည်။',null)
,(1455,3,1,'လေတဖြူးဖြူးတိုက်သည်။',null)
,(1456,3,1,'လေခုသည်။ လေခံသည်။',null)
,(1457,3,1,'အရှေ့လေ။ အရှေ့မြောက်ရာသီလေ။',null)
,(1458,3,1,'(မိုးမရွာခင်တိုက်ခတ်သော) လေအေး။',null)
,(1459,3,4,'မိုးလေမှန်သည်။',null)
,(1460,3,1,'မုတ်သုန်လေ။',null)
,(1461,3,1,'လေပြင်း။ လေမုန်တိုင်း။',null)
,(1462,3,1,'လေစဲသည်။',null)
,(1463,3,1,'လေတဖြူးဖြူးတိုက်သည်။',null)
,(1464,3,1,'လေဆင်နှာမောင်း။',null)
,(1465,3,4,'လေလည်သည်။ လေသက်သည်။',null)
,(1466,3,1,'ကမ္ဘာဖျက်လေ။',null)
,(1467,3,4,'လေအန်သည်။',null)
,(1468,3,1,'လေပြင်းမုန်တိုင်း။ လေဆင်နှာမောင်း။ ဝေရမ္ဘလေ။','“ယွံခမဳ၊ ဆလၟုဟ်ဟွံသေၚ်၊ နူအတိက်တေံလေဝ် တၠသ္ဇိုၚ်ဒၠောံဗ္တောန်တုဲရ။ ဟိုတ်မသ္ဇုၚိဒၠောံဗ္တောန် မဟွံဂွံဒ္ဂေတ်ဗက်ဂလာန်တၠပညာတုဲ ပ္ဍဲကျာဝေရံၚ်မရာတ်ဂှ် ဒးစုတိတုဲရ” ကျာ်တြဲဂး။ (ဇ—၃၈၁။ အစွောံ။) = “ရဟန်း၊ သင်သည် ယခုအခါ­သာလျှင် ဆိုနိုင်ခက်သည်မဟုတ်သေး။ ရှေး­လည်း ဆိုနိုင်ခက်ဖူးပြီ။ ဆိုနိုင်ခက်သည်၏အဖြစ်ကိုမှီ၍ ပညာရှိတို့စကားကို နားမထောင်မူ၍ ဝေရမ္ဘလေဝ­ ပျက်စီး ခြင်းသို့ရောက်ဖူးပြီ။” (ညောင်ကန်)')
,(1469,3,1,'လေပြည်လေညှင်း။',null)
,(1470,3,1,'တောင်လေ။ အနောက်တောင်ရာသီလေ။',null)
,(1471,3,1,'မြောက်လေ။',null)
,(1472,3,1,'ပြင်းထန်သောမြောက်လေအေး။',null)
,(1473,3,4,'(ခွေး)အူသည်။','“ကၠဵုမိၚ်ဗရုဇာဒိသိုၚ်ဂအတ်ဝေၚ်တုဲ ကၠဵုကျူတိုန်ရ။” (ဇ—၁၇၂။ အစွောံ။) = “ခြင်္သေ့တို့၏ဟောက်သံကိုကြား၍ မြေခွေးသည်လည်းအူ၏။”')
,(1474,3,1,'မြည်းသတ္တဝါ။',null)
,(1475,3,1,'ဘုရား။',null)
,(1476,3,1,'ဘုရင်မင်းများနှင့်ဆိုင်သော အခေါ်အဝေါ်အသုံးအနှုန်း။','မိကျာ်ဂန် = မယ်တော်။ || မကျာ်ဂန် = ခမည်းတော်။ || ကောကျာ်ဂန် = နောင်တော်ဘုရား။')
,(1477,3,1,'၁။ သက်တော်ထင်ရှားရှိသော မြတ်စွာဘုရား။',NULL)
,(1477,3,1,'၂။ ရှင်ဘုရင်ကို မှူးမတ်စသူတို့ ခေါ်ဝေါ်သောအသုံးအနှုန်း။', NULL)
,(1478,3,1,'စေတီဘုရား။',null)
,(1479,3,1,'မြတ်စွာဘုရား။','ကျာ်တြဲဂေါတမ = ဂေါတမမြတ်စွာဘုရား။')
,(1480,3,1,'ထက်ဝယ်ဖွဲ့ခွေဆင်းတုတော်။',null)
,(1481,3,1,'ထာဝရဘုရားသခင်။',null)
,(1482,3,1,'ရပ်တော်မူဆင်းတုတော်။',null)
,(1483,3,1,'ဆံတော်ရှင်ဘုရား။',null)
,(1484,3,1,'လျောင်းတော်မူဆင်းတုတော်။ ရွှေသာလျောင်း။',null)
,(1485,3,1,'ခြေတော်ရာစေတီ။',null)
,(1486,3,1,'ခြေတော်ရာဘုရား။',null)
,(1487,3,1,'တိုင်းစွန်နယ်ခြား အထိမ်းအမှတ်စေတီ။',null)
,(1488,3,1,'ကျက်သရေ။ အသရေ။','စရာဲကျာ်သြဳ = ဂုဏ်ကျက်သရေ။ || ပိုန်ကျာ်သြဳ = ဘုန်းကျက်သရေ။ || “ယွံတၠညး၊ ကောန်ဗြဴသေဋ္ဌဳဂှ် ဗြဴကျာ်သြဳဟွံသေၚ်၊ လက်သန်ခါခဏဳရောၚ်အဴ” ဗမၞးတံဂး။ (၅၅ဝ။ ဇ—၅၂၇။ ၉—၂၇။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ထိုသူဌေးသမီးသည် ကျက်သရေရှိသော မိန်းမမဟုတ်၊ သူယုတ်မ၏လက္ခာဖြစ်၏” ဟုပုဏ္ဏားတို့ဆို၏။')
,(1489,3,4,'ဆင်ယင်သည်။ အလှပြင်သည်။',null)
,(1490,3,4,'ဆင်ယင်သည်။ အလှပြင်သည်။','“ညာတ်မာတုဂံါမွဲမကျိုၚ်ကျဝ်ဂှ်တုဲ ထဏေန်အာ စိုတ်တုဲ အဲဍိက်သၟိက်ဂွံရာံ ဂသဝ်ဒၟံၚ်ကွေံရအဴ” ခမဳဂှ်ဂး။ (ဇ—၂၆၂။ အစွောံ။) = “တပည့်တော်သည် အလှပြင်တန်ဆာဆင်ထားသော မိန်းမတစ်ယောက်ကိုမြင်၍ တပ်စွန်းသောစိတ်ရှိသည်ဖြစ်၍ လူဝတ်လဲချင်သဖြင့် ညည်းညူနေခြင်းသည် မှန်ပါ၏” ဟုထိုရဟန်းဆို၏။')
,(1491,3,4,'ပြင်ဆင်ဖီးလိမ်းသည်။ အလှပြင်သည်။ အလှဆင်ယင်သည်။','“ယွံကောန်ဂၠုသ္ဍိုက်ယာဲ၊ နာဲစဴစိုပ်သ္ၚိသၟိၚ်ဨကရာတ်ညးမပြဲတုဲ — ကောန်ဂၠုယာဲဂွံ ကျိုၚ်ကြာဲမွဲဇကု—။” (ဇ—၄၅၅။ အစွောံ။) = “အမေ့ချစ်သားကြီး၊ မြတ်သောမင်းဧကရာဇ် အိမ်နန်းသို့ရောက်၍ — ချစ်သားတစ်ကိုယ်တည်း အလှဆင်ယင်ရတော့အံ့။”')
,(1492,3,1,'(ရုပ်ရည်မလှသော်လည်း) တန်ဆာဆင်ယင်ပြီးလျှင် ကြည့်ကောင်းသည်။ အလှတက်သည်။',null)
,(1493,3,1,'၁။ မိကျောင်း။',NULL)
,(1493,3,1,'၂။ မိကျောင်းပုံ ကြိုးတပ်မွန်တူရိယာ။', NULL)
,(1494,3,1,'၁။ အဖူးအညွန့်။','ကျာဲပ္ကဴ = ပန်းဖူးပန်းညွန့်။')
,(1494,3,1,'၂။ အကိုင်းအခက်။ အခက်အလက်။','“ဓဝ်ကိလေသဂှ် မတုပ်တဴရဴကျာဲဒုန်ဓလရောၚ်။” (၅၅ဝ။ ဇ—၅ဝ၅။ ၈—၅၆။ အစွောံ။) = “ကိလေသာတရားသည် အကိုင်းအခက်စည်ပင်သော ဆူးဝါးပင်နှင့်ပမာတူ၏။”')
,(1495,3,5,'အလွန်။ လွန်ကဲစွာ။ ထူးကဲစွာ။','ခိုဟ်ကျဝ် = အလွန်ကောင်းသည်။')
,(1496,3,4,'လှပသည်။','(နဝိ) လှပသော။')
,(1497,3,4,'လှပတင့်တယ်သည်။',null)
,(1498,3,4,'လှပတင့်တယ်သည်။',null)
,(1499,3,4,'အတော်အတန်လှသည်။ ချောလှသည်။',null)
,(1500,3,4,'လှပသည်။ ချောလှသည်။',null)
,(1501,3,4,'ချောင်းကြည့်သည်၊ ချောင်းမြောင်းသည်။','“ပံက်ကျောဝ်ဒၟံၚ်က” = “ဗျိုင်းသည် ငါးကိုချောင်းနေသည်။”')
,(1502,3,4,'အနီးကပ်၍ အသေအချာကြည့်သည်။',null)
,(1503,3,12,'(န) ကရကဋ်ရာသီ။ (ဆယ့်နှစ်ရာသီတွင် ပုစွန်လုံးရုပ်ဖြင့် မှတ်အပ်သော စတုတ္ထရာသီ။)',null)
,(1504,3,1,'အမှုန့်။','ကြကောတ်ဂပဵု = ထုံးမှုန့်။ || ကြကောတ်ခနှိက်တိ = မြေမှုန့်။ || ကြကောတ်စၠန်၊ ကြကောတ်ကြက်စၠန် = အမွှေးနံ့သာမှုန့်။ စန္ဒကူးနံ့သာမှုန့်။ || သာ်ဝွံကလော်ချပ်ရ “ၝဗောဓိသတ်ဂှ် အဲကဵုထအှ်ညိ” ဂးတုဲ ကနှိက်ကြကောတ်မဇိပ်ဂၠိပ် ဍေံဖရုဲဖျေံရ။ ကနှိက်ကြကောတ်တရုဲစှ်ေတုဲ လောပ်အာမုဟ်ၝဗောဓိသတ်ရ။ (ဇ—၁၅၅။ အစွောံ။) = ထိုဘီလူးသည် “ဘုရားလောင်း၏အဘကို ချေစေအံ့” ဟူ၍ သိမ်မွေ့သောအမှုန့်ကို လွှတ်၏။ အမှုန့်သည်လာ လတ်၍ ဘုရားလောင်းအဘ၏ နှာခေါင်းပေါက်­ဝင်၏။')
,(1504,3,4,'မှုန့်မှုန့်ညက်ညက်ကြေသည်၊ — စေသည်။','“ယွံခမဳ၊ ပ္ဍဲကာလမတုဲတေံ ဟိုတ်တၠအဲမသ္ဇိုၚ်ကဵုဒလောအ်ဗ္တောန်တုဲ ဟွံကေတ်ဂလာန် တၠပညာတုဲ ပ္ဍဲစိၚ်ဇၟူသီုကၠေၚ်ဂှ် ဖျုန်ဇကုမဒးကြကောတ်တဴတုဲရသွံ” ကျာ်တြဲဂး။ (ဇ—၁၆၁။ အစွောံ။) = “ရဟန်း၊ သင်သည်ကား ရှေး­လည်း ဆိုဆုံးမခက်သည်၏အဖြစ်ကြောင့် ပညာရှိတို့၏စကားကို နားမထောင်သောကြောင့် အမုန်ယစ်သောဆင်၏ခြေ­ အသားတို့သည် မှုန့်မှုန့်ညက် ညက်ကြေဖူးကုန်ပြီ။” || “တြုံ (ဒၟိက်) ဝွံ နကဵုရိ မၞးတံတက်ကြကောတ်ကၠေံဇုတ်ဍေံညိ။”(ဇ—၁၉၃။ အစွောံ။) = “ဤသူယုတ်မာအား ကျည်ပွေ့ဖြင့် အရိုးတို့ကို သိသိညက်ညက်ကြေအောင် သင်တို့ရိုက်ကြကုန်လော့။”')
,(1505,3,1,'အမွှေးနံ့သာမှုန့်။ ကသယ်မှုန့်။','“သၟိၚ်မဟာကောသလဂှ် ကောန်ဗြဴမွဲကဵု ကုသၟိၚ်ဗိမ္ဗိသာတုဲ တၞဟ်နပၚုဟ်ကြကောတ်မြမောဝ်ဂှ် ကွာန်ကသိမွဲဂှ် ကဵုကုကောန်ဗြဴဂှ်ရ။” (ဇ— ၄၉၂။ အစွောံ။) = “မဟာကောသလမင်းကြီးသည် ဗိမ္ဗိသာရမင်းအား သမီးတော်ကိုပေးသည်ရှိသော် သမီးတော်ရေချိုးကသယ်မှုန့်ဘိုးအလို့ငှာ ကာသိရွာကို ပေးတော်မူ၏။”')
,(1506,3,4,'သင့်လျော်သည်။ လျောက်ပတ်သည်။ (ပါဠိ—ယုတ္တ/ကလ္လ)', null)
,(1507,3,11,'(န) ကျမ်းဂန်လာ အလွန်အသံသာသော ကရဝိက်ငှက်။',null)
,(1508,3,1,'၁။ စပါးလှေ့စင်။',NULL)
,(1508,3,1,'၂။ တံဆိပ်။ ရင်ထိုးတံဆိပ်။ ဒိုင်းဆုတံဆိပ်။',NULL)
,(1509,3,1,'ချိန်ခွၚ်။ ကတ္တား။',null)
,(1510,3,16,'(ဂဏန်း) သုံးခုသင်္ချာ။',null)
,(1511,3,1,'ဆေးဖက်ဝင်အသီးသုံးပါး။ (၄င်းတို့မှာ၊ ဇာဒိပ္ဖိုလ်သီး။ ကြစုသီး။ ဇီးဖြူသီး။)',null)
,(1512,3,1,'ယုတ္တိရှိခြင်း။ လျော်ကန်ခြင်း။ လျောက်ပတ်ခြင်း။ (?)',null)
,(1513,3,16,'(န) ၁။ ပစ္စည်းကြိယာ။ တန်ဆာပလာ။', NULL)
,(1513,3,16,'၂။ (ပါ) (သဒ္ဒါ) ပြုခြင်း၊ ဖြစ်ခြင်း၊ ရှိခြင်းကို ပြသောပုဒ်။ ကြိယာ။',null)
,(1514,3,1,'(သဒ္ဒါ) ဖြစ်စေခြင်း၊ ပြုစေခြင်း ရှိစေခြင်းကို ပြသောကြိယာ။ ကာရိုက်ကြိ ယာ။','(ဥပမာ — မွန်ဘာသာ­ ‘စ’၊ ‘မဴ’၊ ‘တိုန်’၊ ‘ဍောၚ်’ စသောဝေါဟာရတို့သည် သုဒ္ဓကြိ ယာများဖြစ်၍ ‘ဗစ’၊ ‘ဗမဴ’၊ ‘ပတိုန်’၊ ‘ဖဍောၚ်’ စသောဝေါဟာရတို့သည် ကာရိုက်ကြိယာများ ဖြစ်ကြသည်။)')
,(1514,3,1,'(သဒ္ဒါ) ဖြစ်စေခြင်း၊ ပြုစေခြင်း ရှိစေခြင်းကို ပြသောကြိယာ။ ကာရိုက်ကြိယာ။','‘ကြိယာသုဒ္ဓ’ လည်းရှု။')
,(1515,3,1,'အလှဆင်စရာပစ္စည်း။ အဝတ်တန်ဆာ။ လှဝတ်တန်ဆာ။ လက်ဝတ်လက်စား။',null)
,(1516,3,1,'အသုံးအဆောင်ပစ္စည်း။',null)
,(1517,3,10,'(န) (သဒ္ဒါ) ကြိယာကို အထူးပြုသောပုဒ်။ ကြိယာဝိသေသန။',null)
,(1518,3,10,'(န) (သဒ္ဒါ) ဖြစ်ခြင်း၊ ပြုခြင်း ရှိခြင်းကို ပြသောကြိယာ။ သုဒ္ဓကြိယာ။','(ဥပမာ — မွန်ဝေါဟာရ ‘စ’ သည် သုဒ္ဓကြိယာဖြစ်၍ ‘ဗစ’ သည် ကာရိုက်ကြိယာဖြစ်သည်။) ကြိယာကာရိုတ်’ လည်းရှု။')
,(1519,3,11,'(န) အမှုအလုပ်။ အပြုအမူ။ ဆောင်ရွက်မှု။ ကျင့်စဉ်။',null)
,(1520,3,11,'(န) အလယ်အလတ်လမ်းစဉ်။ အလယ်အလတ်ကျင့်စဉ်။',null)
,(1521,3,11,'(န) လက်ဦးဆောင်ရွက်မှု။ ပထမအဆင့်ကျင့်စဉ်။',null)
,(1522,3,11,'(န) နောက်ဆုံးဆောင်ရွက်မှု။ အဆုံးသတ်ကျင့်စဉ်။',null)
,(1523,3,4,'၁။ ပါးသည်။','“တၞးလိက်ဏအ်ဂှ် ကြဳဒၟံၚ်ကွေံရ။” = “ဤစာရွက်သည် တကယ် ပါးလွှာသည်။”')
,(1523,3,4,'၂။ ပါးနပ်သည်။ အကင်းပါးသည်။ သင်ကြားတတ်မြောက်လွယ်သည်။','“သၟတ် ဗြဴဝုတ်ဂှ် ကြဳကွေံရ။ ဟွံဒးဟီုဂၠိုၚ် ကၠိုဟ်ခၠၚ်လောဲရ။” = “ထိုမိန်းမပျိုသည် တကယ်အကင်းပါးသည်။ များများပြောစရာမလိုဘဲ သဘောပေါက်လွယ်သည်။”')
,(1523,3,4,'၃။ နည်းပါးသည်။ လျော့နည်းသည်။ လျော့ပါးသည်။','“ပ္ဍဲပေဲါသဘၚ် တ္ၚဲလက်ကြဴအိုတ်ဂှ် မၞိဟ်ကြဳအာရ။” = “ပွဲသဘၚ် နောက်ဆုံးနေ့­ လူသူပရိသတ် နည်းပါးသွားသည်။” || “(ဂလာန်တၠပညာဂှ်) သၟိၚ်ဗစာရဏာတုဲ ဓဝ်စံၚ်တူပ္ဍဲဂၠံဟဒယဖျုန်ဂြိုဟ်သၟိၚ် ပ္ဍဲဂၞကျာ်ဂှ် တြဳအာညိရ။” (၅၅ဝ။ ဇ—၄ဝ၁။ ဒု—၄၆၅။ အစွောံ။) = “ပညာရှိစကားကို မင်းသည်ဆင်ခြင်၍ မိဖုရားကြောင့် မင်း၏နှလုံးသား­ဖြစ်သော ပူဆွေးသောကသည် အနည်းငယ် လျော့ပါး (သက်သာ) သွား၏။”')
,(1523,3,3,'၁။ ပါးသော။ ပါးလွှာသော။', NULL)
,(1523,3,3,'၂။ ပါးနပ်သော။ အကင်းပါးသော။', NULL)
,(1523,3,3,'၃။ လျော့နည်းသော။ လျော့ပါးသော။', NULL)
,(1524,3,4,'အလွန်ပါးလွှာသည်။',null)
,(1525,3,1,'တန်ခိုး။ အစွမ်း။ အာနုဘော်။ အရှိန်အဝါ။','“ကျာ်တြဲမ္ဂးဂှ် ဇၞော်ကဵုကြဳဇှ်ဣဓိလောန်ရ။ ညးမဂစိုတ်ကျာ်တြဲမာန်ဂှ် ဟွံမွဲရ။” = “မြတ်စွာဘုရားမည်သည်ကား ဘုန်းတန်ခိုးအလွန်ကြီး၏။ မြတ်စွာဘုရားအား သတ်နိုင်သောသူမည်သည် မရှိ။” || “ဒေဝတဴတၠဣဒ္ဓိ မနွံကဵုကြဳဇှ် ပ္ဍဲလိုက်ဟွံ မွဲရောၚ်သ္ဂးဟာ။”(ဇ—၁၉၄။ အစွောံ။) = “အစွမ်းတန်ခိုးရှိသော တန်ခိုးရှင်နတ်တို့သည် လောက­ မရှိလေသလော။” || “ကြဳဇှ်ဂျိနာ် မအာပ်အာကြဳဇှ်လၟတံဂှ်။” (ဇ—၅၂၄။ အစွောံ။) = “နဂါးဆိပ်၏အစွမ်းသည် မုဆိုးတို့၏အစွမ်းကို ရှုံးသွားရ၏။” || “သၟာဂလုံဂှ် နကြဳဇှ်သိပ်ဂၠိပ်ဂကောံ တၠပညာတုဲ — ကလိဂွံတသိုက် ပ္ဍဲဂတမတ်ဂှ်ဟေၚ်။” (ဇ—၁၉ဝ။ အစွောံ။) = “ထိုဆတ္တာသည်သည် ပညာရှိနှင့်တကွ ပေါင်းဖော်မှီဝဲရခြင်း၏ အစွမ်းအားကြောင့် ချမ်းသာကို မျက်မှောက်ဒိဋ္ဌ ရရှိ၏။” || “ကြဳဇှ်ပိုန်ကုသဵုတၠအဲ ထးဝွံဒှ်အာထဝ်ရောၚ်သဒှ်ရ” ဗဴဂှ်ဂးကဵုဗောဓိသတ် ညးဗၞိက်လီု ရ။ (ဇ—၃။ အစွောံ။) = “ဤခွက်သည်ကား သင်၏ကုသိုလ်ဘုန်းအာနုဘော်ကြောင့် ရွှေခွက်ဖြစ်သွားသည်ဖြစ်လတ္တံ့” ဟု အဘွားက ဘုရားလောင်းရွဲကုန်သည်အားပြော၏။ || “(သဳဝလိကုမာဂှ် ဂွံဒှ်ပယၚ်တုဲ) အာစိုပ်ဒဒှ်အရှန်ရ။ ကြဳဇှ်ကံကုသဵု မခၞံဗဒှ်လဝ်တုဲ ဨတဒဂ္ဂမပြဲ ကလိဂွံရ။” (ဇ—၁ဝဝ။ အစွောံ။) = “သီဝလိသတို့သားသည် ရဟန်းဖြစ်ပြီးနောက် ရဟန္တာအဖြစ်သို့ရောက်၏။ ပြုထားအပ်သောကုသိုလ်ကံ၏ အစွမ်းအာနုဘော်ကြောင့် မြတ်သောဧတဒဂ်အရာကို ရရှိ၏။”')
,(1526,3,4,'ပိန်ပိန်ပါးပါးဖြစ်သည်။',null)
,(1527,3,1,'ပါးလွှာသည်။ အလွန်ပါးသည်။','“သၞာလးဂှ် ကြဳသြိၚ်လောန် ညာတ်ဂၠးကၞဳသၟဝ်ဍေံဂှ်ရ။” = “ခင်းထားသောအခင်းသည် အလွန်ပါးလွှာ၏၊ ၄င်းအောက်ရှိကြမ်းပြင်ကို မြင်ရ၏။”')
,(1528,3,4,'သေးသွယ်သည်။ ပိန်ပိန်ပါးပါးဖြစ်သည်။','“သၟတ်တြုံဂှ် ကြဳသွတ်တဴ ရံၚ်စခိုဟ်ကွေံရ။” = “ထိုသူငယ်သည် ပိန်ပိန်ပါးပါးနှင့် အလွန်ကြည့်ကောင်းသည်။”')
,(1529,3,4,'နည်းပါးသည်။ လျော့ပါးသည်။','“ယဲဝေဒနာအပါဂှ် ကြဳအောန်စှ်ေဒၟံၚ်ရ။”= “အဖေ့ရောဂါဝေဒနာသည် လျော့ပါးလာနေပြီ။”')
,(1530,3,4,'ကြုံးဝါးသည်။ မိုက်ရူးရဲစိတ်ရှိသည်။',null)
,(1531,3,1,'ပိန်းပင်။','ခၟာဲကြဴ = ပိန်းဥ။ || ကြဴကုန် = တောင်ပေါ်ပိန်းဥတစ်မျိုး။')
,(1532,3,5,'၁။ နောက်မှာ။ နောက်မှ။ နောက်­။','“ဍေံဂ္ဇအ်ဒၟံၚ်ကြဴအဲရ။” = “ငါ့နောက်မှာ သူထိုင်နေသည်။” || “ကကၟက်အာကြဴ ကဗြဴအာဂတ။” (ဇ—၂၁၆။ အစွောံ။) = “ငါးဖိုသည် နောက်မှသွား၍ ငါးမသည် ရှေ့မှသွား၏။”')
,(1532,3,5,'၂။ နောက်နောင်။ နောင်အခါ။','“ပွသာ်ဝွံ လ္ပပကြဴ။” = “ဤအမှုမျိုး နောင်မပြုလုပ်ပါနှင့်။” ကြဴမိမၜါ = မိဘနှစ်ပါးနောက်ကွယ်။ ‘ကရဴ’ လည်းရှု။')
,(1533,3,4,'ဆေးကြောသည်။','ကြဴက္ဍိုပ် = ခေါင်းလျှော်သည်။ || ကြဴဇိုၚ်တဲ = ခြေလက်ဆေး ကြောသည်။ || ကြဴပါၚ် = ပါးစပ်ဆေးကြောသည်။ ပလုတ်ကျင်းသည်။')
,(1534,3,4,'ဆေးကြောသည်။','“ကြဴကြာတ်ပ္ၚာန် ကဵုသ္အးဇၚးညိၝောံ။” (ဇ—၃ဝ၂။ အစွောံ။) = “ရှင်မ၊ ပန်းကန်တို့ကို စင်ကြယ်အောင် ဆေးကြောပါ။” || ကြဴကြာတ်ဇိုၚ်တဲ = ခြေလက်တို့ကို ဆေးကြောသည်။ || “(ဇိုၚ်စိၚ်ဒှ်သရဂှ် ဓဇဲတံဂှ်) ၜိုဟ်ဍာ်ဒကောဝ်ဆု ကြဴကြာတ်စုတ်ဂဥုဲလွဳပရာ ဇိုၚ်စိၚ်ဂှ်စိန် စိၚ်ဗၠးအာရ။” (ဇ—၁၅၆။ အစွောံ။) = “လက်သမားတို့သည် အနာဖြစ်သော ဆင်၏ခြေကို သစ်ခေါက်ရည်ပြုတ်၍ ဆေးကြောဆေးထည့်ကုသပေးရာ ဆင်ခြေအနာကျက်၍ ဆင်သည် အနာပျောက်ကင်းသွား၏။”')
,(1535,3,4,'ကျောခိုင်းသည်။ စွန့်ပယ်သည်။','“ယွံနာဲပိုဲတံ၊ ဒေဝဒတ်ကြဴကၠေံကဵုအ္စာတုဲ ပသတြု ကဵုအ္စာပၠန်တုဲ လေၚ်ဇၞော်ဟေၚ်အာစိုပ်ရ” ခမဳဂမၠိုၚ်ဟီု။ (ဇ—၂၄၃။ အစွောံ။) = “ငါ့သျှင်တို့၊ ဒေဝဒတ်သည် ဆရာကိုစွန့်၍ ဆရာဖြစ်သော ဘုရား၏ရန်သူဖြစ်၍ ကြီးစွာသောပျက်စီးခြင်းသို့ ရောက်၏။” (ညောင်ကန်) ‘ကရဴကၠေံ’ နှင့်အတူတူ။')
,(1536,3,4,'မျက်နှာချင်းမဆိုင် ကျောလှည့်ထားသည်။ ကျောပေးသည်။ ကျောခိုင်းသည်။','“ညးဂ္ဇအ်ကြဴလဝ်စးကဵုအဲရ။” = “ငါ့ကိုကျောပေး၍ သူထိုင်နေသည်။”')
,(1537,3,5,'နောက်နောင်။ နောင်အခါ။','“ဂလာန်ဟွံခိုဟ် မ္ၚိုဟ်ခဏံၚ်ကြံၚ်သ္ကာတ်ဂှ် ယာံဒးဟီု တုဲဂှ် ကြဴတဲ ဒးစံၚ်တူတဴပၠန်ရ။” (ဇ—၈၈။ အစွောံ။) = “မာကျောကြမ်းတမ်းသော မစကာင်း သောစကားကို အကယ်၍ပြောဆိုမိအံ့၊ နောင်အခါစိုးရိမ်ပူပန်ရပြန်၏။” || “(ဗောဓိသတ်) အာကတ်ဍုၚ်တက္ကသဵု လေပ်ဗိုတ်ပိ၊ ကြဴတဲ မိကဵုမဟွံမွဲတုဲ တိတ်ပခမဳဣသိ ပ္ဍဲဟေမဝန်။” (ဇ—၁၄၉။ အစွောံ။) = “ဘုရားလောင်းသည် တက္ကသိုလ်ပြည်သို့ အတတ်သၚ်သွား၍ ဗေဒၚ်သုံးပုံတို့ကို တတ်မြောက်၏။ နောင်မိဘများမရှိသောအခါ ဟိမဝန္တာတော­ ထွက်၍ရသေ့ရဟန်းပြု၏။”')
,(1538,3,16,'ထို့နောက်။','“ပ္ဍဲအာဒိကိုပ်ကၠာဂှ် ဗၞတ်ယာဂုမွဲဗြံက်ကီု နအလေဝ်ဇကုဍေံဟေၚ် စှ်ေ လံၚ်စုတ်ကၠာရ။ ကြဴပၠန် ပုၚ်သီုရှ် — ဍေံစှ်ေလံၚ်စုတ်ပၠန်ရ။” (ဇ—၁၄။ အစွောံ။) = “အစကန ဦး­ တစ်ခွက်သောယာဂုကိုသာလျှင် သူမကိုယ်တိုင် ဆင်း၍လောင်းလှူ၏။ ထိုနောက်­ အရသာ ရှိသောဆွမ်းကို လောင်းလှူပြန်၏။”')
,(1539,3,1,'ဂမုန်းပိန်း။',null)
,(1540,3,3,'နောက်ကွယ်ဖြစ်သော။ မျက်ကွယ်ရာဖြစ်သော။',null)
,(1541,3,5,'ထိုနောက်­။ (အချိန်ကာလ)','“ကြဴဝွံ နွံကာလမွဲတ္ၚဲ ရးပုန်အာ။ — သၟိၚ်ဇက်အာလဒံရး။” (ဇ—၁၂ဝ။ အစွောံ။) = “ထိုနောက်­ တစ်နေ့သ­တိုင်းစွန်­ သူပုန်ထ၏။ မင်းသည် နှိမ်နင်းအံ့သောငှာ စစ်ချီသွား၏။” || “(ကၠဵုစၞာဲဂှ်) သ္ပဒဒှ်ေဒယှ်ကဵုသတ် မပ္တေဟ်ဇကုတုဲ ကြဴဝွံ ရပ်ဂစိုတ်စကၠေံရ။” (ဇ—၁၂၈။ အစွောံ။) = “ထိုမြေခွေးစဉ်းလဲသည် မိမိကိုယုံသောသတ္တဝါနှင့် ရင်းနှီးအကျွမ်းဝင်အောင်ပြုပြီး ထိုနောက်­ ဖမ်း၍သတ်စားပစ်၏။”')
,(1542,3,3,'နောက်ဆုံး။ နောက်ဆုံးဖြစ်သော။','“ပၞောဝ်ကွဳမသုန်ကၠံဂှ် ကွဳကြဴအိုတ်ဂှ် ပ္ဍိုက်လဝ်ဍာ်ရ။” (ဇ—၁။ အစွောံ။) = “ငါးရာကုန်သောလှည်းတို့အနက် နောက်ဆုံးလှည်း­ ရေကိုတင်ဆောင်ထား၏။”')
,(1543,3,4,'ဆိုးသွမ်းသည်။ ဆိုးမိုက်သည်။ အုပ်ချုပ်ရန်ခက်သည်။',null)
,(1544,3,4,'ဆိုးသွမ်းသည်။ နိုင်ထက်ကလူပြုတတ်သည်။','“(သၟိၚ်) ညာတ်ပွခဍာ်ဂှ် ကြံကြဗိုန်ဒၟံၚ်ဂှ်တုဲ—။” (ဇ—၂၉၂။ အစွွောံ။) = “မင်းသည် ကျီး၏ဆိုးသွမ်းခိုင်မာသော အမူအရာကိုမြင်၍—။”')
,(1545,3,4,'ခက်ထန်သည်။ ကြမ်းကြုတ်သည်။ ရုန့်ရင်းသည်။',null)
,(1546,3,1,'အနှစ်။ အနှစ်သာရ။','ဂလာန်မၞုံကဵုကြက် = အနှစ်ရှိသောစကား။ || ကြက်နာဍူ = ပိတောက်အနှစ်။ || ဆုကြက် = သစ်မာ။ အကောင်းစားသစ်။')
,(1547,3,9,'အနာဂါတ်ကာလကိုပြသော ကြိယာရှေ့ သို့မဟုတ် ကတ္တားရှေ့တွင် ထားရသော စကားလုံး။ မည်။ လိမ့်မည်။ အံ့။ လတ္တံ့။','“ဇၟာပ်မၞိဟ်ကြက်ဒးချိုတ်ဖအိုတ်ရ။” = “လူတိုင်း သေရမည်ချည်းဖြစ်သည်။” || “ကြက်အဲမၚ်သဳဥပုဟ်ညိ။”= “ငါသည် ဥပုသ်သီလကို စောင့်စည်းအံ့။” || “ကွးမၞးဂှ် ဍေံဟွံကြက်ဇၞးရ။ မၞးမဒှ်အ္စာဍေံရောၚ် ကြက်သ္ဂောံဇၞးရ” ဣန်ဂးကဵုဗောဓိသတ် ရ။ (ဇ—၂၄၃။ အစွောံ။) = “သင့်တပည့်သည် မနိုင်လတ္တံ့။ ဆရာဖြစ်သောသင်သည်လျှင် အနိုင်ရလတ္တံ့။”')
,(1548,3,4,'အစပြုသည်။ ဆင်းသက်လာသည်။ (ယခင်မှယခုအထိ) စဉ်ဆက်မပြတ်ဖြစ်လာသည်။','“ပိုဲမန်ဗဝ်သၟုတ်က္ၜၚ်ဂှ် ကြက်ကၠုၚ်နူလဵုရော။” = “တို့မွန်များ သၚ်္ဘောဆွမ်းတော်တင် ခြင်းသည် အဘယ်ကအစပြုခဲ့ပါသနည်း။” || “ယွံတဳလမၞုံပိုန်၊ ထအှ်တုဲ ‘ဇိဝတု၊ ကဵုဂျိုၚ်လမျီု ညိ’ မ္ဂးဂှ် ဂလာန်ဂှ် မူနူမဂွံဟီုကြက်ကၠုၚ်ဂှ်ရော။” (ဇ—၁၅၅။ အစွောံ။) = “အရှင်ဘုရား၊ နှာ ချေ၍ ‘အသက်ရှည်ပါစေသော’ ဟုဆိုသောစကားသည် ဘယ်ကအစပြု၍ ဆိုစမှတ်ပြုခဲ့ပါသနည်း။” || “မကဵုမ္ၚဵုစိၚ်သၟိၚ်မ္ဂးဝွံ ဒဵုကဵုထပှ်ဒတောဝ် တၞောဝ်ပိုဲမကြက်ကၠုၚ်ရောၚ်။” (ဇ—၁၆၃။ အစွောံ။) = “မင်း၏ဆင်မၚ်္ဂလာပြုခြင်းမည်သည်ကား အမျိုးခုနစ်ဆက်တိုင် ငါတို့၏အနွယ်သည် မပြတ်ဆက်လာခဲ့၏။”')
,(1549,3,1,'ပြက္ခဒိန်။','“သာ်ဝွံလက်သန်၊ ဗေဒၚ်ပန်ရ။ ကြက္ကဒိန်က္ဍၚ်၊ သၚ်ဝတ်ဆဝ်ဂျ။”(လိက် နယသမုဒ္ဒြဳ။ အစွောံ။)')
,(1550,3,1,'အမျိုးစစ်အမျိုးမှန်။',null)
,(1551,3,1,'နောင်လာမည့်ကာလ။ အနာဂတ်ကာလ။','(ကြိ) ရှေ့တွင်ဖြစ်လာလိမ့်မည်။')
,(1552,3,1,'စကား၏အနှစ်သာရ။ အနှစ်သာရရှိသောစကား။',null)
,(1553,3,3,'မူလအစဖြစ်သော။',null)
,(1554,3,1,'ယင်းတိုက်ပင်။',null)
,(1555,3,1,'နံ့သာနှစ်။ စန္ဒကူးနံ့သာ။',null)
,(1556,3,1,'သစ်ကောင်းသစ်မာ။ အနှစ်ဖြစ်သောသစ်။',null)
,(1557,3,1,'ဥစ္စာအနှစ်။ စည်းစိမ်ဥစ္စာ။','“ဗောဓိသတ်ဒှ်ပ္ဍဲဂကူဗမၞး ဂၠိုၚ်ကဵုကြက်ဒြပ်—။” (ဇ— ၁၂၃။ အစွောံ။) = “ဘုရားလောင်းသည် ပုဏ္ဏားမျိုး­ဖြစ်၍ များစွာသောစည်းစိမ်ဥစ္စာရှိ၏။”')
,(1558,3,1,'ကရမက်။','‘ကလာမက်’ နှင့်အတူတူ။')
,(1559,3,1,'ရှားပင်။ (ပါဠိ—ခဒိရ)','လ္ၚကြက်လကံ = ရှားမီးခဲ။')
,(1560,3,4,'အနှစ်ဖြစ်သည်။ အချုပ်ဖြစ်သည်။ အစစ်အမှန်ဖြစ်သည်။ အမှန်တကယ်ဖြစ်သည်။',null)
,(1561,3,1,'၁။ မှို့ပင်။ လဲပင်။','၂။ လက်ပံပင်။ (ပါဠိ—သိမ္ဗလိရုက္ခ)')
,(1562,3,1,'ဟင်းခတ်အမွှောအကြိုၚ်သုံးမျိုး။ ၄င်းတို့မှာ ၁။ (ကၞိ) ပိတ်ချင်း။ ၂။ (မြေက်ခ မှိဟ်) ၚရုပ်ကောင်း။ ၃။ (လ္ဂဝ်) ဂျင်း။)',null)
,(1563,3,1,'ဟင်းခတ်အမွှောအကြိုၚ် မျိုးကြီးသုံးမျိုး။ ၄င်းတို့မှာ ၁။ (ခ္ဍၚ်ရာ) သစ်ကြံ ပိုး။ ၂။ (မအဳ) ဖာလာစေ့။ ၃။ (အညာ) ဇာဒိပ္ဖိုလ်သီး။)',null)
,(1564,3,4,'တည်တံ့သည်။ တည်မြဲသည်။ အရှည်တည်သည်။','ကြိက်ကြက်အာဗွဲဂတ = နောင်လာမည့် ရှည်ကြာသောကာလတိုင် တည်တံ့ခိုင်မြဲသည်။')
,(1565,3,1,'၁။ တရုတ်လူမျိုး။','ဍုၚ်ကြုက် = တရုတ်ပြည်။')
,(1565,3,1,'၂။ သရက်သီး။', NULL)
,(1566,3,1,'ဆင်နင်းသရက်။',null)
,(1567,3,1,'တစုမေ့သရက်။',null)
,(1568,3,1,'တောစာသရက်။',null)
,(1569,3,1,'ရွှေရၚ်အေးသရက်။',null)
,(1570,3,1,'မနွယ်နွယ်သရက်။',null)
,(1571,3,1,'သီဟိုဠ်သရက်။',null)
,(1572,3,1,'မန္တလေးရၚ်ကွဲသရက်။',null)
,(1573,3,1,'မချစ်စုသရက်။',null)
,(1574,3,1,'စားသောသူတို့အား အအိုမှအပျိုသို့ ပြောင်းလဲပေးနိုင်စွမ်းရှိသည်ဆိုသော ဒဏ္ဍာရီ လာသရက်သီး။',null)
,(1575,3,1,'အဗ္ဗန္တရသရက်သီး။ (အနံ့အရသာနှင့် အထူးပြည့်စုံသော ဝေဿဝဏ်နတ်မင်း၏ အသုံးအဆောင်ဖြစ်သော ကျမ်းဂန်လာသရက်။ ၄င်းသရက်ပင်ကို ကုမ္ဘန်တစ်ထောင် အစောင့်အ ကြပ်ထားရှိသည်ဆို၏။)','“ယွံတၠညး၊ ကြုက်အဘန်တဵုမ္ဂးဂှ် ဒှ်ပြဘိုက်ဒေဝတဴတံ ပ္ဍဲဂြိုပ်ဟေမ ဝန်တေံရောၚ်အဴ။” (ဇ—၂၈၁။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ နတ်တို့၏အသုံးအဆောင်ဖြစ် သော အဗ္ဘန္တရမည်သောသရက်သည် ဟိမဝန္တာဝယ် ရွှေဂူ၏အတွင်း­ရှိ၏။” (ညောင်ကန်)')
,(1576,3,1,'ချိပ်။ (ပါဠိ—လာခါ/ဇတု)','စၟကြေက် = ချိပ်ပိုးကောင်။ ကြေက်ဗ္ဒဝ် = ဇီးပင်မှရ သောချိပ်။')
,(1576,3,1,'ချိပ်။ (ပါဠိ—လာခါ','“(သွက်ဗမၞးမုဟ်ပိုတ်ဂှ်) နကဵုကြေက်ဂှ် အ္စာသဝ်မာန်ပတုပ်မုဟ်ဂှ်တုဲ တုပ်ညံၚ်မုဟ်တ ရေံဂှ်ကီု။” (ဇ—၁၂၆။ အစွောံ။) = “(ထိုနှာခေါင်းပြတ်သောပုဏ္ဏားအတွက် ဆေးသမားသည်) ချိပ်တို့ဖြင့် နှာခေါင်းတုကိုပြု၍—။” (ညောင်ကန်)')
,(1577,3,4,'လိုက်ဖက်သည်။ ထိုက်တန်သည်။ သင့်လျော်သည်။','“ပလောအ်ဏအ် ကြိုက်ကဵုအဲရ။”= “ဤအင်းကျီ ကျွန်တော်နှင့်လိုက်ဖက်သည်။” || “ပ္ဍဲမညန်ကဵုဋ္ဌာန်ခမဳအရဳတအ်ဂှ် ဟွံကြိုက် ကဵုတဳတံမံၚ်ရ။” = “အရိယာရဟန်းတို့နေသော နေရာအနီး­ တိတ္ထိတို့နေရန် မသင့်လျော်ပါ။”')
,(1578,3,4,'“မျက်နှာနှင့်လိုက်သည်” ဟုအဓိပ္ပါယ်ရှိသော ဝေါဟာရဖြစ်သည်။ လူတစ်ဦး တစ်ယောက်က မိမိပြောစကားကို မနာယူ၍ဖြစ်စေ၊ မပြုသင့်သည်ကို ပြု၍ဖြစ်စေ၊ ထိုသူဒုက္ခ ရောက် အခက်ကြုံသောအခါ “ကောင်းပါ၏၊ ထိပါစေ” ဟူသောအနက်ဖြင့် အရွဲ့တိုက်ပြောဆို သောစကား။',null)
,(1579,3,4,'သဘောတူသည်။ နှစ်သက်သည်။ စိတ်ကြိုက်ဖြစ်သည်။','“ကြဳဇှ်ပိုန်ကုသဵုတၠအဲ ထးဝွံဒှ်အာထဝ်ရောၚ်သဒှ်ရ၊ ပိုဲမကြိုက်စိုတ်ကဵုတၠအဲရ၊ လီုညိညဆမကြိုက်စိုတ် ကဵုကုပိုဲရ၊ ယိုက်ကေတ်ထးဝွံတုဲ အာဂွံရ” ဗဴကဵုစဴညးၜါ ဂးကဵုဗောဓိသတ်ညးဗၞိက်လီု။ (ဇ—၃။ အစွောံ။) = “သင်၏ကုသိုလ်ဘုန်းအာနုဘော်ကြောင့် ဤခွက်သည် ရွှေခွက်ဖြစ်သွားသည်ဖြစ်လတ္တံ့၊ သင့်အားပေးရန် ငါတို့သဘောတူပါ၏။ သင်နှစ်သက်သလောက်သော အနည်းငယ်သောရွဲတို့ကို ငါတို့အားပေး၍ ဤခွက်ကိုယူ၍ သင်သွားနိုင်ပြီ။” || “ညးဂှ်မွဲ မၞးတံညးဂမၠိုၚ် ကြိုက်ကဵုစိုတ်ပ သၟိၚ်ရော။” (ဇ—၂၈၄။ အစွောံ။) = “အဘယ်သူတစ်ဦးကို မင်းပြုစေရန် သင်တို့နှစ်သက်သ ဘောတူပါသနည်း။”')
,(1580,3,4,'ထိုက်တန်သည်။ သင့်လျော်သည်။','“တရတၠပညာသာ်ဝွံ ကြိုက်တန်ကဵုနာဲပိုဲသန် သွံ” ညးဂမၠိုၚ်ဂးကဵုသၟိၚ်။ (ဇ—၅။ အစွောံ။) = “ဤသို့ပညာရှိသောရာပြတ်သည် ငါတို့သခင် မင်းကြီးနှင့် ထိုက်တန်ပေစွ။”')
,(1581,3,4,'လိုက်ဖက်ညီသည်။','“သၟတ်ဗြဴလေဝ် တၠကၞောတ်ရုပ်ရ၊ သၟတ်တြုံလေဝ် တၠ ကၞောတ်ကွတ်ရ၊ သၟတ်တြုံကဵုသၟတ်ဗြဴညးၜါဝွံ ကြိုက်လ္ၚေၚ်လောန်သန်ရ။” = “သူငယ်မလည်း လှထွတ်ခေါင်ဖြစ်၏၊ သူငယ်လည်း အထွတ်အထိပ်ပညာသည်ဖြစ်၏၊ သူငယ်နှင့်သူငယ်မနှစ်ဦးတို့သည် အလွန်လိုက်ဖက်ညီလှသည်။” || “အဲကေုာံသဟာဲအဲ သဟာဲအဲကေုာံအဲလေဝ် (သေဋ္ဌဳမွဲစွံ) ကြိုက်လ္ၚေၚ်သန်၊ သ္ဇက်ရုဲစှ်ရၚ်သ္ကံဟွံမွဲရ။” (ဇ—၁၂၅။ အစွောံ။) = “ကျွန်ုပ်နှင့်အဆွေ၊ အဆွေ နှင့်ကျွန်ုပ်သည်လည်း (သူဌေးအချင်းချင်းဖြစ်၍) အလွန်လိုက်ဖက်ညီ၏၊ ရွေးချယ်စရာမရှိပြီ။”')
,(1582,3,5,'တိုက်တိုက်ဆိုင်ဆိုင်။ တိုက်ဆိုင်စွာ။','“ကမၠတ်ဂှ် ကၠတ်ဒရေပ်ဏာဂၠဴဂှ်ရ၊ ကြိုက်သၟိက်ကဵုဒှ် ပ္ဍဲဒေါဝ်တရဴ အာဂဗဆဵုစုတ်ဒးကဵုတၠဂၠဴရ။” = “သူခိုးသည် နွားကိုခိုး၍ အပြေး ယူသွားသည်၊ တိုက်တိုက်ဆိုင်ဆိုင် လမ်းခုလပ်တွင် နွားပိုၚ်ရှင်နှင့် ပက်ပင်းတိုးသည်။” || “ဟာဲမ၊ မၞိဟ်သလိုက်ပိုဲပ္ဍဲမ္ၚး ဍေံလှိၚ်အိုတ်တုဲရ။ ဒြပ်မတိုပ်လဝ် သၟဝ်တၞံဆုမဖှ်သာ်ဂှ် မဟွံမွဲပၠန်ဟာ” (သေထဳဗြဴသၟာန်။) “အဲမွဲပယတ်ဗိုန်ဒၟံၚ်” သေထဳတြုံဂး။ ကြိုက်သၟိက်ကဵုဒှ် ကမၠတ်တံကၠုၚ်ကၠတ်စ ဍေံမိၚ်ဂလာန်သေထဳတုဲ — (ဒြပ်ဂှ်)ကမၠတ်ဂွံဖျဴဏာရ။ (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အိုလင်တော်မောင်၊ အတွင်းအပရှိငါတို့လူများ အားလုံးအိပ်ပျော်သွားကြပြီ။ ဤမည်သောသစ်ပင်အောက်­ မြှုပ်ထားသောဥစ္စာကို သၚ်မကြည့်တော့ပြီလော” ဟုသူဌေးမ')
,(1584,3,4,'ရည်မှန်းချက်မရှိ လှည့်လည်သွားလာသည်။ လေလွင့်သည်။ ခြေဦးတည့်ရာလျှောက် သွားသည်။ ဟိုဟိုဒီဒီ လှည့်ပတ်သွားလာသည်။','“လၟဂှ် တလိၚ်ဒိုဟ်ပ္ဍဲဂြိုပ်တုဲ ဇၞတ်မကြၚ်အာ စိုပ်အာဘာရသိရ။” = “မုဆိုးသည် တောထဲတွင် အရပ်မျက်နှာအမှတ်မှား၍ ဟိုဟိုဒီဒီလျှောက် သွားရင်း ရသေ့ကျောင်းသို့ ရောက်သွားသည်။” || “(ကောန်သေဋ္ဌဳဂှ်) ကြဴဝွံ ဂတှ်ညးဂၠိုၚ်အာတုဲ ညးကၠုၚ်မိက်ရ၊ လေဲကဵုညးဟွံမာန်တုဲ ဒဴကြၚ်အာရ။” (ဇ—၄၈၂။ အစွောံ။) = “ထိုသူဌေးသားသည် နောက်ကာလ­ အကြွေးများသွား၍ အကြွေးရှင်တို့ အကြွေးလာတောင်းကြကုန်၏၊ မပေးလျော်နိုင်သဖြင့် ခြေဦးတည့်ရာ တိမ်းရှောင်သွား၏။” || “မၚ်ဗၠာဲမိတ္တဝိန္ဒကဂှ် ဂွံကောန်သမ္ဘာဇကု တုဲ ကြၚ်အာကၠေံရ။” (ဇ—၄၁။ အစွောံ။) = “မိတ္တဝိန္ဒကလုလင်သည် သားမယားကိုယူ၍ ခြေ ဦးတည့်ရာ အရပ်တစ်ပါးသို့သွား၏။”')
,(1585,3,4,'ဟိုဟိုဒီဒီသွားသည်၊ ခြေဦးတည့်ရာသွားသည်။','‘ကြၚ်’ နှင့်အတူတူ။')
,(1586,3,4,'၁။ တံစဉ်းဖြင့်တိုက်သည်။','ကြာၚ်ပသဲ = တံစဉ်းဖြင့် သံကိုပွတ်တိုက်သည်။')
,(1586,3,4,'၂။ (ငါးများ) ဆူးတောင်ဖြင့်ယက်သွားသည်။', NULL)
,(1587,3,1,'ချောင်း။',null)
,(1588,3,1,'ရိုးချောင်း။',null)
,(1589,3,1,'သပြေပင်။ သပြေသီး။','ကြေၚ်ဇမ္ဗူရှ် = ဇမ္ဗူ့သပြေသီး။ || “ခ္ဍာ်မွဲဍုန်ဒၟံၚ် ပ္ဍဲကၞာၚ် ကြေၚ်ဂှ်တုဲ စတဴသတ်ကြေၚ်ဂှ်ရ။” (ဇ—၂၉၄။ အစွောံ။) = “တခုသောကျီးသည် သပြေခက်­ နားလျက် သပြေသီးမှည့်ကိုစား၏။” (ညောင်ကန်)')
,(1590,3,1,'ကြက်တူရွေးတစ်မျိုး။',null)
,(1591,3,1,'ပန်းပဲဖို။ သံထည်အလုပ်ရုံ။',null)
,(1592,3,4,'၁။ (အသီးအရွက်စသည်) ရင့်သည်။','“တၞံကြုက်ပ္ဍဲသ္ၚိပိုဲဂှ် သတ်ဍေံကြံၚ်ဒၟံၚ်ဣရ။” = “ငါတို့အိမ်ရှိသရက်ပင်သည် အသီးရင့်နေပြီ။”')
,(1592,3,4,'၂။ မာသည်။ ကြမ်းသည်။','“ယာတ်ဏအ် ကြံၚ်ဒၟံၚ် ဟွံဇိပ်ဂၠိပ်ရ။” = “ဤစောင်သည် မာကြမ်းနေသည်။ မသိမ်မွေ့မပြေပြစ်ပါ။”')
,(1592,3,4,'၃။ (ပါရမီ၊ ဉာဏ်ပညာစသည်) ရင့်ကျက်သည်။', 'ပညာကြံၚ် = ပညာရင့်သည်။ ပါရမဳကြံၚ် = ပါရမီရင့်သည်။')
,(1592,3,4,'၄။ (အရောင်) ရင့်သည်။','“သာ်ဍီုဏအ်ကြံၚ်အာ အဲဟွံဒးစိုတ်ရ။” = “ဤအပြာရောင်သည် ရင့်သွားသည်။ ကျွန်တော်မကြိုက်ပါ။”')
,(1593,3,4,'ရင့်မှည့်သည်။ ရင့်ကျက်သည်။ ရင့်မာသည်။ ကြီးရင့်သည်။','ပညာကြံၚ်ဍုဟ် = ပညာရင့်ကျက်သည်။ || ပါရမဳကြံၚ်ဍုဟ် = ပါရမီရင့်သည်။ || ဂၠံဂဝ်ကြံၚ်ဍုဟ် = ကိုယ်ဝန်ရင့်မာသည်။ || “ခမဳဗြဴဂှ် ဂၠံဂဝ်ကြံၚ်ဍုဟ်အာတုဲ သၠးဂဝ်ဂၞဴ ဂွံကောန်တြုံမွဲရ။” (ဇ—၁၂။ အစွောံ။) = “ထိုရဟန်းမိန်းမသည် ကိုယ်ဝန်ရင့်မာ၍ သားယောကျာ်းတစ်ယောက်ကို ဖွားမြင်၏။” || “(ကောန်သၟိၚ်ဂှ် ဇီုဗပါ်ကၠေံဗဗေၚ်ပစ္စေဂဗုတ်ဂှ်) ပ္ဍဲချိုန်ခဏဂှ်ဟေၚ် သရာံပါပ်ဂှ် ကြံၚ်ဍုဟ်တိုန်တုဲ ကတဴတိုန်အလုံဇကုကောန်သၟိၚ်ဂှ်—။” (ဇ—၂၂ဝ။ အစွောံ။) = “မင်းသားသည် အရှင်ပစ္စေက ဗုဒ္ဓာ၏သပိတ်ကို ဆောင့်ခွဲပစ်လိုက်၏။ ထိုခဏ­ပင် ထိုမကောင်းမှုသည် ရင့်မှည့်လာရာ မင်း သား၏ကိုယ်အလုံးသည် ပူလောင်လာ၏။”')
,(1594,3,4,'ခြောက်သွေ့သည်။',null)
,(1595,3,4,'၁။ မာကျောသည်။','“ဆုကြက်လကံဝွံဂှ် ဍေံကြံၚ်မ္ၚိုဟ်က္ဍၚ်သန်ရောၚ်။” (ဇ— ၂၁ဝ။ အစွောံ။) = “ရှားပင်တို့မည်သည်ကား — ချင်ချင်မာကုန်၏။” (ညောင်ကန်)')
,(1595,3,4,'၂။ (စကား၊ အပြုအမူစသည်) ရင့်သီးသည်။ ရုန့်ရင်းသည်။','ဂလာန်မကြံၚ်မ္ၚိုဟ် = ရင့်သီးသောစကား။ “(ကောန်သၟိၚ်ဂှ်) ဇၞော်ကဵုဒေါသ ကြံၚ်မ္ၚိုဟ်သ္ကာတ်မြဟ်လောန်။” (ဇ—၁၄၉။ အစွောံ။) = “ထိုမင်းသားသည် အမျက်ကြီး၏၊ ရုန့်ရင်းကြမ်းကြုတ်၏။”')
,(1596,3,4,'၁။ (လှောင်အိမ်ထဲတွင်) လှောင်သည်။','“လၟမွဲဂှ် လောပ်အာဂြိုပ် ပံါဂွံဂစေံဒဂိုတ် မဂၠိုၚ်တုဲ ကြိုၚ်လဝ်တုဲ သွံစဂယိုၚ်လမျီုရ။” (ဇ—၁၁၈။ အစွောံ။) = “တစ်ယောက်သောမုဆိုးသည် တောသို့ဝင်၍ များစွာသော ငုံးငှက်တို့ကိုဖမ်းပြီးလျှင် လှောင်ထားကာ ရောင်း၍အသက်မွေး၏။” || “သီုညးမသုန်ဂှ် ကြိုၚ်လဝ်ကောံကောံတုဲ—။”(ဇ—၉၂။ အစွောံ။) = “ထိုငါးယောက် သောသူတို့ကို တစ်နေရာတည်းစု၍ (အချုပ်ခန်းတွင်) လှောင်ထား၏။”')
,(1596,3,4,'၂။ သိုလှောင်သည်။','ကြိုၚ်လဝ်ဍာ် = ရေသိုလှောင်ထားသည်။ || ကြိုၚ်လဝ်အပေါတ်ဗၞိက် = ကုန်ပစ္စည်းများ သိုလှောင်ထားသည်။')
,(1597,3,4,'ဟိုဟိုဒီဒီ ခြေဦးတည့်ရာသွားသည်။ လှည့်လည်သည်။','“ၝောံပြာပ်အာဍုၚ်ဗာရာ ဏသဳတုဲ ၝောံဟွံဒးကြိုၚ်အာတ်စရ။ ဂွံစၞတသိုက်ရ။” (ဇ—၁၉၃။ အစွောံ။) = “ရှင်မ၊ သင်သည် ဗာရာဏသီပြည်သို့ သွားရောက်ပါက လှည့်လည်တောင်းစားနေစရာ မလိုတော့ပါ။ အစာကို ချမ်းသာစွာရလတ္တံ့။” || “(ကောန်သေဋ္ဌဳဂှ် ဆဝေၚ်ဂြိုၚ်သုၚ်စဂှ် ဒြပ်တံဂှ်အိုတ်အာတုဲ) ဒိုက် ဒိန်ကၠၚ်ကၠောန်အာရ။ ဒးသပိုၚ်ယာတ်ခမၞက် ကြိုၚ်တဴရ။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုသူဌေးသားသည် ပျော်ပါးသောက်စားခြင်းဖြင့်သာလျှင် ဥစ္စာတို့သည်ကုန်၍ ဆင်းရဲအထီးကျန်သည်ဖြစ်၍ ပုဆိုးနွမ်းကိုဝတ်လျက် ခြေဦးတည့်ရာသွား၏။” || “ဘဲပရိုက်ဘဲပိသာ်က္တဵုဒှ်တုဲ မၞိဟ်ဂမၠိုၚ်ယိုက် ကောန်တုဲ ဂ္ၚေၚ်ကြိုၚ်တဴအိုတ်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “ကပ်ဘေးသုံးမျိုးဖြစ်ပေါ်၍ လူတို့သည် သားတို့ကိုချီကုန်၍ ဟိုဟိုဒီဒီ လှည့်လည်ကြကုန်၏။” ‘ကြၚ်’ နှင့်အဓိပ္ပါယ်အတူတူ။ ‘တြိုၚ်’ ဟုလည်းရေးသည်။')
,(1598,3,4,'‘ကြၚ်’','‘ကြိုၚ်၂’ နှင့် အဓိပ္ပါယ်အတူတူ။')
,(1598,3,4,'‘ကြၚ်’','“မၚ်ဗၠာဲဒိုက်အာရ။ ဒးသ ပိုၚ်ယာတ်ခမၞက်တုဲ ရပ်ကဝေက် ဒးကြိုၚ်ကြၚ်အာတ်စ—။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုလုလင်သည် ဆင်းရဲသွား၏။ အဝတ်နွမ်းကိုဝတ်၍ ခွက်လက်စွဲကာ လှည့်လည်တောင်းစားရ၏။”')
,(1599,3,4,'ခြေဦးတည့်ရာသွားသည်။','“ဇၞတ်သၟိၚ်မကြိုၚ်ဂနိၚ်အာ အာဂွံတ္ကံမွဲ ပိၚ်္ဂ လဒိပ္ပဂးယၟု။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မင်းသည် ခြေဦးတည့်ရာ သွားသည်ရှိသော် ပိၚ်္ဂလ ဒဳပအမည်ရှိသော တစ်ခုသောကျွန်းသို့ ရောက်သွား၏။”')
,(1600,3,4,'လမ်းဖြတ်တားဆီးသည်။','“ကၠာဒပ်ပၞာန်သတြုဟွံစိုပ်ဏီဂှ် ဒပ်ပၞာန်ပိုဲကြတ်ဗ္တိုက် ပ္ဍဲဒေါဝ်တရဴရ။” = “ရန်သူ့စစ်တပ်ရောက်မလာမှီ ငါတို့စစ်တပ်က လမ်းခုလပ်မှ ဖြတ်၍တိုက် ခိုက်သည်။”')
,(1601,3,4,'ရှေ့ဖြတ်ဆီးတားသည်။',null)
,(1602,3,4,'ကြိုတင်ပြုလုပ်သည်။','“ကၠာပၟတ်ဟွံတူ ပိုဲဒးကြတ်ဒုၚ်စဵုဒၞာလဝ်ရောၚ်။” = “မီးမလောင်ခင် ငါတို့တွေ ကြိုတင်ကာကွယ်ထားရမည်။”')
,(1603,3,4,'စောင့်ကြည့်သည်။ ထောက်လှမ်းသည်။',null)
,(1604,3,4,'ဆေးသည်။ ဆေးကြောသည်။','ကြာတ်တဲ = လက်ဆေးသည်။ ကြာတ်က္ဍိုပ် = ခေါင်းဆေးသည်။ ခေါင်းလျှော်သည်။ (န) ဝါပင်တစ်မျိုး။')
,(1605,3,4,'ဆေးကြောသည်။','‘ကြဴကြာတ်’ ရှု။')
,(1606,3,4,'သန့်ရှင်းအောင်ဆေးကြောသည်။',null)
,(1607,3,1,'၁။ ခန္ဓာကိုယ်တွင်းရှိအူ။',NULL)
,(1607,3,1,'၂။ (အပင်စသည်၏) အူတိုင်။','ကြုတ်ဆု = သစ်ပင်အူတိုင်။')
,(1608,3,1,'ဝက်အူချောင်း။ (စားဖွယ်)',null)
,(1609,3,1,'မြက်ကြွပ်ပင်။',null)
,(1610,3,1,'အူမကြီး။',null)
,(1611,3,1,'အူသိမ်။',null)
,(1612,3,11,'(န) ‘ကရုဏာ’ ရှု။',null)
,(1613,3,1,'တီကောင်။',null)
,(1614,3,1,'ယက္ကန်းတိုင်ချည်။',null)
,(1615,3,5,'လှည်းဝင်ရိုးသံကဲ့သို့သောမြည်သံ။',null)
,(1616,3,1,'၁။ ကြုတ်။ (အဖုံးပါသော ဝါးကျည်ထောက်ပုံရှိသော ထည့်စရာ။) (ပါဠိ—ကရ ဏ္ဍက)',NULL)
,(1616,3,1,'၂။ သပိတ်ပင်။',NULL)
,(1617,3,1,'ချိပ်။ ချိပ်ပိုးမှထွက်သည့် အစေးနီ။','ဍာ်ကြိုတ် = ချိပ်ရည်။ “(ဗောဓိသတ် ဒှ်စိၚ်ဗ္တာၚ်) ဇိုၚ်ပန် (ညံၚ်) စဳဖျောန်သနောဟ်လဝ် နဍာ်ကြိုတ်ကီု။” (ဇ—၇၂။ အစွောံ။) = “ဘုရားလောင်းသည် ဆင်ဖြူဖြစ်၍ အခြေလေးချောင်းတို့သည် ချိပ်ရည်ဖြင့် ဆိုးထားဘိသကဲ့သို့ဖြစ်၏။”')
,(1618,3,4,'ချိန်းဆိုသည်။ ချိန်းချက်သည်။','“ပ္ဍဲသမယမွဲ ဍေံတံကြန်လဝ်တုဲ—။” (ဇ—၄၉။ အစွောံ။) = “တစ်ခုသောနေ့ရက်ကို သူတို့ချိန်းချက်ထားပြီးသော်—။”')
,(1619,3,1,'အချိန်းအချက်။ ချိန်းဆိုထားသောအချိန်။','“ယွံဒေဝတဴဇြဲ၊ အဲအာတ်ကောန်တြုံမွဲဂှ် ပေၚ်အာထပှ်တ္ၚဲရ။ ပ္ဍဲတ္ၚဲဝွံဂှ် ကၠုၚ်စိုပ်ကြန်သမွဲအဲဂှ်ရ ဒေဝတဴ” ပြော ဟိတ်ဂး။ (ဇ—၅ဝ၉။ အစွောံ။) = “ဟယ်ညောင်စောင့်နတ်၊ သားတစ်ယောက်ကို ငါတောင်း ထားသည်မှာ ခုနစ်ရက်စေ့ပြီ။ ယနေ့သည် ငါ့အချိန်းအချက်အချိန်ရောက်ပြီ။”')
,(1619,3,4,'ချိန်းချက်သည်။ ချိန်းဆိုသည်။ အချိန်းအချက်ပြုသည်။ ကတိပြုသည်။','“တ္ၚဲယးဂတ ပ္ဍဲစှ်နာဍဳ ပိုဲဆဵုဂဗ ညးသ္ကအ် ပ္ဍဲဘာလကျာ်ရောၚ် ပိုဲကြန်သမှဲလဝ်ရ။” = “မနက်ဖြန်ဆယ်နာရီ ဘုန်းကြီးကျောင်းမှာ ငါတို့တွေ့ဆုံကြမည်ဟု ချိန်းဆိုထားကြသည်။” || ‘သမောဲကြန်’/‘သမွဲကြန်’/‘သမှဲကြန်’ နှင့် အတူတူ။')
,(1620,3,4,'၁။ ရမ်းသည်။ ရမ်းကားသည်။','“ကျတှ်ေကြာန် မာန်တှ်ေကြအ်။” = “ရှုံးလျှင်ရမ်း နိုင်လျှင်ရူး။”')
,(1620,3,4,'၂။ ရမ်းဆသည်။ ရမ်းသန်းပြောသည်။','“ပ္ဍဲသ္ကေမ်တဲဍေံ ဍေံကေမ်လဝ် သြန်မွဲဒကေဝ်ရောၚ် အဲကြာန်ဟီုစုတ်ဏာ ဍာံအာရ။” = “သူ့လက်ဆုပ်ထဲတွင် ငွေတစ်ကျပ် သူဆုပ်ထားသည်ဟု ကျွန်တော်ရမ်းသန်းပြောလိုက်ရာ မှန်သွားသည်။”')
,(1621,3,4,'ယှက်သန်းသည်။ ထွေးယှက်သည်။ (ပင့်ကူကွန်ယက်) ဖြန့်ကြက်သည်။','“ပ္ဍဲတၞံဂှ် ဇုက်ခြုံကြာန်ပေၚ်ဒၟံၚ်ရ။” (ဇ—၁၉၃။ အစွောံ။) = “ထိုသစ်ပင်­ ခြုံနွယ်များပြည့်ယှက်နေ၏။” || “ဖိုၚ်ကၠဇၞော်မွဲဂှ် ဍေံရပ်စၜိုပ်တံဂှ် ဍေံချပ်တုဲ ဍေံဒက်ကြာန်လဝ်ဇာ ပ္ဍဲပါၚ်ဂိုဟ်ဂှ်ရ။”(ဇ—၅ဝ၉။ အစွောံ။) = “ပင့်ကူကြီးသည် ဟၚ်္သာတို့ကိုဖမ်းစားရန် လိုဏ်ဂူဝ­ ပင့်ကူကွန်ယက်တို့ကို ဖြန့် ကြက်ဖွဲ့ထား၏။” || “လထဴဗျုဂှ်ဇြာဲ ဇြေဟ်တုဲ လတေၚ်ကြာန်ဒၟံၚ်ရ။” = “အဖိုးအိုသည် ပိန်လှီ၍ အကြောပြိုင်းပြိုင်းထနေ၏။” || ‘ကြာန်ဒမာန်’ လည်းရှု။')
,(1622,3,5,'အရမ်းမဲ့။ အရမ်းကာရော။ မစဉ်းစားမဆင်ခြင်ဘဲ။',null)
,(1623,3,4,'(သစ်ပင်နွယ်ပင်စသည်) ကူးလူးယှက်သန်းသည်။ ပွားများစည် ပင်သည်။',null)
,(1624,3,4,'ရမ်းဆသည်။','“လဟီုမွဲမဟီုဂှ် တီချိုတ်ပၠိုတ်တုဲဟီုညိ၊ ကြာန်ဆတုဲလ္ပဟီုညိ။” = “စကားပြောဆိုလျှင် သေချာစွာသိပြီးမှပြောပါ၊ ရမ်းဆပြီးမပြောပါနှင့်။”')
,(1625,3,4,'ရှုပ်ထွေးယှက်သန်းသည်။',null)
,(1626,3,4,'ရှုပ်ထွေးသည်။ ထွေးရောယှက်တၚ်ဖြစ်သည်။',null)
,(1627,3,4,'၁။ ရမ်းကားသည်။ သွေးရူးသွေးတန်းဖြစ်သည်။','“သုၚ်ဗ္ၜူ အရက်တုဲ လ္ပကြာန်ဓမာန်ညိ။” = “အရက်သောက်မူးပြီး မရမ်းကားပါနှင့်။”')
,(1627,3,4,'၂။ ယောင်ယမ်း မြည်တမ်းသည်။','“ဟာဲသၟိၚ်ဂန္ဓရးသမၠီု၊ ဗှ်ေလ္ပကၠုၚ်ကြာန်ဓမာန်ဒၟံၚ်ရ။ ဗဵုလဗးပၞာန်ဗှ်ေ ပၞာန်စိၚ် ချေံတိုက်ကွဳ သီုဖအိုတ်တံဂှ် — အဲလၞိန်ဗပိန်ထောံကၠေံရ။” (ဇ—၂၃ဝ။ အစွောံ။) = “ဟယ်ငမိုက်၊ သင်သည် မယောင်ယမ်းမမြည်တမ်းလင့်။ — သင်၏စစ်သည်အပေါင်းကို (ငါ) ဖျက်ဆီး လိုက်အံ့။” (ညောင်ကန်) || “ဗမၞးသၚ်္ခဝွံ ဟိုတ်နူမဖေက်ဂစိုတ်တုဲ ဟီုကြာန်ဒမာန်အာရောၚ်သဒှ်။” (ဇ—၄၄၂။ အစွောံ။) = “ဤ(သၚ်္ခ)ပုဏ္ဏားသည် သေဘေးမှကြောက်သဖြင့် ငိုကြွေးမြည် တမ်းယောင်တကား။” (ညောင်ကန်)')
,(1628,3,4,'(အကြော) ပြိုင်းပြိုင်းထသည်။ ပြိုင်းရရိုင်းထသည်။','“ရသိ ညာတ်သၟိၚ်နာ်ဂှ်တုဲ ဖေက်တုဲ ဇြာဲဇြေဟ်ဖျောဟ်ဂတး လတေၚ်ကြာန်ဒမာန်တဴရ။” (ဇ—၂၅၃။ အစွောံ။) = “ရသေ့သည် နဂါးမင်းမှကြောက်သောကြောင့် ကြုံလှီ၏။ — ဖက်ရွက်ရော်ကဲ့သို့ ဖျော့တော့သောအဆင်းရှိသည်ဖြစ်၏။ အကြောပြိုင်းပြိုင်းထသောကိုယ်ရှိသည်ဖြစ်၏။” (ညောင်ကန်) “ဂမှဳမွဲဂှ် စိုတ်စပ်အာကဵုဗြဴမွဲတုဲ ဒတူတလှာဲရာဂဂှ်တုဲ ဇြေဟ်ဇြာဲဖျိုဟ်ဂတးတုဲ လတေၚ်ကြာန်ဓမာန်တဴရ။” (ဇ—၅၂၇။ အစွောံ။) = “ထိုရဟန်းသည် မိန်းမတစ်ယောက်ကိုမြင်လေလျှင် တပ်စွန်းသောစိတ်ရှိသည်ဖြစ်၍ ရာဂနှိပ်စက်သည်ဖြစ်၍ ကြုံကြုံလှီလှီ အကြောပြိုင်းပြိုင်းထသော ကိုယ်ရှိသည်ဖြစ်၍ ဖက်ရွက်ရော်ကဲ့သို့ ဖျော့တော့သောအဆင်းရှိသည်ဖြစ်၏။” (ညောင်ကန်)')
,(1629,3,4,'၁။ (လူစသည်) ကြုံလှီသည်။ သေးပိန်သည်။','“ကောန်ၚာ်ဗှ်ေဏအ် မူဒှ်ဂွံကြေန်တဴ ဂလိုၚ်ဏအ်ရော။ ဍေံဟွံဖဲတှ်ဟာ။” = “နင့်ကလေး ဘာဖြစ်လို့ ဒီလောက်တောင်ပိန်သေးရသ လဲ။ နို့မဝလို့လား။”')
,(1629,3,4,'၂။ (ကြိုးအစိတ်အပိုင်း) သေးငယ်ကြုံလှီသည်။','“ဇုက်သတ်ဗြဴဂှ် ကြေန် ဒၟံၚ်ကြပ်ပိုတ်ရ။” = “ထိုအုန်းဆံကြိုးသည် (တစ်နေရာတွင်) သေးငယ်ကြုံလှီနေသည်မှာ ပြတ် လုနီးပြီ။”')
,(1630,3,1,'ကင်းလိပ်ချော။','“ဇြုံကီု အယဴကီု ဂဂဳကီု ဖိုၚ်ကၠကီု ကြောန်၊ ကၞိ—။” (ဇ—၂ဝ၃။ အစွောံ။) = “မြွေ၊ ကင်းမြီးကောက်၊ ကင်းခြေများ၊ ပင့်ကူ၊ ကင်းလိပ်ချော၊ ကြွက်—။”')
,(1631,3,4,'မာသည်။ (တံတောင်ဆစ်၊ ဒူးဆစ်စသည်တွင်) ကြွပ်တက်ပြုပ်ထသည်။','“ဒးယိုက် လဝ်ဂၠိုၚ် ဒၚ်ပၞးကြိုန်အာရ။” = “ထမ်းထားရသည်များသောကြောင့် ပုခုံးမာသွားသည် (ဝါ) ပု ခုံးကြွပ်တက်သည်။”')
,(1632,3,4,'နီးသည်၊ နီးကပ်သည်။','“ကြပ်စိုပ်သ္ၚိရ။”= “အိမ်ရောက်လုနီးပြီ။” || ကြပ်ချိုတ် = သေလုနီးပါး။ သေလုမတတ်။ || ကြပ်စပုၚ် = ထမင်းစားအံ့ဆဲဆဲ။')
,(1633,3,4,'(= ဗာန်)။ (အစေးစသည်­) ကပ်သည်။ ကပ်ငြိသည်။','“(ဗောဓိသတ်စၞေဟ်ကဵုကလော်ဇၜိုတ်ဂှ် ပန်ကဵုကံ) ကံဂှ်ကြပ်အာ — ဗာ်ကဵုသၞာ် သၞာ်ကြပ်အာ၊ တက်ကဵုထကိုအ်ကံ ထကိုအ်ကံကြပ်အာ၊ တက်ကဵုလေံ လေံကြပ်အာ၊ တက်ကဵုတ္ၚ တ္ၚကြပ်အာ၊ တက်ကဵုတဲၜါ တဲၜါကြပ်အာ၊ ထနိက်ကဵုဇိုၚ်ၜါ ဇိုၚ်ၜါကြပ်အာ၊ ထဗတ်ကဵုက္ဍိုပ် က္ဍိုပ်ကြပ်အာ၊ လွဟ်မသုန်ဂှ်လေဝ် ကြပ်အာ၊ အဝဲမသုန်ဂှ်လေဝ် ကြပ်အာသီုဖအိုတ်။” (ဇ—၅၅။ အစွောံ။) = “ဘုရားလောင်းသည် စေးသောကိုယ်အမွေးရှိသော ဘီလူးနှင့်တကွ စစ်ထိုး၏။ မြှားနှင့်ပစ်ရာ မြှားသည် ဘီလူး၏ကိုယ်အမွေး­ ကပ်ငြိသွား၏။ သန်လျက်နှင့်ခုတ်ရာ သန်လျက်ကပ်သွား၏။ မြှားတောင့်နှင့်ခတ်ရာ မြှားတောင့်ကပ်သွားပြန်၏။ ဆောက်ပုတ်ဖြင့်ခတ်ပြန်သော် ဆောက်ပုတ် ကပ်ငြိသွားပြန်၏။ လေးဖြင့်ရိုက်ပြန်ရာ လေးသည်လည်း ကပ်ငြိသွားပြန်၏။ လက်နှစ်ဖက်တို့ဖြင့် ရိုက်ပြန်ရာ လက်နှစ်ဖက်လည်း ကပ်ငြိသွားပြန်၏။ ခြေနှစ်ဖက်တို့ဖြင့် ကန်ကျောက်ပြန်ရာ ခြေနှစ်ဖက်လည်း ကပ်ငြိသွားပြန်၏။ ဦးခေါင်းနှင့်တိုက်ပြန်ရာ ဦးခေါင်းလည်း ကပ်ငြိသွားပြန်၏။ လက်နက်ငါးမျိုးတို့သည်လည်း ကပ်ငြိသွားကုန်၏။ ကိုယ်အၚ်္ဂါငါးခုတို့သည်လည်း ကပ်ငြိသွား ကုန်၏။”')
,(1634,3,4,'နှစ်ဖက်မှညှပ်သည်။ ညှပ်ပိတ်သည်။ ညှပ်ပူးညှပ်ပိတ်ဖြစ်စေသည်။','“ဒပ်ပၞာန်ပိုဲကြာပ် ဗ္တိုက်ဂွံ ဒပ်ပၞာန်သၞရ။” = “ငါတို့စစ်တပ်သည် ရန်သူ့တပ်ကို နှစ်ဖက်မှညှပ်ပိတ်၍ တိုက်ခိုက်သည်။” || “ကကြၚ်ဂှ် ကြာပ်ကဵုကရာပ်တုဲ ပရာၚ်ညိ။” = “ထိုငါးကြင်းကို ညှပ်ဖြင့်ညှပ်၍ မီးကင်ပါ။” || ‘ကရာပ်’ (န) လည်းရှု။')
,(1635,3,4,'တူသောနတ်ကိုးကွယ်သူများအကြားသို့ ကိုးကွယ်ရာနတ်မတူသော သူတစ် ယောက်ယောက်က ဝင်ရောက်နေထိုင်သည်။ နတ်ညှပ်သည်။',null)
,(1636,3,4,'မောင်နှမများအကြား­ တစိမ်းတစ်ယောက်ယောက်က ဝင်ရောက်နေထိုင်သည်။ နို့ညှပ်သည်။ နတ်ညှပ်သည်။',null)
,(1637,3,1,'ကိုက်ဝါးစား၍ ကျွတ်ကျွတ်မြည်သံ။',NULL)
,(1637,3,4,'ကျွတ်ကျွတ်အသံမြည်လျက် (ကိုက် ဝါးစားသည်။)','“ကောန်ၚာ်ဂှ်ဒှ်မၞိဟ်တုဲဗက် ကလော်ဗြဴမွဲဂှ် ကိတ်စကၠေံကြိပ်ကြိပ်ရ။” (ဇ—၅၁ဝ။ အစွောံ။) = “(ထိုသူငယ်လူဖြစ်လာသည်နှင့်) ဘီလူးမသည်လည်း သူငယ်ကို ကြာစွယ်ကြာရင်း ကဲ့သို့ ကျွတ်ကျွတ်ဝါးစား၍—။” (ညောင်ကန်) || “ဗ္ၜေအ်ထဍေၚ်ဗက်ဗြန်တုဲ ဍေံကိတ်စဗြန်ကြိပ်ပ် ရ။ လ္ပအ်သာ်ဂှ် အဲဍိက်ညာတ်အတ်အဴ” သၟိၚ်ပဿိုန်ဂး။ (ဇ—၇၇။ အစွောံ။) = “အကျွန်ုပ်သည်ကား ဆိတ်တို့သည် သစ်တို့ကို လိုက်ကုန်၍ ကြွပ်ကြွပ်မြည်စေကုန်၍ စားကုန်သည်တို့ကို မြင်မက်၏။” (ညောင်ကန်)')
,(1638,3,16,'‘ကြိပ်ကြိပ်’၊ ‘ကြောပ်ကြောပ်’ တို့နှင့်အတူတူ။',null)
,(1639,3,4,'၁။ ရစ်ပတ်ဖုံးအုပ်သည်။','“ဍိုတ်တအ်ဂှ် ကြုပ်လဝ်ကဵုအၚ်္ဂဒဵုရ။”= “ထိုအုတ်တို့ကို အၚ်္ဂတေဖြင့် ရစ်ပတ်ဖုံးအုပ်ထားသည်။”')
,(1639,3,4,'၂။ ‘ကြုပ်—၁’ ရှု။', NULL)
,(1639,3,4,'၃။ ငိုက်မျဉ်းသည်။', '‘မတ် ကြုပ်’ ရှု။')
,(1640,3,4,'နှစ်ခုကြားညှပ်မိသည်။','“ဒဝ်တရၚ်မ္ဂး စွံသတိ တဲလ္ပကဵုကြေပ်ညိ။” = “တံခါးပိတ်လျှင် သတိထားပါ၊ လက်မပေးညှပ်မိပါစေနှင့်။” ‘ကရေပ်’ (န) လည်းရှု။')
,(1641,3,4,'ကျဉ်းကျပ်သည်။',null)
,(1642,3,4,'သွားကြားညှပ်သည်။',null)
,(1643,3,1,'အိမ်မိုးသောအုတ်ကြွပ်။ (ပါဠိ—ဆဒနိဋ္ဌကာ)',null)
,(1644,3,1,'(ကြိဝိ) ‘ကြိပ်ကြိပ်’ နှင့်အတူတူ။','“ဂတဝွံ ကဵုအဲဒှ်ကလော်ဗြဴတုဲ ကဵုအဲဂွံ ကိတ်စကောန်ဗှ်ေကြောပ်ပ်ညိ” (သာ်ဝွံ) ဗြဴသမင်ဂှ် (ပလဝ်သွဴရ။) (၅၅ဝ။ ဇ—၅၁၃။ ၈—၁၅၇။ အစွောံ။) = နောင်­ငါသည် ဘီးလူးမ ဖြစ်၍ သင်၏သားကို ကျွတ်ကျွတ်ဝါးလျက် စားရပါ စေသော်” ဟု ထိုအမြုံမသည် ကျိန်ဆိုထား၏။')
,(1646,3,4,'မြော့သည်။ နွမ်းနယ်ပျော့ခွေသည်။','တိက်ကြိုပ် = နွမ်းနယ်ပျော့ခွေစွာအိပ်သည်။ ‘ကြုပ်’ ဟုလည်းတွေ့ရသည်။ “(ဟိုတ်ပြောဟိတ်ဟွံဒ္ဂေတ်ဗက်စိုတ်ဂၞကျာ်တုဲ ကဵုသၟိၚ် ဂစိုတ်ကၠေံပြောဟိတ်ရဂးတုဲ ညံၚ်ရဴပြောဟိတ်မပလီုပလာ်တက်ၜုၚ်လဝ်ဇကုကီု ဂၞကျာ်ပတုဲ) လ အက်ကၠေၚ်ကဵုဇကုတုဲ ဂလီုယာတ်တုဲ ဂၞကျာ်သတိက်ကြုပ်ဒၟံၚ် ပ္ဍဲဒေန်ဇကုရ။” (ဇ—၂၂ဝ။ အစွောံ။) = “မိဖုယားသည် ကိုယ်ကိုဆီလူး၍ စောၚ်ခြုံလျက် ညောင်စောင်း­ နွမ်းနယ်ပျော့ခွေစွာ အိပ်နေ၏။”')
,(1647,3,4,'(မိုး)သည်းထန်သည်။','“တ္ၚဲဏအ် ဗြဲဂူကြိုပ်တဴ ကၠိုဟ်တ္ၚဲရ။” = “ယနေ့ တစ်နေ့လုံး မိုးသည်းထန်စွာ ရွာသွန်းသည်။”')
,(1648,3,1,'ကမ္ဘောဇတိုင်းသားများကို ရှေးကခေါ်သောအမည်။ ကြွမ်း။','“ပၞာန်ကြောမ်ကၠုၚ်ဗ တိုက်ဍုၚ်မန်။” = “ကြွမ်းစစ်သည်များ မွန်ပြည်ကို လာရောက်တိုက်ခိုက်သည်။”')
,(1649,3,4,'ကြုံးဝါးသည်။ ဥဒါန်းကျူးသည်။','“ဟိုတ်နူအဲမဒ္ဂေတ်ဂလာန်အ္စာအဲတုဲရောၚ် အဲကလိဂွံ ပိုုန်ဟာန်ယဿပတ်ကၟိန်ဍုၚ်ဝွံရောၚ်သွံ” (သၟိၚ်)ချပ်ရံၚ် အိုဟ်တၟိုဟ်စိုတ်တုဲ ဂလာန်မြဴဝွံ ကြီုတိုန် ရ။ (ဇ—၈။ အစွောံ။) = “ငါသည် ငါ့ဆရာ၏စကားကို လိုက်နာသောကြောင့်သာ ဤထီးနန်း စည်းစိမ်အခြံအရံကို ရရှိခြင်းဖြစ်၏” ဟုမင်းသည်ကြံအောက်မေ့၍ ဝမ်းမြောက်သည်ဖြစ်၍ ဤ သို့သောဥဒါန်းကို ကျူးရင့်၏။ || “အဲဇၞးအဲဇၞး သာ်ဝွံလလောၚ်ကြီုပိဝါရ။” (ဇ—၇ဝ။ အစွောံ။) = “ငါအောင်ပြီ ငါအောင်ပြီဟု ပဲ့တင်ထပ်အောင် သုံးကြိမ်ကြုံးဝါး၏။” || “ကရီုညံၚ်ခေသရာဇာဒိ သိုၚ်ကီု ဗောဓိသတ်ကြီုတဴရ။” (ဇ—၁၆၃။ အစွောံ။) = “ကေသရာဇာခြင်္သေ့မင်း၏ ကြုံးဝါး ခြင်းကဲ့သို့ ဘုရားလောင်းကြုံးဝါး၏။” || “(ဂွံစၞေဟ်ဝေၚ်ပၞာန်ရဂးတုဲ) သၟိၚ်ကလိၚ်မိၚ်တုဲ တက် ကၞက်ကြီုတဴရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “စစ်ထိုးကစားရတော့အံ့ဟု ကာလိၚ်္ဂမင်းကြားသည် ရှိသော် လက်ပမ်းပေါက်ခတ်၍ ကြုံးဝါး၏။”')
,(1650,3,4,'ကြုံးဝါးသည်။','“(ညးဂၟံၚ်လ္ၚီတံဂှ်) မိၚ်ပရိုၚ်သတြုတုဲ မိပ်စိုတ်စရိုတ်ကြီုကြတဴ။” (ဇ—၅၁။ အစွောံ။) = “ထိုတစ်ထောင်ကုန်သောသူရဲတို့သည် ရန်သူလာသည့် သတင်းကိုကြားသည်ရှိသော် ပျော်ရွှၚ်မြူးထူးကုန်၍ ဟစ်ကြွေးကြုံးဝါးကုန်၏။” || (ဒမၠမသုန်စှ်ောယုတ်မွဲဂှ် က္တဵု တိုန်ရ၊ “ဆဍေံဝွံမွဲရ မဒှ်တြုံဟာ၊ ပိုဲညးဂမၠိုၚ်ဝွံဂှ် မဒှ်ဗြဴရောၚ်ဟာ” ဂးတုဲ ကြီုကြတုဲ က္တဵုဃဵု ကၠုၚ်ကဵုမၚ်ဗၠာဲရ။ (ဇ—၃၇၄။ အစွောံ။) = (လေးဆယ့်ကိုးယောက်ကုန်သော ခိုးသူတို့သည် ထ လတ်ကုန်၏။ “ဤသူတစ်ယောက်သည်သာ ယောကျာ်းလော၊ ငါတို့သည်ကား မိန်းမလော” ဟု ဆို၍ ကြုံးဝါးကုန်၍ လုလင်ဆီသို့ အတင်းဝင်လာကြကုန်၏။)')
,(1651,3,4,'ဟစ်ကြွေးကြုံးဝါးသည်။','“ယွံအနန်၊ မၞိဟ်မသုန်ကၠံ မစၚးညးတုဲ မနွံကဵုဗရုမသၠုၚ် ဗရုမဇၞော်မ္ဂးဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်၊ ပ္ဍဲဘဝမတုဲတေံကီုလေဝ် ဍေံစၚးညးတုဲ ဗရုမ သၠုၚ် ဗရုမဇၞော်ဂှ် ဍေံတအ်ကြီုဂအတ်တဴတုဲရ။” (ဇ—၁၈၃။ အစွောံ။) = “အာနန္ဒာ၊ ဤငါးရာ ကုန်သော စားကြွင်းစားတို့သည် ယခုအခါ­သာလျှင် စားကြွင်းကိုစားကုန်၍ ကျယ်လောင်သော အသံကို ပြုကုန်သည်မဟုတ်သေး၊ ရှေးဘဝ­လည်း စားကြွင်းကိုစားကုန်၍ ကျယ်လောင်သောအ သံကို ဟစ်ကြွေးဖူးကုန်သည်သာလျှင်တည်း။” || “ပ္ဍဲတ္ၚဲဝွံ ဗပေက်ကၠေံဍုၚ်တက္ကသဵုဝွံရ” ဂးတုဲ ဗဵု ပၞာန်ညးဗာရာဏသဳ ကြီုဂအတ်တဴအိုတ်ရ။ (ဇ—၂၂၉။ အစွောံ။) = “ဤယနေ့­ တက္ကသိုလ် ပြည်ကို ဖြိုခွဲပစ်အံ့” ဟု ဗာရာဏသီစစ်သည်ဗိုလ်ပါတို့သည် ဟစ်ကြွေးကြုံးဝါးကြကုန်၏။')
,(1652,3,4,'ကြွားဝါသည်။ မိမိကိုယ်ကို မိမိအမွှမ်းတင်သည်။','“ယွံခ မဳတံ၊ ခမဳဂှ် ဟီုကြီုစဇကုဂှ် ဆလၟုဟ်ဝွံဟွံသေၚ်၊ နူမတုဲအတိက်တေံလေဝ် ကြီုတဴတုဲရ” ကျာ်တြဲ ဂး။ (ဇ—၈ဝ။ အစွောံ။) = “ရဟန်းတို့၊ ဤရဟန်းသည် ယခုအခါ­သာလျှင် မိမိကိုယ်ကို အမွှမ်းတင်ကြွားဝါသည် မဟုတ်သေး၊ ရှေး­လည်း ကြွားဝါသည်သာလျှင်တည်း။”')
,(1653,3,4,'ကြုံးဝါးသည်။','“ပတွဵုနူဗောဓိသတ်မဒှ်မၞိဟ်ဗက် သရာဲညးဍုၚ်ဂှ် စိုတ်ဍေံတံမြောဟ် တိုန်တုဲ ‘လၟုဟ်ဝွံဂှ် ကောန်သၟိၚ်နာဲပိုဲက္တဵုဒှ်ရ။ ပိုဲတိတ်စၞေဟ်ကဵုသၟိၚ်ကောသလရးရ’ ဂးတုဲ ကြီုဇာ တဴအိုတ်ရ။” (ဇ—၁၅၆။ အစွောံ။) = “ဘုရားလောင်းအား ဖွားမြင်သည်နှင့် တိုင်းပြည်ရှိသူရဲသူ ခက်တို့သည် ရဲစိတ်ရဲမာန်တက်လာကာ ‘ယခုအခါ ငါတို့အရှင်၏သားတော်သည် ဖွားလေပြီ။ ငါတို့သည် ကောသလမင်းနှင့်တကွ စစ်ထိုးကုန်အံ့’ ဟုကြုံးဝါးကြကုန်၏။” || “ညာတ်အသဝ် ကွတ်တ္ၚဗောဓိသတ်တုဲ မှာဇန်ပုရိသာတ်ဂမၠိုၚ် ဟီုထိုၚ်သးတုဲ အိုဟ်တၟိုဟ်စိုတ်ဂှ်ဒှ်တုဲ တက်ကၞက် ကြီုဇာ တက်တဲသဝဲယာတ် ကဵုတဴသာဓုကာအိုတ်ရ။” = “အံ့ဖွယ်သရဲဖြစ်သော ဘုရားလောင်း၏ လေးအတတ်ကိုမြင်၍ လူထုပရိသတ်သည် ချီးမွမ်းကြကုန်၍ နှစ်သက်ရွှၚ်လန်းကုန်သည်ဖြစ်၍ လက်ပန်းပေါက်ခတ် ကြုံးဝါးကုန်လျက် လက်ခုပ်တီး၍၄င်း အဝတ်တို့ကိုဝှေ့ယမ်း၍၄င်း ကောင်း ချီးသြဘာပေးကြကုန်၏။”')
,(1654,3,16,'(န) အခက်အလက်။','ကြာဲပ္ကဴ = ပန်းခက်။')
,(1655,3,1,'ပါဠိအနက်ပြန်ဆိုခြင်း။',null)
,(1656,3,1,'(အမှုန့်စသည်) ဖြူးသည်။ ကြဲသည်။','“အိက်ကၞိဂှ် ဍေံကြုဲစုတ်ဒၞာဲဂှ်ရ။” (ဇ—၂၁၈။ အစွောံ။) = “ထွန်သွားတို့၏ ထားရာအရပ်­ ကြွက်တို့၏မစင်ကို ကြဲ၍ထား၏။” (ညောင်ကန်)')
,(1657,3,1,'လယ်ခေါၚ်ရန်း။',null)
,(1658,3,4,'နှမ်းဖြူးသည်။ (ဥပစာ) သူတစ်ပါးလုပ်၍ ပြီးစီးလုနီးတွင် လူတော်လူတတ်ဝင်လုပ်သည်။','“ညးတၞဟ်ကၠောန်ကွာၚ်စိန်တုဲ လ္ပဝါသနာကဵုကြုဲလ္ၚဴညိ။” = “သူများမုန့်လုပ်လို့ ကျက် ပြီးခါကျမှ နှမ်းဖြူးဝါသနာ မပါချင်စမ်းပါနှင့်။”')
,(1659,3,1,'၁။ ကြိုးကြာငှက်။','“ၜိုပ်ကီု ကြေဲကီု မြာ်ကီု—။” (ဇ—၂၁၄။ အစွောံ။) = “ဟၚ်္သာ သားတို့ကို၄င်း ကြိုးကြာသားတို့ကို၄င်း ဥဒေါင်းသားတို့ကို၄င်း—။” (ညောင်ကန်)')
,(1659,3,1,'၂။ ဝန်ချီ စက်။ ကရိန်း။ ကုန်တင်ကုန်ချမောင်း။',NULL)
,(1660,3,4,'လည်ပတ်သည်။ လျှောက်လည်သည်။','“အာကြေဝ်ကၠိုဟ်တ္ၚဲ” = “တစ်နေကုန် လျှောက်လည်နေသည်။” || ကြေဝ်သွံဗၞိက် = ရွက်၍ဖြစ်စေ ထမ်း၍ဖြစ်စေ ကုန်ရောင်းလှည့် လည်သည်။')
,(1661,3,4,'ဖြတ်ပစ်သည်။ ဖြတ်ညှပ်သည်။','“ဂတာံတုန် ညံၚ်ကဵုကတ်ကြေဝ်ဇမ္ကေက် မကြေဝ်ကၠေံတဝ်သွာဂှ်ကီု ကအ်ပံက်ကြေဝ်ဒကုတ်တုဲ ဂတာံဗၟာစှ်ေအာဍာ်ရ။” (ဇ—၃၈။ အစွောံ။) = “ဗုဇွန်သည် ကတ်ကြေးဖြင့် ကြာရိုးကိုဖြတ်သကဲ့သို့ ဗျိုင်း၏လည်ကိုဖြတ်၍ ရေသို့ဝင်၏။” (ညောင်ကန်) || “နကဵုဂတေက် မၞးတြေဝ်ဒကုတ်ဒြၚ်အဲတုဲ ကေတ်ဏာရ” ဗောဓိသတ်သၟိၚ်စိၚ်ဂး ကဵုလၟရ။ = “လွှဖြင့် ငါ၏အစွယ်ကိုဖြတ်၍ ယူသွားပါ” ဟု ဘုရားလောင်းဆင်မင်းသည် မုဆိုးအားပြော၏။')
,(1662,3,4,'ရေရွတ်သည်။ ညည်းညူသည်။ မြည်တမ်းသည်။','‘ကရေဝ်ကရောတ်’ ရှု။')
,(1663,3,4,'အပျိုလှည့်သည်။ ပိုးပန်းသည်။','“အာဒၟံၚ်ကၠိုဟ်တ္ၚဲ အာကြေဝ်ဒၟံၚ်ဝုတ်အလဵုရော။” = “တစ်နေကုန်လျှောက်သွားနေသည်မှာ ဘယ်မှာသွား၍ အပျိုပိုးပန်းနေသနည်း။”')
,(1664,3,4,'ညည်းညူသည်။ အသံတိုးတိုးဖြင့်ညည်းသည်။',null)
,(1665,3,4,'ကြုံးဝါးသည်။',null)
,(1666,3,4,'ကြုံးဝါးသည်။ ထောင်လွှားသည်။','“အစောံဗှ်ေနွံဂလိုၚ်လဵုတုဲ ဗှ်ေဂွံကြဵုဇာဒၟံၚ်ဂှ် ရော။” = “နင့်အစွမ်း ဘယ်လောက်များရှိလို့ နင်ထောင်လွှားကြုံးဝါးနေရပါသလဲ။”')
,(1667,3,1,'ကျောက်စရစ်။ ကျောက်စရစ်ခဲ။ (ပါဠိ—သက္ခရ)','ကြေဟ်ဗတဳ = သဲကျောက်စရစ်။ ကြေဟ်ဝါန် = ဂဝံကျောက်စရစ်။ “ထိုၚ်ကသာပ်ကဵုထိုၚ်ကောန်တြေဟ်ဂှ် လဝ်မွဲစွံရ။” (ဇ—၂၈၈။ အစွောံ။) = “အသပြာအိတ်နှင့် ကျောက်စရစ်အိတ်ကို အတူထား၏။”')
,(1668,3,1,'ရန်သူကိုထောင်သောဝါးချွန်။ ငြောင့်။','ထံၚ်ကြိုဟ် = ဝါးငြောင့်ထောင်သည်။')
,(1669,3,4,'ရူးသည်။ ရူးသွပ်သည်။ အရူးအမူးဖြစ်သည်။','ကြအ်ကဵုဗြဴ = မိန်းမနှင့်ရူးမူးသည်။ || ကြအ်ကဵုဒြပ် = ဥစ္စာရူးရူးသည်။ || ကြအ်ကဵုပွေၚ် = လောင်းကစားခြင်းဖြင့် ရူးမူးသည်။ || ကြအ်တဏှာ = တဏှာရူးရူးသည်။')
,(1670,3,4,'(ဆင်) မုန်ယိုသည်။ အမုန်ယစ်သည်။','‘ဗ္ၜူကၠေၚ်’၊ ‘တမြအ်ကၠေၚ်’ လည်းရှု။')
,(1671,3,4,'အရူးအမူးဖြစ်သည်။ အဆင်ခြင်ကင်းမဲ့စွာ ထိန်းမနိုင်သိမ်းမရဖြစ်သည်။','“ယွံတၠညး၊ ဗမၞးကွာ်ကၠုၚ်ကွာ်အာ တ္ၜူမာဲညံၚ်မတြံဂဗံအာ၊ မၞိဟ်ဂမၠိုၚ်လေဝ် ယာံကၠံၚ်တမ္ညဝ်ဒၟံၚ် မူဟိုတ်မွဲဒှ်ရောအဴ” ဂၞကျာ်သၟာန်။ (ဇ—၃၁၄။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ပုဏ္ဏားတို့သည် ရူးမူးဘိသကဲ့သို့ယစ်၍ လျှောက်လာလျှောက်သွားလျက်ရှိ၏။ လူတို့သည်လည်း ငိုကြွေးဆူညံ နေကြကုန်၏။ အဘယ်အကြောင်းကြောင့်ပါနည်း။”')
,(1672,3,4,'ရူးအသည်။',null)
,(1673,3,1,'မိုက်မဲသည်။ ရူးမိုက်သည်။',null)
,(1674,3,4,'ရူးမူးသည်။ အရူးအမူးဖြစ်သည်။','“သၟတ်ဗြဴဥမ္မာဒန္တဳဂှ် မၞုံလျးရုပ်သာ်ဂေါဝ် ဆာဲလောန်တုဲ — တြုံတံညာတ်မ္ဂး မတြံဗ္ၜူအာကီုမဒှ်ရ။” (ဇ—၅၂၇။ အစွောံ။) = “ဥမ္မာဒန္တီသ တို့သမီးသည် အလွန်တင့်တယ်သော ရုပ်အဆင်းရှိ၏။ ယောကျာ်းတကာတို့မြင်လျှင် အရူးအမူး ဖြစ်ကုန်၏။”')
,(1675,3,4,'စိတ်ဆိုးသည်။ အမျက်တချောင်းချောင်းထွက်သည်။ ဒေါသူပုန်ထသည်။',null)
,(1676,3,3,'၁။ ဝသော။ ဆူဖြိုးသော။','၂။ ဆိမ့်သောအရသာရှိသော။')
,(1677,3,3,'ဝဖီးသော။ ကိုယ်ထည်မာတင်းပြည့်ဖြိုးသော။',null)
,(1678,3,3,'ဦးခေါင်းသေးသွားအောင်ဝသော။',null)
,(1679,3,3,'ပြည့်ဖြိုးလှပသော။',null)
,(1680,3,3,'ဆူဖြိုးသော။ ဝဖိုင့်သော။',null)
,(1681,3,3,'ဝဖိုင့်ပုကွသော။',null)
,(1682,3,3,'ဝလုံးသော။',null)
,(1683,3,3,'ဝဖီးသော။ ဝဖိုင့်သော။',null)
,(1684,3,3,'ဆူဖြိုးသော။ ဝဖီးသော။','“ကၠဵုမွဲ ခမဳတံဝဳဇၞော်လဝ် ဟိုတ်မဂွံစပုၚ်တုဲ မၞုံဇကု မကြောံဗဗှ်ေတဴ။” (ဇ—၂၄၂။ အစွောံ။) = “ခွေးတစ်ကောင်ကို ရဟန်းတို့မွေးမြူထား၏။ ထို ခွေးသည် ထမင်းစားရသည်ဖြစ်၍ ဆူဖြိုးသောကိုယ်ရှိ၏။ || “ကၠဵုဂှ် ပဟိုတ်နူမဂွံစပုၚ်ကၞန်သ္ၚုတုဲ မၞုံဇကုမကြောံဗဗှ်ေတဴရောၚ်။” (ဇ—၂၄၂။ အစွောံ။)')
,(1685,3,3,'ဗိုက်ရွှဲ၍ဝသော။',null)
,(1686,3,16,'(နဝိ) ဝဖြိုးသော။ ဆူဖြိုးသော။','“မၞိဟ်ဂှ် စဒၟံၚ်သြောံဂန္ဓာသာလဳ စဒၟံၚ်သစ္ဆု ဗြာတ်က္ၜဴတံဂှ် ကြောအ်ဗေံဒၟံၚ်ရ။” (ဇ—၄၆၆။ အစွောံ။) = “ယောကျာ်းတယောက်သည် သလေးထမင်းကိုစားလျက် ကြံအစရှိသောသစ်သီးတို့ကိုခဲလျက် ဆူဖြိုးသောကိုယ်ရှိသည်ဖြစ်၍—။” (ညောင်ကန်)')
,(1687,3,3,'(အရသာ) အီဆိမ့်သော။',null)
,(1688,3,4,'‘ကြောအ်’ နှင့်အတူတူ။',null)
,(1689,3,1,'၁။ ကျား။ (ပါဠိ—ဗျဂ္ဃ)',NULL)
,(1689,3,1,'၂။ ကျားကစားနည်း။','ဝေၚ်ကၠ = ကျားထိုးသည်။ ကျားကစားသည်။')
,(1689,3,1,'၃။ ကျွန်းသစ်။',NULL)
,(1690,3,1,'ဝံပုလွေ။',null)
,(1691,3,1,'ဝံပုလွေ။ (ပါဠိ—ဣဳဟာမိဂ','ဤဟာမိဂ)')
,(1692,3,1,'ဝံပုလွေ။',null)
,(1693,3,16,'(န) ကြောင်ဝံပိုင့်။ ကောက်ညှင်းပေါင်းအနံ့ထွက်သည့် တောကြောင်။',null)
,(1694,3,1,'အောက်လမ်းပညာကြောင့် လူမှပြောင်းလဲဖြစ်လာသည်ဟုဆိုသည့်ကျား။ သမန်းကျား။ နတ်ကျား။',null)
,(1695,3,1,'ရှူးပျံ။ (ပါဠိ—တုလိယ','ပက္ခိဗိဠာလ) “ကၠသမြေၚ်ဂှ် လၟုဟ်ညး ကော်စ ဗၜိုဝ်တၠသၞေၚ်ရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ ဒု။ ၅၄၉။ စန္ဒိမာမဟာထေရ်။)')
,(1696,3,1,'ကျားသစ်။',null)
,(1697,3,1,'ကျားသစ်။',null)
,(1698,3,1,'ကျားသစ်ကြုတ်။',null)
,(1699,3,1,'ကျားသစ်နက်။',null)
,(1700,3,1,'ကျဗဟုံးရောဂါ။ (သူငယ်များတွင် ဖြစ်တတ်သော သူငယ်နာရောဂါ။)',null)
,(1701,3,6,'မတိုင်မှီ။ အလျင်။ ရှေ့က။','“ဍေံကၠုၚ်ကၠာအဲရ။” = “သူကျွန်တော့်အလျင်လာသည်။”')
,(1702,3,5,'ယခင်အခါက။',null)
,(1703,3,5,'မကြာသေးခင်က။','“ကၠာဂှ်ဏအ် ညးတအ်ကၠုၚ်ဝေၚ်သ္ၚိပိုဲ” = “မကြာသေးခင်က ကျွန်တော်တို့အိမ်ကို သူတို့လာလည်တယ်။”')
,(1704,3,5,'အလျင်အဦး။ အစအဦး။ ရှေးဦးစွာ။','“(သၟိၚ်ၜိုပ်ထဝ်ဝွံ) ဇိုၚ်ဒးစုတ်ပးဒၞက်ဂှ်တုဲ — — ဂစာန်ကၠာတဲဂှ် ပးမွဲဂြက်လုပ်တုဲ သၞာံထဝ်ဂှ် ဒကုတ်အာရ။ ဂစာန်ပ္ဍဲဒုတိယဂှ် ဖျုန်ဇိုၚ်ဒကုတ် အာရ။ ဂစာန်ပ္ဍဲတတိယဂှ် လတေၚ်ဒကုတ်တုဲ ပးဂှ် ဒွအ်ဒးဇုတ်ဇိုၚ်ဂှ်ရ။” (၅၅ဝ။ ဇ—၅၃၄။ ၉— ၂၄ဝ။ အစွောံ။) = “ရွှေဟၚ်္သာမင်းသည် ခြေ­ကျော့ကွင်းမိ၏၊ ရှေးဦးစွာရုန်းရာ­ ကြိုးကွင်း တစ်ခုညှပ်ဝင်၍ ရွှေအဆင်းရှိသောအရေသည် ပြတ်၏။ နှစ်ကြိမ်မြောက်ရုန်းရာ­ အသားသည် ပြတ်၏။ သုံးကြိမ်မြောက်ရုန်းရာ­ အကြောသည်ပြတ်၍ ကြိုးကွင်းသည် ခြေရိုး­ထိ၏။”')
,(1705,3,3,'လွန်လေပြီးသော။','(န) လွန်ခဲ့ပြီးသောအခါ။')
,(1706,3,16,'(နဝိ) အလျင်အဦးဖြစ်သော။ အလျင်စောစောဖြစ်သော။','“လိက်ပတ်မန်ဂှ် က္တဵုဒှ် ဇၞော်မောဝ်တဴ ကၠာပြဟ်နူလိက်ဗၟာ ဗၞတ်မွဲလ္ၚီသၞာံဒှ်ရောၚ် တၠပညာတအ်ဂးရ။” = “မွန်စာပေသည် မြန်မာစာပေထက် အနှစ်တစ်ထောင်လောက် အလျင်စော၍ ဖြစ်ပေါ်တိုးတက်ခဲ့သည်ဟု ပညာရှင်တို့ဆိုကြ၏။”')
,(1707,3,5,'အလျင်ဦးဆုံး။ လက်ဦးအစ။',null)
,(1708,3,4,'ညစ်ပေသည်။','(နဝိ) ညစ်ပေသော။')
,(1709,3,4,'နောက်ကျိသည်။ ညစ်ညမ်းသည်။','“ဍာ်ဒေါဝ်ကၟာကၠိကၠဲ သ္ကဲကၟာသ္ဇုၚ်” (ဇ—၇၇။ အစွောံ။) = “ကန်လယ်­ ရေသည်နောက်ကျိ၍ ကန်နံဘေး­ ရေသည်ကြည်လင်၏။”')
,(1710,3,4,'ညစ်ပေသည်။ နောက်ကျိသည်။ ညစ်ညမ်းသည်။',null)
,(1711,3,4,'နောက်ကျုသည်။ ညစ်ညမ်းသည်။',null)
,(1712,3,4,'ညစ်ပေသည်။ ညစ်နွမ်းသည်။',null)
,(1713,3,4,'ပေကျံသည်။ ပေရေသည်။',null)
,(1714,3,4,'ညစ်ပတ်ပေရေသည်။',null)
,(1715,3,4,'၁။ (မျက်စိ) မှုန်သည်။','“မတ်အဲကၠုဒၟံၚ် အဲရံၚ်ဟွံညာတ်ကၠးကၠးရ။” = “ငါ့မျက်စိမှုန် နေ၍ သဲသဲကွဲကွဲ မမြင်ရပါ။”')
,(1715,3,4,'၂။ (အရောင်) မှိန်သည်။','“တ္ၚဲကၠာန်လဝ်တုဲ အရံၚ်သာ်မိတ်ဂှ် ကၠုဒၟံၚ်ရ။” = “နေရောၚ်စားထား၍ ထိုအဝါရောင်သည် မှိန်နေသည်။”')
,(1716,3,1,'ကျွေးဥ။ (ဆန်စပါးရှားပါသော ဒေသများတွင် ဝမ်းစာအဖြစ်စားသုံးသည်။)',null)
,(1717,3,4,'ဆွံ့အသည်။ အသံမပီမသဖြစ်သည်။','“သတိက်ဒၟံၚ်ဟွံဂွံဝေန် မပဝေန်၊ ၜိုန်မဟွံသ္ဍိုၚ် ပ သ္ဍိုၚ်၊ ၜိုန်မဟွံကၠဴ ပကၠဴ၊ အၚ်္ဂပိသာ်ဝွံ အဲသ္ပအဓိဋ္ဌာန်ညိ” သၟတ်တေမဳချပ်။ (ဇ—တေမဳ။ အစွောံ။) = “အိပ်လျက် မဆွံ့ဘဲ ဆွံ့ဟန်ပြု၍၊ မပင်းဘဲ ပင်းဟန်ပြု၍၊ မဆွံ့အဘဲ ဆွံ့အဟန်ပြု၍၊ ဤ အၚ်္ဂါသုံးရပ်ကို အဓိဋ္ဌာန်ပြုအံ့” ဟု တေမိသတို့သားငယ်ကြံ၏။')
,(1718,3,1,'၊ ‘ကလဴ’ (ကြိ) လည်းရှု။','(န) ကမ္ဘာလိပ်ကြီးတစ်မျိုး။')
,(1719,3,16,'တစ်ရာ။','သြန်ၜါကၠံ = ငွေနှစ်ရာ။')
,(1719,3,1,'သွေးစုပ်သောကျွတ်ကောင်။','“ညံၚ်ညးက္ဍုဟ်ကၠံပကောတ်ဂှ်ဒှ်တုဲ။” (ဇ—၁၇၂။ အစွောံ။) = “သူတကာမုန်းသော ကျွတ်မျှော့ တို့ကဲ့သို့။”')
,(1720,3,4,'သီဟရာဇာပင်။ (ဆေးဖက်ဝင်)',null)
,(1721,3,4,'၁။ (အမြင်) ရှင်းလင်းသည်။ ထင်ရှားသည်။','“ရုပ်ဂှ် ညာတ်ကၠးဟာ။” = “ထိုရုပ်ကို ထင်ရှားစွာမြင်ရပါသလား။”')
,(1721,3,4,'၂။ (အကြား) ထင်ရှားသည်။ ပီသသည်။','“ရမျှာၚ်ဍေံတက် ကျာပ္ဍဲဖုၚ်ဂှ် အဲမိၚ်ဟွံကၠးရ။” = “ဖုန်းထဲမှာ သူ့စကားပြောသံကို ပီသစွာ ကျွန်တော်မကြားရပါ။”')
,(1721,3,4,'၃။ (ကျွန်)ဝယ်သည်။','“ဗြဴဝွံ ဍေံစကာဒၟံၚ်အဲ ဟွံဂွံဇူရောၚ်သွံ။ ပဗတ်ဍိက်ဍေံ ကၠးလဝ် ထဝ်လ္ၚီရောၚ်သွံ။” (ဇ—၁ဝ၆။ အစွောံ။) = “ဤမိန်းမသည် ငါ့ကိုမနားရအောင် ခိုင်းစေနေပါ လား။ ငါ့ကို ရွှေသားတစ်ထောင်ဖြင့် ဝယ်ထားသောသူ့ကျွန်သဖွယ် ပြုနေပါလား။”')
,(1722,3,5,'ချည်း။ သက်သက်။ အလွန်များစွာ။','“ပ္ဍဲဖျာတ္ၚဲဏအ် ဖျုန်ကကၠးကၠး။” = “ဒီက နေ့စျေးမှာ သားငါးသက်သက် အလွန်များလှစွာ၏။”')
,(1723,3,4,'ရှင်းလင်းထင်ရှားသည်။ ပီသသည်။','“(ၜိုပ်ထဝ်ဝွံ) ဟီုတိုန်ဝေါဟာမၞိဟ်ကၠးခ္ဍး မိပ်ပ္ဍဲကတောဝ်အဲတုဲ —— အဲသ္ဍိုက်မၠိုက်တုဲ (ဗလးကၠေံရ)” (လၟဂး။) (၅၅ဝ။ ဇ—၅၃၃။ ၉— ၂၂၇။ အစွောံ။) = “ဤရွှေဟၚ်္သာသည် လူ့ဘာသာစကားကို ပီသစွာပြောဆိုသည်မှာ ငါ၏နား ­ နာပျော်ဖွယ်ဖြစ်၍ ငါနှစ်သက်မြတ်နိုးသဖြင့် လွှတ်ပါအံ့” မုဆိုးဆို၏။')
,(1724,3,4,'ပီသသည်။','“ဍေံဟီုအရေဝ်မန်ကၠးခၠေဲ” = “သူမွန်စကားပြော အလွန်ပီသသည်။”')
,(1725,3,4,'ရှင်းလင်းသည်။ နားလည်သဘောပေါက်သည်။',null)
,(1726,3,4,'ရှင်းလင်းထင်ရှားသည်။',null)
,(1727,3,4,'၁။ (မျက်စိ) ကန်းသည်။','“မတ်ဍေံကၠက်ဒၟံၚ်မွဲဒိုဟ်ရ။” = “သူ့မျက်လုံးတစ်ဖက် ကန်းနေသည်။”')
,(1727,3,4,'၂။ အခေါင်းပိတ်သည်။','“ဒုန်ဏအ်ကၠက်ဒၟံၚ်ရ။” = “ဤဝါးသည် အခေါင်း ပိတ်နေသည်။”')
,(1727,3,4,'၃။ လုံအောင်ပိတ်သည်။ စေ့နေအောင်ပိတ်သည်။','“ကၟာတ်တရၚ်ကဵုကၠက်ညိ” = “တံခါးကို လုံအောင်ပိတ်ပါ။”')
,(1727,3,4,'၄။ ပြုန်းသည်။','“တၞံခတိုပ်ကၠောအ်တဵုလဝ်တံဂှ် ကၠက်အာအိုတ်ရ။” = “စိုက်ထားသော မြင်းခွါရွက်ပင်များသည် ပြုန်းကုန်ပြီ။”')
,(1728,3,1,'သပ်။ စို့။','ကၠာ်ဆု = သစ်သားသပ်။ ကၠာ်ပသဲ = သံသပ်။ စုတ်ကၠာ်၊ ပၠောပ်ကၠာ် = သပ်လျှိုသည်။ သပ်သွင်းသည်။')
,(1729,3,1,'ဝက်။','ကၠိက်ပၠိုၚ်ပၠိုၚ် = ဝက်ပေါက်။ ဝက်ပျို။ ကၠိက်ဗ္တာၚ် = ဝက်ဖြူ။')
,(1730,3,1,'တောဝက်။',null)
,(1731,3,1,'ဝက်သိုး။',null)
,(1732,3,4,'လက်ဖြင့်ပွတ်သည်။','ကၠေက်မတ် = မျက်စိကို လက်ဖြင့်ပွတ်သည်။ || “လမၠံလုပ် မတ်မ္ဂး လ္ပကၠေက်မတ်ညိ။” = “မျက်စိထဲအမှိုက်ဝင်လျှင် မျက်စိကိုမပွတ်ပါနှင့်။”')
,(1733,3,5,'ခဏခဏ။','“ကၠုၚ်မံၚ်ကၠံက်ကၠံက်” = “ခဏခဏလာနေသည်။”')
,(1734,3,1,'ကွမ်းအစ်ရှိထုံးဗူး။',null)
,(1735,3,4,'ညစ်ပေသည်။',null)
,(1736,3,4,'ညစ်ပတ်ပေရေသည်။ နောက်ကျိသည်။',null)
,(1737,3,4,'ရောယှက်သည်။ ကပြားဖြစ်သည်။',null)
,(1738,3,4,'အမှားရောနှော၍ ပျက်ယွင်းသည်။','“နူပထမ၊ မူလကိုပ်ကၠာ။ နွံပိုန်ဝါတ်စောန်၊ ကၠောန်ဒွက်လင်္ကာ။ ဂလာန်ကၠိုက်ကၠဟ်၊ ဒှ်တဴမှာရာ။ အဲလဟဵုညိ၊ တၟိမွဲဝါ။” (နရသာသန။ သဳလဝန္တထေရ်။) = “ဤစာလင်္ကာကို ဝါတ်စွန်ဆရာတော်က ရေးသားစီကုံးခဲ့ရာ ကာလရွေ့လျား ၍ အက္ခရာအမှားများ ရောနှောသဖြင့် စကားပျက်ယွင်းသွားသည်ကို အသစ်တစ်ဖန် အကျွန်ုပ် မွမ်းမံစီကုံးပါအံ့။”')
,(1739,3,4,'ညစ်ပေသည်။ ညစ်နွမ်းသည်။',null)
,(1740,3,1,'ညစ်ညမ်းမှု။ ညစ်ညူးမှု။ အညစ်အကြေး။','“ဘဒ္ဒဇိကုမာမိၚ်ဓဝ်တုဲ ကိလေသ ကၠိုက်လ္ၚေၚ် ပ္ဍဲသန္ထာန်ဇကုဂှ် သ္ဂုတ်ကၠေံရ၊ အာစိုပ်ဒဒှ်အရှန်ရ။” (ဇ—၂၆၄။ အစွောံ။) = “ဘဒ္ဒဇိသူဌေးသားသည် တရားတော်ကိုနာလျက်လျှင် မိမိ၏သန္တာန်မှ ခပ်သိမ်းသောကိလေသာ အညစ်အကြေးတို့ကိုဖြတ်၍ ရဟန္တာအဖြစ်သို့ရောက်၏။”')
,(1740,3,4,'ညစ်ညူး—ညစ်ညမ်း—ညစ်နွမ်းသည်။—စေသည်။','“ဍာ်မဟွံသ္အးမကၠိုက်လ္ၚေၚ်တဴဂှ် သုၚ်စုတ်မ္ဂး က္တဵုဒှ်ယဲမာန်ရ။” = “မသန့် ရှင်းသော ညစ်ညမ်းသောရေကို သောက်မိလျှင် ရောဂါဖြစ်ပွားနိုင်သည်။” || “သၟုဟ်ယက်မတိတ် ကၠုၚ် နူပၠံၚ်ယက်ရုၚ်စက်ဂမၠိုၚ်ဂှ် ကၠိုက်လ္ၚေၚ်ကၠေံဂၠံကျာရ။” = “စက်ရုံမီးခိုးခေါင်းတိုင်များမှ ထွက်လာသောမီးခိုးသည် လေထုကို ညစ်ညမ်းစေသည်။” || “(သၟိၚ်မြာ်ထဝ်ဂှ်) လုကဴထပှ်ကၠံသၞာံ တဏှာရာဂကိလေသ ၜိုန်သ္ၚိတ်လလံဒၟံၚ်ကီု — မိၚ်ရမျှာၚ်မာတုဂါမ်တုဲဗက် ပ္ဍဲချိုန်ဂှ်ရ ကိလေသ ကၠိုက်လ္ၚေၚ်တိုန်ဟေၚ်။” (ဇ—၁၅၉။ အစွောံ။) = “ရွှေဥဒေါင်းမင်းသည် အနှစ်ခုနစ်ရာတို့ပတ် လုံး တဏှာရာဂကိလေသာသည် ငြိမ်သက်စွာနေသော်လည်း မိန်းမအသံကိုကြားသည်နှင့် ထိုခ ဏ­ပင် ကိလေသာသည် ညစ်ညမ်းထကြွလာ၏။”')
,(1741,3,1,'လေထုညစ်ညမ်းမှု။',null)
,(1742,3,1,'ရေထုညစ်ညမ်းမှု။',null)
,(1743,3,1,'ထောင့်။ အမြှောင့်။','ပိကၠၚ် = သုံးထောင့်။ သုံးမြှောင့်။ || မသုန်ကၠၚ် = ငါးထောင့်။ ငါးမြှောင့်။ || “ကၠဂှ် သ္ၚဳရံၚ်ဝုတ်ဒိုဟ်ပန်ကၠၚ်တုဲ သွက်ဂွံရပ်ဒြာဲဂှ် တိတ်အာလ္ပာ်ဒိုဟ်ဗၟံက်ရ။” = “ကျားသည် အရပ်လေးမျက်နှာကို ကြည့်ရှုပြီးလျှင် သမင်အားဖမ်းရန် အရှေ့ဘက်သို့ ထွက်သွားသည်။”')
,(1743,3,4,'မိဘမဲ့သည်။ တစ်ဦးတည်းဖြစ်သည်။', '“ကောန်ၚာ်ဂှ် ကၠၚ်ဒၟံၚ်မိမရ။” = “ထိုကလေးသည် မိဘမဲ့ဖြစ်နေသည်။”')
,(1744,3,1,'သည်းခြေ။',null)
,(1745,3,4,'သည်းခြေငယ်သည်။ (ဥပစာ) အကြောက်လွယ်သည်။ အလွန်ကြောက် တတ်သည်။',null)
,(1746,3,4,'သည်းခြေအရည်ပျော်သည်။','(ဥပစာ) အလွန်ထိတ်လန့်တုန်လှုပ်သည်။')
,(1747,3,4,'သည်းခြေပျက်သည်။ စိတ်ဖောက်ပြန်သည်။ ရူးသွပ်သည်။',null)
,(1748,3,4,'အထီးကျန်သည်။ အဖော်မဲ့သည်။ အားကိုးရာမဲ့သည်။','“ယွံတၠဂုန်အဲ၊ အဲဍိက်ဒိုက်ကၠၚ်ကၠောန်သန်၊ သ္ဇက်စပဂယိုၚ်လမျီုဟွံမွဲ၊ အဲဍိက်သ္အာတ်ဒြၚ်တၠဂုန်ရ” လၟဂးကဵုသၟိၚ်စိၚ် ရ။ (ဇ—၇၂။ အစွောံ။) = “အရှင်၊ အကျွန်ုပ်သည် ဆင်းရဲ၏၊ အထီးကျန်၏။ အသက်မွေးခြင်းငှာ မတတ်နိုင်၍ အရှင်တို့ကို ဆင်စွယ်ပိုင်းကို တောင်းပါ၏။” “ယွံဗမၞး၊ တလအဲသိုက္ခမာ ရောၚ်သွံ။ မူဟိုတ်ဇကုမွဲ ကၠုၚ်ဂ္ဇအ်ဒၟံၚ်အကြာဂြိုပ် သီုမကၠၚ်ကၠောန်ဒၟံၚ်ဝွံရော။” (ဇ—၂၂ဝ။ အစွောံ။) = “ပုဏ္ဏား၊ သင်သည် နူညံ့သိမ်မွေ့သောသူဖြစ်၏။ အဘယ်ကြောင့် ဤတောသို့ဝင်၍ အထီးကျန်လျက် ထိုနေသနည်း။” || “ဂတာံထဝ်ဂှ် ရာန်သကိုတ်ရပ်လဝ်အဲတုဲ အဲမွဲမဒးကၠၚ် ကၠောန်တဴတုဲ အဲမဒးလရိုအ်ယာံတဴရောၚ်” စိၚ်ဂး။ (ဇ—၂၆၇။ အစွောံ။) = “ရွှေပုစွန်သည် ငါ့ အားနှိပ်စက်ဖမ်းထားသည်ဖြစ်၍ ငါသည် တစ်ကိုယ်တည်း အထီးကျန်၍ ငိုကြွေးနေရပါ၏” ဟု ဆင်သည်ဆို၏။ || “(ကောန်သေဋ္ဌဳဂှ် ဆဝေၚ်ဂြိုၚ်သုၚ်စဂှ် ဒြပ်တအ်ဂှ်အိုတ်အာတုဲ) ဒိုက်ဒိန်ကၠၚ် ကၠောန်အာရ။ ဒးသပိုၚ်ယာတ်ခမၞက် ကြိုၚ်တဴရ။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုသူဌေးသားသည် ပျော်ပါးသောက်စားခြင်းဖြင့်သာလျှင် ဥစ္စာတို့သည်ကုန်၍ ဆင်းရဲအထီးကျန်သည်ဖြစ်၍ ပု ဆိုးနွမ်းကိုဝတ်၍ သွားရ၏။” || တမၠၚ်ကမၠောန်’ (န) လည်းရှု။')
,(1749,3,4,'ငတ်ပြတ်သည်။',null)
,(1750,3,4,'ပူဆွေးသည်။ သောကဖြစ်သည်။',null)
,(1751,3,4,'စိတ်ညှိုးငယ်သည်။ ပူဆွေးသည်။',null)
,(1752,3,1,'ခင်ပုတ်ငှက်။','“ဂစေံကၠၚ်ဟိုက်မွဲဂှ် ဍေံလုပ်အောပ်ဒၟံၚ် ပ္ဍဲကၟဵုဒုန်။” (ဇ—၂၂၆။ အစွောံ။) = “တခုသောခင်ပုပ်ငှက်သည် ဝါးရုံချုံသို့ ဝင်၍ပုန်းအောင်း၏။” (ညောင်ကန်)')
,(1753,3,1,'အိုးကြီး၊ စရည်းအိုး။','ကၠာၚ်ဍာ် = ရေအိုးကြီး။ || ကၠာၚ်ပသဲ = သံဒယ်အိုး။ || ကၠာၚ်နရက် = ငရဲအိုးကြီး။')
,(1753,3,4,'ဆေးကြောသည်။ ကျင်းသည်။','“ကၠာၚ်ထောံထၟာဲညိ။”= “အိုးကို ဆေးကြောလိုက်ပါ။”')
,(1754,3,1,'အဝကျဉ်းပလုံး။',null)
,(1755,3,4,'ပလုတ်ကျင်းသည်။',null)
,(1756,3,4,'လာသည်။','‘တၠုၚ်’ (န) နှင့်နှိုင်းယှဉ်။')
,(1757,3,4,'လက်ပြန်ကြိုးတုပ်၍ ချည်နှောင်သည်။','“ညးကၠေၚ်ဏာကောန်တြုံသေဋ္ဌဳဂှ် ညး ဏာဂစိုတ်ရဂးတုဲ တမ္ညဝ်အာအလုံဍုၚ်တံဂှ်ရ။” (ဇ—၁၁၈။ အစွောံ။) = “ဥတ္တရသူဌေးသားကို လက်ပြန်ချည်၍ မင်းအာဏာကို ပြုကုန်အံ့ဟု ယူ၍သွားကြလေကုန်၏။ — မြို့အလုံးသည် အုတ်အုတ်ကျက်ကျက်ဖြစ်၏။” (ညောင်ကန်)')
,(1757,3,4,'၂။ ဗိုင်းငင်သည်။ ချည်ငင်သည်။ (= ကၠေၚ်တောဝ်)','“လဗြဴဗျုမွဲ — ကၠေၚ်ဒၟံၚ်တောဝ်။” (ဇ—၁၇၇။ အစွောံ။) = “မိန်းမအိုတစ်ယောက်သည် ချည်ငင်နေ၏။” (ညောင်ကန်မြန်မာမူ­ ‘ချည်ဝင့်’သည်ဟုလာသည်။)')
,(1758,3,1,'ဆီ။ အဆီ။','ကၠေၚ်လ္ၚဴ = နှမ်းဆီ။ ကၠေၚ်ရာဲ = မုန်ညင်းဆီ။ ကၠေၚ်ကၠိက် = ဝက်ဆီ။ ကၠေၚ်ဂယာၚ် = ကညၚ်ဆီ။ ကၠေၚ်ပၞာၚ်သေံ = ထင်းရူးဆီ။')
,(1758,3,4,'ဆီဖြင့်လိမ်းကျံသည်။ အဆီဝင်းသည်။ အဆီပြန်သည်။','“သၟန်ပါၚ်ကၠေၚ်ဒၟံၚ်သွံ၊ မူစလဝ်ရော။” = “နှုတ်ခမ်း တွင် အီဝင်းနေသည်။ ဘာစားထားပါသလဲ။”')
,(1759,3,1,'ဦးဏှောက်။',null)
,(1760,3,1,'ဆီကျက်။',null)
,(1761,3,1,'အုန်းဆီ။ ခေါင်းလိမ်းဆီ။',null)
,(1762,3,1,'အမဲဆီ။',null)
,(1763,3,1,'စားဆီ။',null)
,(1764,3,1,'နံ့သာဆီ။',null)
,(1765,3,4,'(ဆင်) မုန်ယိုသည်။ အမုန်ယစ်သည်။','“စိၚ်ကၠေၚ်စှ်ေမွဲ ဂ္ၚေၚ်ကၠုၚ်စိုပ် ပ္ဍဲဇရေၚ် အသုဘဂှ် ဍေံဂွံအမြာဲအသုဘဂှ်—။”(ဇ—၂၂၇။ အစွောံ။) = “အမုန်ယစ်သော ဆင်ပြောင်တစီးသည် ထိုအရပ်သို့လာလတ်၍ မစင်နံ့နံခြင်းကြောင့်—။” (ညောင်ကန်)')
,(1766,3,1,'မီးထွန်းဆီ။ ရေနံဆီ။',null)
,(1767,3,1,'ရေနံ။',null)
,(1768,3,1,'ဆီဦး။',null)
,(1769,3,1,'ခြၚ်ဆီ။ ရိုးတွင်းခြၚ်ဆီ။',null)
,(1770,3,4,'(ဆင်) မုန်ယိုသည်။',null)
,(1771,3,4,'လက်ပြန်ကြိုးတုပ်သည်။ ချုပ်နှောင်သည်။',null)
,(1772,3,1,'ဓာတ်ဆီ။',null)
,(1773,3,1,'ပရုတ်ဆီ။',null)
,(1774,3,1,'ဆီမန်း။',null)
,(1775,3,1,'ပျားဖယောင်း။ ဖယောင်းချက်။',null)
,(1776,3,1,'ထောပတ်။ ဟင်းရွက်ဆီ။ (ဂဟေေ)',null)
,(1777,3,1,'၁။ သွေးအရည်ကြည်။ သနံရည်။','၂။ အဆီခဲ။')
,(1778,3,1,'နံ့သာဆီ။ (စၚနေတဒေ ံိလ)','“ဂၞကျာ်ကြဴဇိုၚ်သဟာဲဂှ်တုဲ ဂၞကျာ်အာကေတ်နၚ် ကၠေၚ်မြမောဝ်တုဲ ကၠုၚ်လအက်ဂတာဇိုၚ်သဟာဲဂှ်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “မိဖုယားသည် လည်း (အဆွေခင်ပွန်း၏) ခြေတို့ကိုဆေး၍ နံ့သာဆီဖြင့်လိမ်း၏။” (ညောင်ကန်)')
,(1779,3,1,'ဆုပ်နယ်လိမ်းကျံရန်ဆီ။',null)
,(1780,3,1,'ထောပတ်သစ်။ (ပါဠိ—သပ္ပိ) (ဂဟေေ)','“ဗောဓိသတ်အာလမန်ညး ဂွံပုၚ်ပၟန်သီု ကၠေၚ်သွဟ်ရ။” (ဇ—၁၆၂။ အစွောံ။) = “ထိုဘုရားလောင်းသည် — ဆွမ်းဘိတ်ရာအရပ်သို့ သွား၍ ထောပတ်နှင့်ရောနှောအပ်သော ဃနာကိုရခဲ့၍—။” (ညောင်ကန်)')
,(1781,3,1,'သွေးအကြည်ရည်။ အဆီ။ ဆီကြည်။ (အသားမှဖြစ်ပေါ်သောအဆီ)(ပါဠိ—ဝသာ)','“ညံၚ်သၠိုၚ်ထဝ်မဂိုၚ်လဝ် ကၠေၚ်အယိၚ်ဇာဒိသိုၚ်ကီု။” (ဇ—တေမဳ။ အစွောံ။) = “ခြင်္သေ့ဆီကို ခံယူအပ်သောရွှေခွက်ကဲ့သို့။” || “ကၠေၚ်အယိၚ်ခဍာ် ဟွံမွဲမွဲလှ်ေရောၚ်။” (ဇ—၁၄ဝ။ အစွောံ။) = “ကျီးတို့အား အဆီမည်သည်မရှိ။” (ညောင်ကန်)')
,(1782,3,4,'ဗိုင်းငင်သည်၊ ချည်ငင်သည်၊ ချည်ဝင့်သည်။',null)
,(1783,3,1,'ကျောက်အၚ်ပင်။ ဖောက်ကြံ့ပင်။ ကြို့ပင်။',null)
,(1785,3,4,'ဆူညံသည်။ အုတ်အုတ်ကျက်ကျက်အသံဖြစ်စေသည်။','“ယွံတဳလမၞုံပိုန်၊ ပ္ဍဲဋ္ဌာန်မွဲမ ညန်ကဵုဘာဇေတဝန်ဂှ် ဋ္ဌာန်ဒမံၚ်တဳဂမၠိုၚ် ညးခၞံအိုတ်ရောၚ်အဴ။ ဟိုတ်ဂှ် ဗရုကၠံၚ်ဒၟံၚ်ရောၚ်အဴ” ထေအနန်ဂး။ (ဇ—၂၁၃။ အစွောံ။) = “အရှင်ဘုရား၊ ဇေတဝန်ကျောင်းတော်၏အနီး­ တိတ္ထိတို့ ၏နေရာကို ဆောက်လုပ်နေကုန်၏။ ထို့ကြောင့် အသံဆူညံနေခြင်းဖြစ်၏။” || “ခမဳဗၠာဲတံကီု သာမဏဳတံကီု ကောံဓရီုကၠံၚ်ဒၟံၚ်တုဲ—။” (ဇ—၁၅၈။ အစွောံ။) = “ရဟန်းငယ်တို့သည်၄င်း သာ မဏေတို့သည်၄င်း စုဝေးဆူညံလျက်နေကုန်၏။” || “ကၞုဟ်ဒတုံစှ်ေ ပ္ဍဲဒေါဝ်ပုရိသာတ်ဂမၠိုၚ်တုဲ ခဍအ်ကၞုဟ်ဂှ် ပြောပ်အာတုဲ ညးဂမၠိုၚ်ဟုပ်ကၠုၚ်ဗဵု ကၠံၚ်မံၚ်အိုတ်ရ။” (ဇ—၂၁၅။ အစွောံ။) = “လိပ်သည် ပရိသတ်များအလယ်­ ပြုတ်ကျ၍ လိပ်ခွံသည် ကွဲကြေလေသော် လူများစုအုံလာ ကြည့်ကြရာ အုတ်အုတ်ကျက်ကျက် ဆူညံလျက်ရှိ၏။”')
,(1786,3,4,'စုရုံးဟစ်ကြွေးသည်။ အုတ်အုတ်ကျက်ကျက်အသံပြုသည်။',null)
,(1787,3,1,'မျက်စိစွန်နာ။',null)
,(1788,3,4,'ဆူညံသည်။ စုရုံးဟစ်ကြွေးသည်။',null)
,(1789,3,4,'ဆူညံသည်။ မြည်ဟည်းသည်။',null)
,(1790,3,4,'လူစုလူဝေးဖြင့် ဆူညံသံပြုသည်။ အုတ်အော်သောင်းနင်းဖြစ်သည်။',null)
,(1791,3,4,'ခိုးသည်။',null)
,(1792,3,1,'အမိုးတွင် စုလစ်မွန်းချွန်ပါသောအဆောင်။ ပြာသာဒ်ဆောင်။','ကအ်ကၠတ် = ပြာ သာဒ်၏ဘုံအဆင့်။ တာဝင်္တံသာခန်း။ || နန်ကၠတ် = နန်းအိမ်။ နန်းပြာသာဒ်။ || သ္ၚိကၠတ် = နန်းဆောင်။ နန်းအိမ်။')
,(1793,3,16,'(န) ခန်းမဆောင်။',null)
,(1794,3,1,'ဘုံအဆင့်ပြာသာဒ်။',null)
,(1795,3,1,'လွှတ်တော်အဆောင်။',null)
,(1796,3,4,'လှည့်စားသည်။ လိမ်လည်သည်။','“ဗြဴမ္ဂးဂှ် ဍေံလေပ်ကၠတ်စိုတ်တၠသ္ၚိသန်။” (ဇ—၅၁၉။ အစွောံ။) = “မိန်းမမည်သည် လင်ယောကျာ်းကို လိမ်လည်လှည့်စားတတ်၏။”')
,(1797,3,4,'ခိုးကြည့်သည်။ ချောင်းမြောင်းသည်။',null)
,(1798,3,4,'တစ်ပါတည်း ခိုးယူသွားသည်။',null)
,(1799,3,4,'ပါးစပ်မှပြန်ထုတ်သည်။ ထွေးအန်ထုတ်သည်။','“(ကၠိက်ဂှ် ဂၜံကေတ်မၞိက်တုဲ ကလာၚ်အာညာတ်တ္ကအ်မွဲ စှ်ေတန်ဒၟံၚ်တုဲ) ကၠာတ်စွံလဝ်မၞိက်ဂှ်တုဲ။” (ဇ—၁၈၆။ အစွောံ။) = “ထိုဝက်သည် ပတ္တမြားကိုငုံလျက် ကောင်းကင်ခရီးဖြင့်ပျံသွားရာ ကျွန်းတစ်ခုကိုမြင်၍ ဆင်း၍နေကာ ထိုပတ္တမြားကို ပါးစပ်မှအန်ထုတ်၍ ချထား၏။” || “(သၟိၚ်စတဴသတ်ကြုက်ဂှ်) ဍေံကတၚ်အာညံၚ် ရှ်လှီကီုဒှ်တုဲ ၚိတ်ဏာဟွံမာန် သၟိၚ်ကၠာတ်ချဟ်ထောံကၠေံရ။” (ဇ—၁၈၆။ အစွောံ။) = “မင်းသည် ထိုသရက်သီးကိုစားရာ တမာ၏အရသာကဲ့သို့ ခါးသည်ဖြစ်၍ မမျိုချနိုင်ဘဲ ထွေးအန်ထုတ်ပစ်လိုက်၏။” || “သစဒြပ်ညး ဗစာရဏာဗိုန်တုဲစ မဟွံဒးကၠာတ်ပၠန်ဂှ်စညိ။” (သၠပတ်ဒ္ၚောဝ် သၜောံ) = “သူတစ်ပါးဥစ္စာကို စားသည်ရှိသော် သေချာစွာဆင်ခြင်ပြီးမှစားပါ။ စားပြီး၍ ပြန်မ ထွေးအန်ရသည်ကိုသာ စားပါ။” || “ညံၚ်ညးမှာသတိ စဒးဂျိ တီဂျိတုဲ ကၠာတ်ထောံကဵုပြဟ်ညိ။” (ဇ—၁၁၃။ အစွောံ။) = “သတိလစ်ဟင်း၍ အဆိပ်ကိုစားမိသောသူကဲ့သို့ အဆိပ်မှန်းသိရှိပြီး လျှင်မြန်စွာအန်ထုတ်ပစ်ပါလေ။”')
,(1800,3,3,'(တိရိစ္ဆာန်)ရိုင်းသော။ အကပ်မခံသော။ အန္တရာယ်ပြုတတ်သော။ ရန်လိုတတ်သော။','“ပြေၚ်ကၠာတ် ဂွံဒက်ဝါတ်ရ။” = “အနားအကပ်မခံသောကျွဲကို ချည်ရန်ခက်ခဲသည်။” || “ဍေံပတ်ဍာ်တှ်ဂၠဴပဏတ်ကၠာတ်မွဲဂှ်တုဲ ဂၠဴဂှ်ထၞိက်စုတ်တုဲ ဍေၚ်ဍာ်တှ်ဍေံ သီုမၞိဟ်ဂှ် လောတ် လောတမဝ်တဴကီု။” (ဇ—၅၂ဝ။ အစွောံ။) (ဂၠဴပဏတ် = နို့စားနွားမ) = “တခုသောနွားမစဉ်း လဲသည် နို့ညှစ်သောသူကို ခြေဖြင့်ကျောက်ကန်၍ နို့ရည်အိုးနှင့်တကွ လိမ့်၍လည်းစေ၏။” (ညောင်ကန်) (မြန်မာမူတွင် ‘နွားမစဉ်းလဲ’ ဟုသုံးထားသည်။')
,(1801,3,4,'အပင်ပေါက်သည်။','“ပ္ဍဲလတူတၟံလးဂှ် ဒြာတ်လဝ်မသြောံတုဲ ၜိုန်ဗြဲဗဂူဖျေံကီုလေဝ် သွက်မသြောံဂှ် ကၠုတ်တိုန်ဟွံမွဲရ။” (ဇ—၂၉၉။ အစွောံ။) = “ကျောက်ဖျာ­ မျိုးစေ့ကို အ ကယ်၍ပျိုးငြားအံ့၊ မိုဃ်းသည်လည်း အကယ်၍ရွာငြားအံ့၊ ထိုမျိုးစေ့သည် မပေါက်ရာသည်သ လျှင်ကတည်း။” (ညောင်ကန်)')
,(1802,3,4,'၁။ စေးကပ်သည်။ စေးထန်းသည်။','“ကၠေၚ်ပၠုဲဏအ် ကၠေတ်ကွေံကွေံရ။” = “ဤဖယောင်းချက်သည် အလွန်စေးကပ်သည်။” || “ခၟာဲကြဴဏအ် စကၠေတ်ခိုဟ်ကွေံရ။” = “ဤပိန်း ဥသည် စားရသည်မှာ အလွန်စေးကပ်သည်။”')
,(1802,3,4,'၂။ စိပ်သည်။ နီးကပ်သည်။','“တာန်လဝ်နဂှ် ကၠေတ်လောန်အာရ။” = “တောင်းရက်ထားသည်မှာ စိပ်လွန်းသည်။”')
,(1803,3,4,'ကပ်စေးနဲသည်။',null)
,(1804,3,1,'၁။ စပါးကြီးမြွေ။',NULL)
,(1804,3,1,'၂။ ဝှေးရောဂါ။ (= ယဲကၠန်)',null)
,(1805,3,1,'ဝှေးကျသည်။ အူကျသည်။ (ရောဂါ)',null)
,(1806,3,1,'ဝှေးတက်သည်။ (ရောဂါ)',null)
,(1807,3,1,'ငန်းစောင်း။ ကျိုင်းခေါင်းမြွေ။',null)
,(1808,3,4,'၁။ လျှာဖြင့်လျက်သည်။','ကၠာန်စ = လျှာဖြင့်လျက်စားသည်။ || “ချေံၜါဂှ် ညာတ်ညး သ္ကအ်တုဲ သ္ဍိုက်မၠိုက်အာညးသ္ကအ်တုဲ ဆုၚ်ညးသ္ကအ် ကၠာန်ညးသ္ကအ်—။” (ဇ—၁၅၈။ အစွောံ။) = “ထိုမြင်းနှစ်ကောင်တို့သည် အချင်းချင်းမြင်သည်ရှိသော် ချစ်နှစ်သက်ကုန်သည်ဖြစ်၍ အချင်းချင်း နမ်းကြကုန်၏၊ အချင်းချင်းလျက်ကြကုန်၏။” || “ဍာ်ကသှ်ဂှ် ချဟ်ထောံကၠေံတုဲဂှ် ကၠာန်ဍေံပၠန်ဂှ် ဟွံဒှ်ရ။” (ဇ—၃၁ဝ။ အစွောံ။) = “ထွေးပစ်ပြီးသောတံတွေးပေါက်ကို ပြန်လျက်ရန် မဖြစ်နိုင် တော့ပါ။”')
,(1808,3,4,'၂။ (မီး၊ နေစသည်) ဟပ်သည်။','“ပလောအ်မၞုံကဵုအရံၚ်ဂှ် စဲလဝ်ပ္ဍဲတ္ၚဲလအ်အာမ္ဂး တ္ၚဲကၠာန်ထောံတုဲ အရံၚ်ဗိုဟ်အာရောၚ်။” = “အရောင်ရှိသောအင်္ကျီကို နေတွင်ကြာကြာလှန်း ထားလျှင် နေရောၚ်ဟပ်၍ အရောင်မှိန်သွားလိမ့်မည်။”')
,(1809,3,4,'စိတ်ဆိုးအောင်ဆွသည်။ နောက်ပြောင်သည်။',null)
,(1810,3,4,'လုပ်သည်။ လုပ်ကိုင်သည်။','ကၠောန်ဓမာတ် = ပန်းထိမ်လုပ်သည်။ ပန်းထိမ်အလုပ်ဖြင့် အသက်မွေးသည်။ || ကၠောန်တမ္ၚာ = တံငါလုပ်သည်။ တံငါအလုပ်ဖြင့် အသက်မွေးသည်။ || ကၠောန်ကွာၚ် = မုန့်လုပ်သည်။ || ကၠောန်ကၠိက် = ဝက်လုပ်သည်။ ဝက်သတ်သည်။ ဝက်ပေါ်သည်။')
,(1810,3,1,'၁။ ကျွန်းငယ်။ ကျွန်းကလေး။', NULL)
,(1810,3,1,'၂။ (ကျောင်းအဆောက်အဦ၏) အမည်မဖော်နိုင်သေးသော) အစိတ်အပိုင်းတစ်ခု။', '“ဘာဒမံၚ်ကျာ်မှာဂေါတမဂှ် ဆကၠောန် ဘာဣတေံဂှ် ထဝ်ဒစိတ်ကိုတ်၊ ဗလးဘာဣတေံဂှ် ထဝ်ဒစိတ်ကိုတ်၊ ဘာဒယိုၚ်အတှ်လ္ၚီ ဂန္ဓကုဋဳ ဒမံၚ်ဣတေံ မူသ္ဇက်ဂးနွံရော။” (ဇ—၂၂၉။ အစွောံ။)')
,(1811,3,4,'အလုပ်လုပ်သည်။',null)
,(1812,3,4,'အလုပ်လုပ်သည်။','“တြုံတၠသ္ၚိဂှ် ကၠောန်ကလောန်ဂွံသြန် ပ္ဍဲမ္ၚးသ္ၚိတုဲ သမ္ဘာဂှ်တုန် ကၠောန်ကေၚ်ကာပ္ဍဲသ္ၚိရ။” = “လင်ယောကျာ်းသည် ငွေရသော ဥိမ် ပြင်ပအလုပ်ကိုလုပ်၍ ဇနီးမယားသည် အိမ်တွင်းမှုအလုပ်များကို လုပ်ကိုင်သည်။” || “ကာလဂှ်တုဲ ဗြဴဂှ် ဍေံက္တဵုကၠောန်ကာရ။” (ဇ—၁၃ဝ။ အစွောံ။) = “ထိုအခါ­ ထိုမိန်းမသည် အိပ်ရာမှထ၍ အလုပ်လုပ်၏။”')
,(1813,3,4,'ခြံလုပ်သည်။ ခြံအလုပ်ဖြင့် အသက်မွေးသည်။',null)
,(1814,3,4,'တောင်ယာလုပ်သည်။ တောင်ယာအလုပ်ဖြင့် အသက်မွေးသည်။',null)
,(1815,3,4,'လုပ်စားသည်။ လုပ်ကိုင်စားသောက်သည်။ အသက်မွေးဝမ်းကြောင်းသည်။','“မူညး တအ်ကၠောန်စဒၟံၚ်အိုတ်ရော။” = “သူတို့တွေ ဘာလုပ်ကိုင်စားသောက်နေကြပါသလဲ။”')
,(1816,3,4,'လုပ်ငန်းကိုၚ်ငန်း အဆင်ပြေသည်။ အသက်မွေးဝမ်းကြောင်းမှု ချောၚ်လည်သည်။',null)
,(1817,3,4,'အလုပ်အကိုင် အဆင်ပြေသည်။ စီးပွားတိုးတက်သည်။','“စသ္ကဂတဒိုဟ်ပလိုတ် ဒတိုန်တွိုန်ဟွံမွဲရ၊ ကၠောန်စဟွံတိုန်။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “အနောက်အရပ်သို့ မျက်နှာမူ ၍ တံပူစား(သွားတိုက်)သောသူအား စန်းထခြင်းမရှိ၊ လုပ်စား၍စီးပွားမဖြစ်။”')
,(1818,3,4,'လယ်လုပ်သည်။ လယ်အလုပ်ဖြင့် အသက်မွေးသည်။',null)
,(1819,3,4,'လုပ်ကိုင်သည်။ လုပ်ကျွေးသည်။ အလုပ်အကျွေးပြုသည်။','တ္ၚဲကၠောန်ၜိုတ် = အလှူအတန်းလုပ်သည့် အလုပ်အကိုင်နေ့။ || “ညးမကၠောန်ၜိုတ်ကဵုမိမဂှ် စုတိတုဲ ဂွံတိုန်စိုပ်ဍုၚ် သွဝ်ရ။” = “မိဘကို လုပ်ကျွေးပြုစုသောသူသည် သေလွန်သော် နတ်ပြည်သို့လားရ၏။” || “ယွံဂမှဳ၊ တၠအဲကၠောန်ၜိုတ်ကဵုခရှ်ဂှ် ဒှ်ကွေံဟာ” ကျာ်တြဲသၟာန်။ (ဇ—၄၈၄။ အစွောံ။) = “ရဟန်း၊ သင်သည် လူတို့ကို လုပ်ကျွေးသတတ်ဟူသည် မှန်သလော” ဟုမေးတော်မူ၍—။ (ညောင်ကန်) || “နနဲသာ်ဝွံ လုကဴပိပန်တ္ၚဲ ကၠောန်ၜိုတ်ကဵုသၟိၚ်တုဲ—။” (ဇ—၃ဝ၂။ အစွောံ။) = “ဤသို့ သုံးလေးရက် မင်းကိုလုပ်ကျွေး၍—။” (ညောင်ကန်)')
,(1820,3,4,'ကိုယ်လက်သုတ်သင်သည်။ ကျင်ကြီးကျင်ငယ်စွန့်သည်။','“ပ္ဍဲတ္ၚဲယးဂတ ဂှ် (ဣသိဂှ်) ကၠောန်ၜိုတ်ကဵုဇကုတုဲ (လုပ်အာဍုၚ် တၞဟ်နဂ္ၚေၚ်ပိဏ္ဍပါတ်ရ။)” (ဇ—၂၅၁။ အစွောံ။) = “(ရသေ့သည်) မိုးသောက်လတ်သော် ကိုယ်လက်သုတ်သင်၍ (ဆွမ်းခံရန်အလို့ငှာ မြို့သို့ဝင်သွား၏။)” (ညောင်ကန်) || “(ဗောဓိသတ်သေဋ္ဌဳ) တၞဟ်နကၠောန်ၜိုတ်ကဵုဇကု လောပ် အာဋ္ဌာန်မဗ္ဒန်—။” (ဇ—၁၂၅။ အစွောံ။) = “(ဘုရားလောင်းသူဌေးသည်) ကိုယ်လက်သုတ်သင် အံ့သောငှာ ဖုံးလွှမ်းရာအရပ်သို့ သွား၏။” (ညောင်ကန်)')
,(1821,3,4,'လိုက်ဖက်သော အစားအစာတစ်ခုခုဖြင့် တွဲ၍စားသောက်သည်။','ကၠပ်ကၞပ် = ငပိနှင့် တို့စရာကို တို့စားသည်။ || “ဖျုန်ကၠိက်ပရာၚ်ဏအ် ကၠပ်ကဵုသုရာခိုဟ်ကွေံရောၚ်။” = “ဤဝက်သားကင်ကို အရက်နှင့်မြည်းစားလျှင် အလွန်ကောင်းလိမ့်မည်။” || ‘ကၞပ်’ (န) လည်းရှု။')
,(1822,3,1,'၁။ ကျိုင်း။ (မင်းမှူးမတ်စသည်တို့၏ အဆောင်အယောၚ်တစ်မျိုး)','၂။ သေတ္တာငယ်။ ကြုပ်။')
,(1823,3,1,'ကျိုင်း။ (‘ကၠေပ်—၁’ နှင့်အတူတူ)','ကၠေပ်ထဝ်ဗာန်ထဝ် = ရွှေကျိုင်း။')
,(1824,3,1,'လျှော်တေပင်။ လျှော်ဖြူ။','ဇုက်ကၠီ = လျှော်ဖြူကြိုး။')
,(1825,3,1,'ပခြုပ်။ တံတင်း။ သေတ္တာ။','“ဒဒှ်သၟိၚ်နာ်မဍိုန်အာဂှ် လၟာဲတီတုဲ နဇုက်လရိတံဂှ် ဍေံခၞံကၠုံထဍအ်တုဲ ဍေံပြိုက်စုတ် ပ္ဍဲကၠုံထဍအ်ဂှ်ရ။” (ဇ—၅ဝ၆။ အစွောံ။) (ကၠုံ = ထဍအ်) = “ထိုအလမ္ပာယ်သည် နဂါးမင်းအားနည်းသည်ကိုသိ၍ နွယ်ပခြုပ်ကိုရက်ပြီးလျှင် ထိုပခြုပ်­ နဂါးမင်းကို ထည့်၏။”')
,(1826,3,1,'၁။ သိုက်စာ။', NULL)
,(1826,3,1,'၂။ ဉာဏ်နီဉာဏ်နက်။','ကၠေမ်ဂၠိုၚ် = ဉာဏ်များသည်။')
,(1827,3,4,'အိမ်ခေါင်ချုပ်သည်။','ကၠီုကလီု = ခေါၚ်ကိုချုပ်သည်။ ‘ကလီု’ (န) လည်းရှု။')
,(1828,3,4,'၁။ ဘာသာပြန်သည်။ စကားပြန်သည်။','“လိက်ဝတ္ထုဏအ် ကၠာဲလဝ်နူဘာသာဗၟာရ။” = “ဤဝတ္ထုကို မြန်မာဘာသာမှ ဘာသာပြန်ဆိုထားသည်။”')
,(1828,3,4,'၂။ အမျိုးရောစပ်သည်။ အမျိုး ပျက်သည်။ ကပြားဖြစ်သည်။ ဗန္ဓတ်ဖြစ်သည်။','“ကြုက်တဵုလဝ်ဂှ် သတ်ဍေံကၠာဲအိုတ်ရ။” = “စိုက်ထားသောသရက်ပင်၏ အသီးတို့သည် အမျိုးစပ်(အမျိုးပျက်)သွားပြီ။” (မူလအရည်အသွေး လျော့ကျပျက်စီးသည်။)')
,(1828,3,1,'ရွှေ့ပြောင်းတောင်ယာ။','ကၠာဲဂူ = ရွှေ့ပြောင်းစိုက်တောင်ယာ။')
,(1829,3,4,'(စာ)ဘာသာပြန်သည်။',null)
,(1830,3,4,'(စကား)ဘာသာပြန်သည်။',null)
,(1831,3,1,'၁။ တစ်နှစ်အတွင်းထွက်ရှိသောအခွန်။','“ကွာန်ဇၞော်မွဲဂှ် မၞုံကၠေဝ်ဍေံ မွဲမွဲသၞာံထဝ်မွဲ လက်ဂှ် (သၟိၚ်)ဇိုန်ကဵုသၟာဂလုံတုဲ—။” (ဇ—၉။ အစွောံ။) = “(မင်းသည်) ဆတ္တာသည်အား (တနှစ်လျှင်) အခွန်တစ်သိန်းထွက်သောရွာကို ဆုပေး၍—။” (ညောင်ကန်) || “ကွာန်ပန်ဒိုဟ်ဍုၚ်ဂှ် မနွံကၠေဝ်မွဲလက် (သၟိၚ်) ကဵုလာပ်ကုလမေန်ရ။” (ဇ—၁ဝ၇။ အစွောံ။) = “မြို့၏အရပ်လေးမျက် နှာရှိ အခွန်တစ်သိန်းထွက်သောရွာကို မင်းသည် ငဆွံ့အား ဆုလာဘ်အဖြစ်ပေး၏။”')
,(1831,3,1,'၂။ ဒယ် အိုး။','ကၠေဝ်တိ = မြေဒယ်အိုး။')
,(1832,3,4,'ပေကျံသည်။ ညစ်ပေသည်။','“ကောန်ၚာ်ဂှ် ဍေံဝေၚ်လဝ်တိတုဲ ကၠေဝ်ဒၟံၚ်အလုံဇကု ရ။” = “ထိုကလေးသည် မြေကြီးကစားထား၍ တစ်ကိုယ်လုံး ပေကျံနေသည်။”')
,(1833,3,1,'အခွန်ဘဏ္ဍာ။ ထွက်ရှိသောအခွန်။','“ယွံကောန်ဂၠုသ္ဍိုက်ယာဲ၊ နာဲစဴ စိုပ်သ္ၚိသၟိၚ်ဨကရာတ်ညးမပြဲတုဲ ညးဇိုန်ကဵုဍုၚ်ကွာန်၊ ကၠေဝ်ဖလှာ၊ အဟာရမပြဲတၞဟ်ဟ်သာ်၊ — —။” (ဇ—၄၅၅။ အစွောံ။) = “အမေ့ချစ်သား၊ သင်ချစ်သားသည် မြတ်သောမင်းဧကရာဇ်အိမ် နန်းသို့ရောက်၍ မြို့ရွာ၊ အခွန်ဘဏ္ဍာ၊ မြတ်သောအဟာရအမျိုးမျိုးကို သင်ချစ်သားအား ပေးကုန်လတ္တံ့။”')
,(1834,3,1,'၁။ ဘွဲ့ထူးဂုဏ်ထူး။ ရာထူးဋ္ဌာနန္တရ။','“ကြဴဝွံသၟိၚ်တီစုတ် ဝါသဘခတ္တိယာဝွံ ဒှ် ကောန်ဍိက်ဗြဴညးရောၚ်ဂးတုဲ သီုညးၜါမိကဵုကောန် သၟိၚ်ပဿိုန်ရုပ်ကၠေံကၠေဝ်မက်တုဲ ဖျေံထောံကၠေံ ရ။” (ဇ—၇။ အစွောံ။) = “မင်းသည်ကား ဝါသဘခတ္တိယာ၏ ကျွန်မအဖြစ်ကို နောက်မှသိ၍ သားအမိနှစ်ယောက်လုံးကို ရာထူးမှရုပ်၍ အရာမှချလိုက်သည်။”')
,(1834,3,1,'၂။ တစ်နှစ်အတွင်းထွက်ရှိ သောအခွန်။', '‘ကၠေဝ်—၁ နှင့်အတူတူ။ “ရသိတွံဓဝ်ဒၠောံဗ္တောန်သၟိၚ်တုဲ သၟိၚ်သ္ဇုၚ်သ္ဍိုက်တုဲ ကွာန်ဇၞော်မွဲဂှ် မွဲသၞာံကၠေဝ်မက်မွဲလက်ဂှ် သၟိၚ်ကဵုရသိရ။” (ဇ—၃၇၆။ အစွောံ။) = “(ဘုရားလောင်းရသေ့သည် မင်းအား တရားဟောဆုံးမသည်ရှိသော်) မင်းသည် ကြည်ညိုသောစိတ်ရှိသည်ဖြစ်၍ ဘုရားလောင်းအား အခွန်တစ်သိန်းထွက်သော ရွာမြတ်ကိုပေး၏။” (ညောင်ကန်)')
,(1835,3,4,'ငတ်မွတ်သည်။','“တိရစ္ဆာန်တံဂှ် ကၠောဝ်ဍာ်တုဲ ဍောၚ်ၜိုတ်တဴအိုတ်ရ။” (ဇ— ၁၂၄။ အစွောံ။) = “တိရစ္ဆာန်တို့သည် ရေငတ်မွတ်၍ ပင်ပန်းကုန်၏။” ‘ကၞောဝ်’ (န) လည်း ရှု။')
,(1836,3,4,'လျှိုသည်။','ကၠောဝ်တၞောဝ် = ယက္ကန်းယက်ဖောက်သီးရစ်သည်။ ဗိုင်းရစ်သည်။')
,(1837,3,4,'အစားငမ်းသည်။',null)
,(1838,3,4,'အစားအသောက်ငတ်သည်။ အစားအသောက်ငမ်းသည်။',null)
,(1839,3,4,'အစာငတ်သည်။',null)
,(1840,3,4,'ဆာလောင်ငတ်မွတ်သည်။ ချင်ခြင်းတပ်သည်။ (ဇဟန် = စၞ)','“ကောန်တြုံ သၟိၚ်ညာတ်လ္ၚဴဂှ်တုဲ ၜိုတ်ကေတ်လ္ၚဴမွဲသ္ကေံတုဲ စကၠေံရ။ ‘တြုံဂှ် ကၠောဝ်ဇဟန်ကွေံသွံ’ (လဗြဴတၠလ္ၚဴ ဂှ်) ချပ်တုဲ ကၞပ်ဒၟံၚ်ရ။” (ဇ—၂၅၂။ အစွောံ။) = “မင်းသားသည် နှမ်းဖြူတို့ကိုမြင်၍ နှမ်းတဆုပ်ကို ယူ၍စား၏။ နှမ်းပိုင်ရှင်မိန်းမအိုသည်ကား ‘ဤလုလင်သည် ချင်ခြင်းတပ်သောသူဖြစ်၏’ ဟု အောက်မေ့လျက် တစုံတခုမဆို။” (ညောင်ကန်)')
,(1841,3,4,'ရိက္ခာပြတ်လပ်သည်။',null)
,(1842,3,4,'ရေငတ်သည်။ ရေပြတ်လပ်သည်။',null)
,(1843,3,4,'ထမင်းငတ်သည်။','“ကလောန်ကမေတ်ဟွံမွဲမ္ဂး ကၠောဝ်ပုၚ်ရောၚ်။” = “အလုပ်အကိုင်မရှိလျှင် ထမင်းငတ်လိမ့်မည်။”')
,(1844,3,4,'ဆာလောၚ်ငတ်မွတ်သည်။',null)
,(1845,3,4,'ဆေးလိပ်ဆာသည်။ ဆေးလိပ်ငတ်သည်။',null)
,(1846,3,1,'ခွေး။',null)
,(1847,3,1,'ခွေးဝဲစား။',null)
,(1848,3,1,'နကျယ်ကောင်။',null)
,(1849,3,1,'၁။ ခွေးအ။',NULL)
,(1849,3,1,'၂။ ငရဲခွေးကြီး။','“သၟိၚ်နာလဳကေရဂှ် ဟိုတ်ဍေံမဒးဂြိုဟ်ကဵုဂမှဳဂှ်တုဲ ဍေံစှ်ေဒးနရက်တုဲ ကၠဵုကၠိၚ်တၟာစိၚ်ဗၠာဲ ဒြေပ်ခဵုကၠုၚ်တုဲ ကၠဵုတံဂှ် ကိတ်သ္ၚာဲစကြိပ်ပ်တုဲ ဂပိုတ်ဂပိုၚ်တုဲ လရိုအ်ယာံဂတေဝ်တဴရ။” (၅၅ဝ။ ဇ—၅၂၂။ ၈—၃၂၇/၃၂၈။ အစွောံ။) = “နာလီကေရမင်းသည် ရဟန်းတို့အား ပြစ်မှားခဲ့သောကြောင့် ငရဲကျခံရ၍ ဆင်ပျိုပမာဏရှိသော ငရဲခွေးကြီးများက အတင်းပြေးဝင်လာကာ တကျွတ်ကျွတ် ကိုက်ဝါးစားသည်ရှိသော် လူးလိမ့်လျက် အော်ဟစ်ငိုကြွေးနေရ၏။”')
,(1850,3,1,'သာမန်ခွေး။ အိမ်ခွေး။ (ပါဠိ—သောဏ)',null)
,(1851,3,1,'ဗိုလ်ခွေး။',null)
,(1852,3,1,'မြေခွေး။ (ပါဠိ—သိၚ်္ဂါလ)','ကၠဵုဂြိုပ်မွဲ ဍေံဂေတ်ကၠုၚ်အာ ညာတ်ပွကၞိတအ်ဂှ်တုဲ “အဲ ဝဵုကေတ်ကၞိဂမၠိုၚ်ဝွံတုဲ အဲရပ်စကၞိတအ်ဂှ်ညိ” ဍေံချပ်။ (ဇ—၁၂၈။ အစွောံ။) = တစ်ခုသောမြေ ခွေးသည် ထိုမှဤမှ လှည့်လည်သည်ရှိသော် ထိုကြွက်အပေါင်းကိုမြင်၍ “ကြွက်အပေါင်းတို့ကို လှည့်စား၍စားအံ့” ဟုကြံ၏။ (ညောင်ကန်) || ကၠဵုဂြိုပ်မွဲဂှ် တၞဟ်နဂၠာဲသ္ၚဳအဟာဂှ် တိတ်အာနူခြုံ ဇကုဂှ်တုဲ—။ (ဇ—၃၁၆။ အစွောံ။) = မြေခွေးသည်လည်း နေရာအရပ်မှထွက်၍ အစာရှာလတ် သော်—။ (ညောင်ကန်) (မှတ်ချက်။ ‘ကၠဵုတိ’ ဟုအချို့သူများ သုံးနှုန်းနေကြသည်မှာ မွန်ဝေါ ဟာရအမှန်မဟုတ်။ ‘ကၠဵုဂြိုပ်’သည်သာလျှင် မွန်ဝေါဟာရအမှန်ဖြစ်သည်။)')
,(1853,3,1,'ဗိုလ်ခွေး။',null)
,(1854,3,1,'ခွေးရူး။',null)
,(1855,3,4,'၁။ လွှင့်ပစ်သည်။ စွန့်ပစ်သည်။','“ခၟိက်ခၟောန်တအ်ဂှ် အာကၠဟ်ထောံ ပ္ဍဲနခၟိက်ညိ။” = “အမှိုက်သရိုက်များကို အမှိုက်ပုံးထဲ စွန့်ပစ်လိုက်ပါ။”')
,(1855,3,4,'၂။ ပစ်သည်။ ပစ်ခတ်သည်။','“ညးကၠဟ်ဏာကၠဵုကမၠတ်ဂှ် နကဵုမတၟအ်ရ။” = “ထိုခွေးသူခိုးကို ကျောက်ခဲလုံးနှင့် သူပစ်ခတ်လိုက်သည်။”')
,(1855,3,1,'ဖျဉ်းအိုး။ အဝကျယ်သောရေအိုး။','ကၠဟ်တိ = မြေဖျဉ်းအိုး။')
,(1856,3,4,'ပစ်ပေါက်သည်။ တိုက်ခိုက်သည်။','“ဍေံကၠဟ်ဇီုကၠဵုကမၠတ်ဂှ် နကဵုဍိုတ်ရ။” = “ထိုခွေးသူခိုးကို အုတ်ဖြင့် သူပစ်ပေါက်သည်။”')
,(1857,3,4,'လွှင့်ပစ်သည်။',null)
,(1858,3,4,'သိုင်းသည်။ သိုင်းခြုံသည်။ ရစ်သိုင်းသည်။','ကၠေဟ်ယာတ်စဏေဟ် = အပေါ်ရုံအဝတ်စအရှည်ကို သိုင်းခြုံသည်။')
,(1859,3,4,'ပေါက်သည်။','‘ကၠိုဟ်’ ရှု။')
,(1860,3,4,'၁။ ပေါက်သည်။','“ထၟာဲတိဏအ်ကၠိုဟ်အာရ။” = “ဤမြေအိုးပေါက်သွားပြီ။”')
,(1860,3,4,'၁။ ပေါက်သည်။','“(ခမဳဂှ်ပေါဟ်ဏာ) ဒွံဒးမတ်ၜိုပ်ကၠိုဟ်အာ သီုၜါဒိုဟ်ရ။” (ဇ—၁ဝ၇။ အစွောံ။) = “ထိုရဟန်းသည် ကျောက်စရစ်ဖြင့်ပစ်လိုက်ရာ ဟၚ်္သာ၏မျက်စိကိုထိမှန်၍ မျက်စိနှစ်ဖက်လုံးပေါက်သွား ၏။” || ‘ကၠောဟ်’ ဟုလည်း အနည်းအားဖြင့်တွေ့ရသည်။')
,(1860,3,4,'၂။ နားလည်သည်။ သဘောပေါက်သည်။', null)
,(1860,3,3,'လုံးလုံး။','ကၠိုဟ်တ္ၚဲ၊ ကၠိုဟ်တ္ၚဲထုတ် = တစ်နေ့လုံး။ တစ်နေကုန်။ ကၠိုဟ်ဗ္တံ၊ ကၠိုဟ်ဗ္တံထုတ် = တစ်ညပတ်လုံး။ ညလုံးပေါက်။ ကၠိုဟ်သၞာံ = တစ်နှစ်ပတ်လုံး။')
,(1861,3,4,'လူမှုရေးနားလည်သည်။ ယဉ်ကျေးလိမ္မာသည်။',null)
,(1862,3,4,'၁။ သဘောပေါက်နားလည်သည်။','ဟွံကၠိုဟ်ခၠၚ်ပရေၚ်မၞိဟ် = လူမှုရေးနားမလည်။ || ဓဝ်ကၠိုဟ်ခၠၚ် = နားလည်မှု။')
,(1862,3,4,'၂။ (ကျမ်းဂန်စာပေတွင်) ကြေညက်သည်။ နှံ့စပ်သိမြင်သည်။','ညးမကၠိုဟ်ခၠၚ်ပြကိုဟ်ကၞပ် = စာပေကျမ်းဂန်တတ်ကျွမ်းသူ။')
,(1862,3,4,'၃။ ထိုးထွင်း၍သိနိုင်စွမ်းသည်။','“ကျာ်နာဲပိုဲဝွံ — မနွံပညာမစာ်စ္ဍးနူပွမသၠေဟ်ပၟာ ဂြၚ်တီကၠိုဟ်ခၠၚ်ရောၚ်။” (ဇ—၂၁၄။ အစွောံ။) = “မြတ်စွာဘုရားသည် ယုံမှားခြင်းမှကင်းဝေးသော ထိုးထွင်းသိမြင်သောပညာရှိ၏။”')
,(1863,3,4,'သဘောပေါက်နားလည်သည်။',null)
,(1864,3,4,'ထုတ်ချင်းခပ်ပေါက်သည်။ ထုတ်ချင်းပေါက်ဖြစ်သည်။ ဖောက်ထွက်ကျော်လွန်သည်။','“မၚ်ဗၠာဲဗလးဏာကံဂျိဂှ် ဒးနူကၟံၚ် လုပ်ကလှၚ်ကၠေံဂြိုဟ်ဍေံတုဲ ကၠိုဟ်သာတ်တိတ်အာ လပါ်ဗတတေံတုဲ စိၚ်ဂှ်လောတ်ဒၟံၚ်ဒၞာဲဂှ်ရ။” (ဇ—၃၇၄။ အစွောံ။) = “လုလင်သည် ထိုဆင်အား ဆိပ်လူးမြှားဖြင့် ပစ်လွှတ်လိုက်ရာ ဦးကင်းမှထိမှန်၍ အသည်းကိုဖောက်ထွင်း၍ အမြီးဘက်သို့ တိုင် ထုတ်ချင်းခပ်ပေါက်ထွက်၍ ထိုဆင်သည် ထိုနေရာ­လျှင် လဲကျသွား၏။” || “(ဗောဓိ သတ်သၟာတ္ၚဒယှ်) မၞုံအစောံသၞာံဇမ်ကဟ်ကၠံထပ် ပန်ကၠိုဟ်သာတ်အာ။” (ဇ—၁၈၁။ အစွောံ။) = “လေးသမားကျော်ဖြစ်သော ဘုရားလောင်းသည် သားရေခြောက်ခုနစ်ထပ်တို့ကို ထုတ်ချင်းထွင်းအောင် ပစ်နိုင်စွမ်းရှိ၏။”')
,(1865,3,1,'ခြံ။ ဥယျာဉ်။','ကၠအ်ပ္ကဴ = ပန်းခြံ။ ပန်းဥယျာဉ်။ || ကၠအ်သတ်ဗြဴ = အုန်းခြံ။ || ကၠအ်ဇၜိုတ် = ရော်ဘာခြံ။')
,(1866,3,1,'ဥယျာဉ်ခြံမြေ။',null)
,(1867,3,4,'၁။ ပျောက်သည်။','“သြန်အဲကၠေံအာစှ်ရ။” = “ကျွန်တော့်ငွေတစ်ဆယ် ကျပ် ပျောက်သွားသည်။”')
,(1867,3,4,'၂။ ထွက်ခွါသည်။','“ကၠေအ်နူဍုၚ်ရေဝ်တုဲ ဆက်တရဴအာစိုပ်ဍုၚ်ဓဝဲါရ။” = “ရေးမြို့မှထွက်ခွါပြီးလျှင် ခရီးဆက်ခဲ့ရာ ထားဝယ်မြို့သို့ ရောက်ရှိသွားသည်။”')
,(1868,3,9,'၁။ ကြိယာနောက်ဆက်အဖြစ် ပြုမှုဖြစ်မှုပြီးပြတ်ခြင်းကို ဖော်ပြသောစကားလုံး။','ထောံကၠေံလွဳ = လုံ့လလျှော့သည်။ လုံ့လကို လျှော့ပစ်သည်။ || “ပၞောဝ်ဒဂိုတ်ဂမၠိုၚ် ဒဂိုတ်မွဲမဇြေဟ်ဇြာဲတဴဂှ် ညးရုဲပါဲထောံကၠေံ ညးဟွံရာန်ရ။” = “ငုံးများအနက် တစ်ခုသောပိန်လှီ သောငုံးကို သူတကာတို့မဝယ်ဘဲ ရွေးဖယ် (ပစ်)လိုက်သည်။”')
,(1868,3,9,'၂။ တိုက်ရိုက်ကံပုဒ်မလိုသော သုဒ္ဓကြိယာကို ကာရိုက်ကြိယာအဖြစ် သုံးလိုသောအခါ ဖြည့်စွက်ပေးသော ကြိယာနောက်ဆက် စကားလုံး။','“သၟတ်ဗြဴဂှ် မၞုံရမ်သာၚ်မမိပ်မဇိပ်ဂၠိပ် မဗ္ၜူကၠေံစိုတ်အဲရ။” = “ထိုမိန်းမပျိုသည် သာယာနာပျော်ဖွယ်သောအသံရှိ၍ ငါ၏စိတ်ကို မိန်းမူးစေ၏။” || “(တၞဟ်နဗက်ဗ္ဒဴကၠေံဂစေံဂမၠိုၚ် သၟိၚ်နာ်)ကတဴကနှံကၠေံဍာ်ရ။” (ဇ—၁၃၃။ အစွောံ။) = “ငှက်များအား မောင်းထုတ်ပစ်ရန် နဂါးမင်းသည် ရေကို ကျိုက်ကျိုက်ဆူစေ၏။”')
,(1869,3,4,'ဆိတ်သုန်းပျောက်ကွယ်သည်။',null)
,(1870,3,4,'ပျောက်ဆုံးသည်။',null)
,(1871,3,4,'ကြိုးစားသည်။ စိတ်ပါလက်ပါ ဂရုတစိုက်ပြုလုပ်သည်။ အားထုတ်သည်။','“(ဗောဓိသတ်)ကၠေံစိုတ်ကတ် လုကဴဗၞတ်မွဲဗ္တံ ဒဵုကဵုတ္ၚဲယး ဗိုတ်ပိကီု မ္ၚဵုစိၚ်ကီု ကတ်ဂွံ တိုန်ပါၚ်စိုတ်—။” (ဇ—၁၆၃။ အစွောံ။) = “ဘုရားလောင်းသည် တစ်ညအတွင်း မိုးလင်းသည် အထိ ကြိုးစား၍သင်ယူရာ ဗေဒၚ်သုံးပုံကို၄င်း ဆင်မၚ်္ဂလာအတတ်ကို၄င်း နှုတ်တက်ရ၏။ || “ဣသိဂှ် ကၠေံစိုတ်အိုတ်ဇိုၚ်တဲတုဲ သိုၚ်ခၞံလဝ်ပဏ္ဏသာဂှ်ရ။” = “ထိုရသေ့သည် ခြေကုန်လက်ပန်းကျ အောင် အပင်ပန်းခံ၍ ထိုကျောင်းသၚ်္ခမ်းကို ကြိုးစား၍ ဆောက်လုပ်ထားရ၏။” || “ယွံမၞးတံညးဂမၠိုၚ်၊ မၞးတံကၠေံစိုတ်ဗတိုက်ဇၞးတုဲ ထဝ်သြန်တံဝွံ အဲဇိုန်ကဵုမၞးတံရ။” (ဇ—၂၈၄။ အစွောံ။) = “အချင်းတို့၊ သင်တို့ကြိုးစားတိုက်ကြကုန်လော့။ အောင်နိုင်ပါက ဤရွှေငွေတို့ကို သင်တို့အား ငါပေးအံ့။”')
,(1872,3,4,'ကြိုးစားအားထုတ်သည်။ လုံ့လစိုက်သည်။',null)
,(1873,3,4,'ပျောက်ကွယ်သည်။',null)
,(1874,3,4,'ပျောက်ဆုံးသည်။','“မၚ်ဗၠာဲကောန်ကလော်ဗြဴဂှ်တုန် ပ္ဍဲကြဴဝွံ ဟိုတ် မာဲအာတုဲ ရိုဟ်ဆုဂှ် ကၠေံလေၚ်အာရ။” (၅၅ဝ။ ဇ—၅၁၃။ ၈—၁၅၉။ အစွောံ။) = “ဘီးလူးမ သားသည်လည်း နောက်အဘို့­ မေ့လျော့သဖြင့် ထိုဆေးမြစ်(သည်) (ပျောက်ဆုံးသွား၏။)” (၅၅ဝ။ စတု—၆၂၇။ ညောင်ကန်။)')
,(1875,3,4,'အသက်စွန့်သည်။ အသက်ကိုပဓါနမထားပဲ ပြုလုပ်သည်။','“ပ္ဍဲ မုက်ပၞာန်ဋ္ဌာန်စၞေဟ် ဗ္တိုက်ကဵုသတြုမ္ဂး ကၠေံလမျီုတုဲ ဒးဗ္တိုက်စၞေဟ်ညံၚ်ဇၞးရ။” = “စစ်မျက်နှာတွင် ရန်သူနှင့်စစ်တိုက်လျှင် အသက်ကို ပဓါနမထားဘဲ အနိုင်ရအောင်တိုက်ရမည်။” || “(တြုံ ဒိုက်ဂတ်ဂှ် တၞဟ်နကၠတ်ယာတ်ချီုသၟိၚ်) သ္ဂာဗ္တံ ကၠေံလမျီုတိတ်နူဍုၚ် စိုပ်တၞံယာတ်သာ်ချီုသၟိၚ်ရ။” (ဇ—၁၄၇။ အစွောံ။) = “(သူဆင်းရဲယောကျာ်းသည် မင်း၏ဝတ်ပန်းကိုခိုးရန်) ညဉ့်အဘို့­ အသက်ကိုစွန့်၍ မြို့မှထွက်၍ မင်း၏ဝတ်ပန်းခင်းသို့သွား၏။” (ညောင်ကန်)')
,(1876,3,4,'၁။ ကူးသည်။ ဖြတ်ကူးသည်။','“နကဵုဂၠုၚ် ညးကၠောံအာသြၚ်လ္ပာ်တေံရ။” = “လှေဖြင့် ဟိုဘက်ကမ်းသို့ သူဖြတ်ကူးသွားသည်။” || “နူဂှ် ကၠောံအာက္ဍိုပ်ဒဵုမွဲလ္ပာ်တေံတုဲ —။” (ဇ— ၁၉၃။ အစွောံ။) = “ထိုနေရာမှ အခြားတစ်ဖက်ရှိ တောင်ထိပ်ဆီသို့ ကူးသွား ၏။” || ကၠောံဒဒန် = တံတားကူးသည်။')
,(1876,3,4,'၂။ ကူးစက်သည်။','ယဲကၠောံ = ရောဂါကူးစက်သည်။')
,(1877,3,3,'သာယာနာပျော်ဖွယ်သော(အသံ)။','‘မၞုံရမျှာၚ်မကၠောံဂပဝ်မိပ်။’ (ဇ—၂၉၄။ အစွောံ။) = ‘သာယာနာပျော်ဖွယ်သောအသံရှိသော။’')
,(1878,3,4,'ကူးစက်သည်။','ယဲကၠောံစပ် = ရောဂါကူးစက်သည်။')
,(1879,3,4,'ခင်မင်ရင်းနှီးသည်။ အကျွမ်းဝင်သည်။ ကူးလူးဆက်ဆံသည်။','“ဗၠာဲသၟိၚ်ဂှ် ကၠောံသ္ဍအာကဵုဂၞကျာ် လှိၚ်တဴမွဲသၞာရ။” (ဇ—၁၂ဝ။ အစွောံ။) = “ထိုမင်းချင်းယောကျာ်းသည် မိဖုယားနှင့် ချစ်ကျွမ်းဝင်သွားကာ အတူတကွ မွေ့လျော်အိပ်စက်၏။”')
,(1880,3,4,'ကူးစက်သည်။ ကူးစက်ပျံ့နှံ့သည်။','“ယဲအေအာၚ်ဒဳအေတ်ဂှ် ကၠောံသၞာန်ဒၟံၚ် အလုံလိုက်ဂၠးတိရ။” = “အေအိုင်ဒီအက်ရောဂါသည် တစ်ကမ္ဘာလုံးကို ကူးစက် ပျံ့နှံ့နေသည်။”')
,(1881,3,4,'(အတတ်ပညာ) အပြီးသို့ရောက်သည်။ တစ်ဘက်ကမ်းခပ် တတ်မြောက်သည်။','“(ဗောဓိသတ်) ဒှ်အာယုက်စှ်တြဴသၞာံ ကၠောံသြၚ်ကွတ်အိုဿီု—။” (ဇ—၄ဝ။ အစွောံ။) = “(ဘုရားလောင်းသည်) တဆယ့်ခြောက်နှစ်ရှိသောကာလ­လျှင် ခပ်သိမ်းသောအတတ်­ အပြီးသို့ရောက်၏။” (ညောင်ကန်) || “ကောန်သၟိၚ်ဗြဟ္မဒတ္တကုမာဂှ် ပေၚ်အာယုက်စှ်တြဴ သၞာံတုဲ အာကတ်ဍုၚ်တက္ကသဵု ကွတ်ဗိုတ်ပိကၠောံသၚ်ရ။” (ဇ—၅ဝ။ အစွောံ။) = “(ဗြဟ္မဒတ္တ ကုမာမင်းသား) ဘုရားလောင်းသည် တဆယ့်ခြောက်နှစ် အရွယ်ရှိလတ်သော် တက္ကသိုလ်ပြည်­ အတတ်ကိုသၚ်၍ ဗေဒၚ်သုံးပုံတို့၏ ကမ်းတဘက်သို့ရောက်၍—။” (ညောင်ကန်) || “(ဗောဓိသတ်) ပ္ၚောအ်တက္ကသဵု ကၠောံသြၚ်ကွတ်အိုဿီုတုဲ ကလေၚ်စဴဍုၚ်ဗာရာဏသဳ။” (ဇ—၁၅ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် တက္ကသိုလ်ပြည်သို့ အတတ်သၚ်သွား၍ ခပ်သိမ်းသောအတတ် တို့ကို တစ်ဖက်ကမ်းခပ်တတ်ပြီးလျှင် ဗာရာဏသီပြည်သို့ ပြန်လာ၏။” || “ဗိုတ်ပိကၠောံသြၚ် ကွတ်တြုံစှ်ဒစာံသာ်လေပ်အိုတ်။” (ဇ—၂၈၇။ အစွောံ။) = “ဗေဒၚ်သုံးပုံတို့­ တစ်ဖက်ကမ်းခပ် ၍ တဆယ့်ရှစ်ရပ်သော ယောကျာ်းတို့ကို တတ်မြောက်၏။”')
,(1882,3,16,'ပုကွသည်။—သော။','“(ထေရ်ဂှ်) မၞုံဇကုသၠုၚ်ဒတဴမသွတ်လောန် မၞုံဇကုမသဝ်ကွ တဴ။” (ဇ—၂ဝ၂။ အစွောံ။) = “ထိုမထေရ်သည် ငယ်သောကိုယ်အရပ်အမောင်းရှိ၏။ ပုကွ သောကိုယ်ရှိ၏။”')
,(1883,3,3,'ပုကွသေးငယ်သော။','“(ထေရ်ဝွံ) မူရဴပွမွဲမဒးပလဝ်တုဲ မဒးကွသွတ်လောန်ရော အဴ” ခမဳဂမၠိုၚ်သၟာန်ကျာ်။ (ဇ—၂ဝ၂။ အစွောံ။) = “ဤမထေရ်သည် အဘယ်မကောင်းမှုကို ပြု ထားသဖြင့် ပုကွသေးငယ်ရပါသနည်း။”')
,(1884,3,3,'ပုပု။ ကွကွ။',null)
,(1885,3,1,'စာဆိုတော်။ ကဝိ။ ပညာရှိ။','အ္စာကဝိ = စာဆိုတော်။')
,(1886,3,1,'လှည်း။ ရထား။ ယာဉ်။','(စည်း) နွားလှည်းစသည်ကို ရေတွက်ရာတွင် သုံးသောစ ကားလုံး။ လှည်းတစီးတိုက်။ (၂၅)တင်းနှင့်ညီမျှသော အခြၚ်အတွယ်။ || သြောအ်ၜါကွဳ = လှည်းနှစ်စီးတိုက်စပါး။ တင်း(၅ဝ)။')
,(1887,3,1,'မြင်းလှည်း။ မြင်းရထား။',null)
,(1888,3,1,'နွားးလှည်း။',null)
,(1889,3,1,'မော်တော်ကား။',null)
,(1890,3,1,'နတ်ရထား။ နတ်လှည်းယာဉ်။',null)
,(1891,3,1,'အမိုးပါသောလှည်း။',null)
,(1892,3,1,'လက်တွန်းလှည်း။',null)
,(1893,3,1,'ရထားပေါင်းချုပ်။ လှည်းပေါင်းချုပ်။ အမိုးအကာပါသောလှည်း။',null)
,(1894,3,1,'မီးရထား။',null)
,(1895,3,1,'ဖုတ်သွင်းရထား။ ဖုဿရထား။',null)
,(1896,3,1,'လှည်းယာဉ်။ ယာဉ်ရထား။',null)
,(1897,3,1,'စက်ဘီး။',null)
,(1898,3,1,'မော်တော်ဆိုင်ကယ်။',null)
,(1899,3,1,'တဆေး။ ကစော်ဖောက်ဆေး။',null)
,(1900,3,1,'ဥသြငှက်။',null)
,(1901,3,1,'တပည့်။',null)
,(1902,3,1,'ဆရာ့ဝေယျာဝစ္စကို ဆောင်ရွက်ပေးသောတပည့်။','“မှာထေရ်အာနန်ဂှ် ဒှ်ကွး ကမၠောန်ကျာ်တြဲရ။” = “အရှင်အာနန္ဒာမထေရ်သည် မြတ်စွာဘုရား၏ ဝတ်ကြီးဝတ်ငယ်တို့ကို ဖြည့်ဆည်းလုပ်ကိုင်ပေးသော အနီးကပ်တပည့်ရင်းဖြစ်သည်။”')
,(1903,3,1,'တပည့်တပန်း။','“မတီဂုန်ပရဲဍိက်သ္ကံသွးကွးဂနးဂှ် ဒှ်မတီဒိုဟ်အသၟဝ်ရ။” (ဇ—၉၆။ အစွောံ။) = “ကျေးကျွန်')
,(1906,3,1,'ဘယ်လက်ရုံးတပည့်။ လက်ဝဲရံတပည့်။',null)
,(1907,3,1,'ကျောင်းသား။',null)
,(1908,3,1,'ကောလိပ်ကျောင်းသား။',null)
,(1909,3,1,'တက္ကသိုလ်ကျောင်းသား။',null)
,(1910,3,1,'အထက်တန်းကျောင်းသား။',null)
,(1911,3,1,'ဘုန်းကြီးကျောင်းသား။',null)
,(1912,3,1,'ညာလက်ရုံးတပည့်။ လက်ယာရံတပည့်။',null)
,(1913,3,1,'၁။ ချိတ်ဆွဲသည်။','“ကၞုဟ်မာဒၟံၚ်လၟဂွံ စုတ်ထိုၚ်ကွက်လဝ် ပ္ဍဲဂဂဵုဆုမွဲရ။” (ဇ—၂ဝ၆။ အစွောံ။) = “မုဆိုးသည် လိပ်ကိုယူ၍ အိတ်­ထည့်၍ တခုသောသစ်ၚုတ်­ ဆွဲ၏။” (ညောင်ကန်) || “ဍေံကွက်လဝ်ပရှ်ေ ကဵုဂစေံတံကၠုၚ်ဒီု—။” (ဇ—၂၇၄။ အစွောံ။) = “ခြင်းတောင်းကို ချိတ်ဆွဲ၍ ငှက်တို့ကို လာနားခိုစေ၏။”')
,(1913,3,1,'၂။ မွန်စာရေးထုံးတွင် အဆွဲဆယ်မျိုးအနက် တစ်ခုခုကို ဆွဲ၍ရေးသားသည်။','“ပ္ဍဲအခဝ်(က)ဂှ် ကွက်စုတ်(ဝ)မ္ဂး ဒှ်ကၠုၚ်(ကွ)ရ။” = “(က)အက္ခ ရာတွင် (ဝ)ဆွဲလိုက်လျှင် (ကွ)ကိုရသည်။” || ‘ကၟက်’ (န) လည်းရှု။')
,(1914,3,4,'တွဲလျားဆွဲသည်။ ချိတ်ဆွဲသည်။','“ပ္ကဴဇၟန်ကဵုကွက်တလာဲတလာဲလဝ်။” (ဇ— ၂၅၄။ အစွောံ။) = “ပန်းဆိုင်းတို့ကို တွဲလျားကျအောင် ချိတ်ဆွဲထားကုန်၏။” “ကမၠတ်ဝွံ ပိုဲ ဟွံဂွံဍေံရမၞးတံ။ ဗတ်ရပိုဲသ္ဂောံဒၞာဲဝွံဂှ် ဗာ်ကၞာၚ်သၠီတုဲ သြံၚ်ဂစိုတ်ကွက်တလာဲလဝ် ကဵုကၞာၚ်သၠီဝွံတုဲ စဴအာရ” မၞိဟ်တံဂှ်ဂး။ (ဇ—၃၁၁။ အစွောံ။) = “အချင်းတို့၊ ခိုးသူကို ငါတို့မမိနိုင်တော့ပြီ။ အကယ်၍ ဤနေရာ­ ဖမ်းမိခဲ့ငြားအံ့၊ တမာကိုင်းကိုခုတ်၍ တံကျင်လျှိုသတ်ပစ်ပြီးလျှင် ဤတမာ ကိုင်း­လျှင် (အလောင်းကို) တွဲလျားချိတ်ဆွဲထားကုန်၍ သွားအံ့။”')
,(1915,3,4,'လမ်းလျှောက်သည်။','‘တဝါ်’ (န) ရှု')
,(1916,3,4,'နှင့်နှိုင်းယှဉ်။',null)
,(1917,3,4,'စမ်းစမ်းလျှောက်သည်။',null)
,(1918,3,4,'ရှပ်တိုက်လျှောက်သည်။',null)
,(1919,3,4,'တရားဆုံးဖြတ်သူအဖြစ် ဆောင်ရွက်သည်။','“(ဒေဝတဴဖာ ဒှ်ဂလာန်ကဵုဒေ ဝတဴတၞံပြာန်) ဒေဝတဴဖာ အာဝေါန်စဝ်ဒေဝတဴဓိတာန် ကဵုတွာ်က္ဍိုပ်ဂဗုတ်ရ။” (သၠပတ်ဒ္ၚောဝ်သ ၜောံ) = “ပျဉ်းကတိုးပင်စောင့်နတ်နှင့် အငြင်းအခုံဖြစ်သော တောင်ပိနနဲပင်စောင့်နတ်သည် အင်ကြင်းပင်စောင့်နတ်အား သွားရောက်တောင်းပန်၍ တရားဆုံးဖြတ်သူအဖြစ် ဆောင်ရွက်စေ ၏။”')
